//! `Container` — one box that can size, pad, colour, round, border and shadow its child.

use frus::{BorderRadius, BoxDecoration, BoxShadow, Color, Colors, Container, Row, Text, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // The simplest use: a fixed size and a colour.
        Box::new(section(
            "Size and colour",
            Container::new()
                .width(120.0)
                .height(60.0)
                .color(Color::hex("#6366F1")),
        )),
        // Padding is inside the box, margin outside it; `radius` rounds the corners.
        Box::new(section(
            "Padding, margin and radius",
            Container::new()
                .padding(16.0)
                .margin(8.0)
                .radius(12.0)
                .color(Color::hex("#E0E7FF"))
                .child(Text::new("Padded content").color(Color::hex("#312E81"))),
        )),
        // A border, and a shadow under it.
        Box::new(section(
            "Border and shadow",
            Container::new()
                .padding(16.0)
                .radius(8.0)
                .color(Colors::WHITE)
                .border(1.0, Color::hex("#E4E4E7"))
                .shadows([BoxShadow::new(
                    0.0,
                    4.0,
                    12.0,
                    Color::rgba(0.0, 0.0, 0.0, 0.15),
                )])
                .child(Text::new("A card-like box").color(Color::hex("#09090B"))),
        )),
        // `decoration` takes the whole description at once — what a theme or a design
        // system would hand you.
        Box::new(section(
            "BoxDecoration",
            Row::new()
                .spacing(12.0)
                .child(
                    Container::new().width(64.0).height(64.0).decoration(
                        BoxDecoration::filled(Color::hex("#F59E0B"))
                            .radius(BorderRadius::uniform(32.0)),
                    ),
                )
                .child(Container::new().width(64.0).height(64.0).decoration(
                    BoxDecoration::filled(Color::hex("#10B981")).radius(BorderRadius::uniform(4.0)),
                )),
        )),
    ])
}

//! `Padding` — empty space around a child, and nothing else.

use frus::{Color, Container, Insets, InsetsDirectional, Padding, Text, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // A single number pads every side by the same amount.
        Box::new(section(
            "The same on every side",
            framed(Padding::new(24.0, label("24 px all round"))),
        )),
        // `Insets::symmetric(horizontal, vertical)`: wide and short, the shape of a button.
        Box::new(section(
            "Symmetric",
            framed(Padding::new(
                Insets::symmetric(32.0, 8.0),
                label("32 across, 8 down"),
            )),
        )),
        // `Insets::new(top, right, bottom, left)` sets each side on its own.
        Box::new(section(
            "Each side",
            framed(Padding::new(
                Insets::new(4.0, 8.0, 24.0, 48.0),
                label("4 / 8 / 24 / 48"),
            )),
        )),
        // Directional insets say "start" and "end" instead of left and right, so the
        // indent follows the reading direction: on the right in Arabic or Hebrew.
        Box::new(section(
            "Start and end",
            framed(Padding::new(
                InsetsDirectional::only_start(40.0),
                label("Indented at the start"),
            )),
        )),
    ])
}

/// The tinted box shows where the padding is: the label sits in a white box, the tint
/// around it is the padding.
fn framed(padding: Padding) -> Container {
    Container::new().color(Color::hex("#C7D2FE")).child(padding)
}

fn label(text: &str) -> Container {
    Container::new()
        .padding(8.0)
        .color(Color::hex("#FFFFFF"))
        .child(Text::new(text).color(Color::hex("#312E81")))
}

//! `Center` and `Aligned` — place one child somewhere inside the room it is given.

use frus::{
    Aligned, Alignment, AlignmentDirectional, Center, Color, Container, Text, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // `Center` takes all the room it is offered and puts its child in the middle.
        Box::new(section("Center", frame(Center::new(dot("center"))))),
        // `Aligned` does the same at any of the nine named spots — or anywhere between
        // them: `Alignment::new(x, y)` runs from -1 (left/top) to 1 (right/bottom).
        Box::new(section(
            "Aligned",
            Wrap::new()
                .gap(12.0)
                .run_gap(12.0)
                .child(frame(Aligned::new(Alignment::TOP_LEFT, dot("top left"))))
                .child(frame(Aligned::new(
                    Alignment::BOTTOM_RIGHT,
                    dot("bottom right"),
                )))
                .child(frame(Aligned::new(
                    Alignment::new(0.5, -0.5),
                    dot("(0.5, -0.5)"),
                ))),
        )),
        // Directional alignment says "start" and "end": the child moves to the right in a
        // right-to-left language without any change to the code.
        Box::new(section(
            "Directional",
            frame(Aligned::new(
                AlignmentDirectional::CENTER_END,
                dot("center end"),
            )),
        )),
        // A size factor makes the box a multiple of its child instead of taking the whole
        // room: here twice as wide and three times as tall as the label.
        Box::new(section(
            "Size factors",
            Container::new().color(Color::hex("#E0E7FF")).child(
                Center::new(dot("2× wide, 3× tall"))
                    .width_factor(2.0)
                    .height_factor(3.0),
            ),
        )),
    ])
}

/// A fixed box, so you can see where inside it the child ends up.
fn frame(child: impl Widget + 'static) -> Container {
    Container::new()
        .width(200.0)
        .height(120.0)
        .radius(8.0)
        .color(Color::hex("#E0E7FF"))
        .child(child)
}

fn dot(text: &str) -> Container {
    Container::new()
        .padding(6.0)
        .radius(6.0)
        .color(Color::hex("#4F46E5"))
        .child(Text::new(text).size(12.0).color(Color::hex("#FFFFFF")))
}

//! `Row` and `Column` — children in a line, across or down: the two containers most
//! screens are built from.

use frus::{
    Align, Alignment, Color, Column, Container, Justify, MainAxisSize, Row, Text, TextDirection,
    VerticalDirection, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // `spacing` puts the same gap between every pair of children — no spacer widgets.
        Box::new(section(
            "Row with spacing",
            Row::new()
                .spacing(8.0)
                .child(block("A", 48.0))
                .child(block("B", 48.0))
                .child(block("C", 48.0)),
        )),
        // A row fills the width it is given, so the main-axis alignment decides where the
        // free room goes: at the end, in the middle, or shared between the children.
        Box::new(section(
            "Main axis alignment",
            Column::new()
                .spacing(8.0)
                .child(lane(Justify::Start, "Start"))
                .child(lane(Justify::Center, "Center"))
                .child(lane(Justify::End, "End"))
                .child(lane(Justify::SpaceBetween, "SpaceBetween"))
                .child(lane(Justify::SpaceEvenly, "SpaceEvenly")),
        )),
        // The cross axis is the other direction. Children of different heights line up on
        // their tops, their centres (the default) or their bottoms, or all stretch to the
        // tallest one.
        Box::new(section(
            "Cross axis alignment",
            Row::new()
                .spacing(16.0)
                .child(tall_row(Align::Start, "Start"))
                .child(tall_row(Align::Center, "Center"))
                .child(tall_row(Align::End, "End"))
                .child(tall_row(Align::Stretch, "Stretch")),
        )),
        // `MainAxisSize::Min` makes the row only as wide as its children — the size you
        // want for a row that is itself placed by something else, such as a button's
        // icon and label.
        Box::new(section(
            "MainAxisSize::Min",
            Container::new().color(Color::hex("#E0E7FF")).child(
                Row::new()
                    .main_axis_size(MainAxisSize::Min)
                    .spacing(8.0)
                    .child(block("Shrink", 70.0))
                    .child(block("wrapped", 70.0)),
            ),
        )),
        // A column is the same thing downwards. `vertical_direction(Up)` stacks from the
        // bottom; a row's `text_direction(Rtl)` lays its children out right to left.
        Box::new(section(
            "Column, and both directions reversed",
            Row::new()
                .spacing(24.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    Column::new()
                        .spacing(4.0)
                        .child(block("1", 48.0))
                        .child(block("2", 48.0))
                        .child(block("3", 48.0)),
                )
                .child(
                    Column::new()
                        .spacing(4.0)
                        .vertical_direction(VerticalDirection::Up)
                        .child(block("1", 48.0))
                        .child(block("2", 48.0))
                        .child(block("3", 48.0)),
                )
                .child(
                    Row::new()
                        .main_axis_size(MainAxisSize::Min)
                        .spacing(4.0)
                        .text_direction(TextDirection::Rtl)
                        .child(block("1", 40.0))
                        .child(block("2", 40.0))
                        .child(block("3", 40.0)),
                ),
        )),
    ])
}

/// A full-width row of three blocks, aligned along its length by `justify`.
fn lane(justify: Justify, name: &str) -> Container {
    Container::new().color(Color::hex("#EEF2FF")).child(
        Row::new()
            .main_axis_alignment(justify)
            .spacing(4.0)
            .child(block(name, 110.0))
            .child(block("·", 32.0))
            .child(block("·", 32.0)),
    )
}

/// Three children of different heights, aligned across the row by `align`.
fn tall_row(align: Align, name: &str) -> Column {
    // Stretch only stretches a child that has no height of its own.
    let bar = |height: f32, color: &str| {
        let bar = Container::new().width(16.0).color(Color::hex(color));
        if align == Align::Stretch {
            bar
        } else {
            bar.height(height)
        }
    };
    Column::new()
        .spacing(4.0)
        .child(Text::new(name).size(12.0))
        .child(
            Container::new()
                .height(80.0)
                .color(Color::hex("#EEF2FF"))
                .child(
                    Row::new()
                        .main_axis_size(MainAxisSize::Min)
                        .cross_axis_alignment(align)
                        .spacing(4.0)
                        .child(bar(24.0, "#6366F1"))
                        .child(bar(48.0, "#4F46E5"))
                        .child(bar(36.0, "#818CF8")),
                ),
        )
}

fn block(label: &str, width: f32) -> Container {
    Container::new()
        .width(width)
        .height(36.0)
        .radius(6.0)
        .color(Color::hex("#6366F1"))
        .alignment(Alignment::CENTER)
        .child(Text::new(label).size(13.0).color(Color::hex("#FFFFFF")))
}

//! `Flex` — the flexbox container under `Row` and `Column`: a line of children that
//! shrink-wraps, stretches them across, and can wrap or run in reverse.
//!
//! Reach for `Row`/`Column` first. `Flex` is for when you want flexbox's own rules: a
//! container as big as its content, children stretched across it, `gap` and padding
//! built in.

use frus::{Align, Color, Container, Flex, Justify, Text, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // A flex row is as wide as its children; `gap` spaces them and `padding` pads the
        // whole line.
        Box::new(section(
            "Row with gap and padding",
            tinted(
                Flex::row()
                    .gap(8.0)
                    .padding(8.0)
                    .child(chip("one"))
                    .child(chip("two"))
                    .child(chip("three")),
            ),
        )),
        // Children are stretched across the line by default — here, to the tallest one.
        // `align` picks another cross-axis position.
        Box::new(section(
            "Stretched across (the default) and centred",
            Flex::row()
                .gap(24.0)
                .child(tinted(
                    Flex::row().gap(4.0).child(chip("short")).child(tall_chip()),
                ))
                .child(tinted(
                    Flex::row()
                        .gap(4.0)
                        .align(Align::Center)
                        .child(chip("short"))
                        .child(tall_chip()),
                )),
        )),
        // With a fixed width, `justify` distributes the spare room along the line.
        Box::new(section(
            "Fixed width, justified",
            tinted(
                Flex::row()
                    .width(300.0)
                    .justify(Justify::SpaceBetween)
                    .padding(8.0)
                    .child(chip("left"))
                    .child(chip("middle"))
                    .child(chip("right")),
            ),
        )),
        // `reverse` lays the children out from the far end — a chat transcript that
        // grows upwards is a reversed column.
        Box::new(section(
            "Reversed column",
            tinted(
                Flex::column()
                    .reverse()
                    .gap(4.0)
                    .padding(8.0)
                    .child(chip("first child"))
                    .child(chip("second child"))
                    .child(chip("third child")),
            ),
        )),
        // `wrap` moves what does not fit onto a new line; `run_gap` spaces the lines.
        Box::new(section(
            "Wrapping",
            tinted(
                (1..=12).fold(
                    Flex::row()
                        .wrap()
                        .width(280.0)
                        .gap(6.0)
                        .run_gap(6.0)
                        .padding(8.0),
                    |flex, i| flex.child(chip(&format!("item {i}"))),
                ),
            ),
        )),
    ])
}

fn tinted(child: impl Widget + 'static) -> Container {
    Container::new()
        .radius(8.0)
        .color(Color::hex("#E0E7FF"))
        .child(child)
}

fn chip(label: &str) -> Container {
    Container::new()
        .padding_each(6.0, 10.0, 6.0, 10.0)
        .radius(6.0)
        .color(Color::hex("#6366F1"))
        .child(Text::new(label).size(13.0).color(Color::hex("#FFFFFF")))
}

fn tall_chip() -> Container {
    Container::new()
        .padding(10.0)
        .height(72.0)
        .radius(6.0)
        .color(Color::hex("#4338CA"))
        .child(Text::new("tall").size(13.0).color(Color::hex("#FFFFFF")))
}

//! `Expanded`, `Flexible` and `Spacer` — share the free room of a `Row` or a `Column`
//! between some of its children.

use frus::{Alignment, Color, Container, Expanded, Flexible, Row, Spacer, Text, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // `Expanded` takes whatever room the fixed children leave: the classic "label
        // fills, button keeps its size" row.
        Box::new(section(
            "Expanded fills the rest",
            Row::new()
                .spacing(8.0)
                .child(fixed("fixed"))
                .child(Expanded::new(filler("Expanded", "#6366F1")))
                .child(fixed("fixed")),
        )),
        // Several expanded children split the room by their `flex` factors: 1 : 2 : 1.
        Box::new(section(
            "Flex factors",
            Row::new()
                .spacing(8.0)
                .child(Expanded::new(filler("1", "#818CF8")))
                .child(Expanded::new(filler("2", "#6366F1")).flex(2.0))
                .child(Expanded::new(filler("1", "#818CF8"))),
        )),
        // `Flexible` may take up to its share but does not have to: a short child keeps
        // its own width. `Expanded` beside it gets what the flexible one did not use.
        Box::new(section(
            "Flexible keeps its own size",
            Row::new()
                .spacing(8.0)
                .child(Flexible::new(
                    Container::new()
                        .padding(8.0)
                        .color(Color::hex("#F59E0B"))
                        .child(Text::new("Flexible").color(Color::hex("#FFFFFF"))),
                ))
                .child(Expanded::new(filler("Expanded", "#6366F1"))),
        )),
        // A long text in a `Flexible` wraps instead of pushing its neighbours off the
        // row — the usual cure for a row that overflows.
        Box::new(section(
            "Flexible wraps long text",
            Row::new()
                .spacing(8.0)
                .child(fixed("icon"))
                .child(Flexible::new(
                    Text::new(
                        "A long description that would run past the edge of the row if it \
                         were not allowed to wrap inside a Flexible.",
                    )
                    .wrap(),
                )),
        )),
        // `Spacer` is an empty `Expanded`: it pushes what follows it to the end.
        Box::new(section(
            "Spacer",
            Container::new()
                .padding(8.0)
                .color(Color::hex("#EEF2FF"))
                .child(
                    Row::new()
                        .child(fixed("left"))
                        .child(Spacer::new())
                        .child(fixed("right")),
                ),
        )),
    ])
}

fn fixed(label: &str) -> Container {
    Container::new()
        .width(64.0)
        .height(40.0)
        .radius(6.0)
        .color(Color::hex("#10B981"))
        .alignment(Alignment::CENTER)
        .child(Text::new(label).size(13.0).color(Color::hex("#FFFFFF")))
}

fn filler(label: &str, color: &str) -> Container {
    Container::new()
        .height(40.0)
        .radius(6.0)
        .color(Color::hex(color))
        .alignment(Alignment::CENTER)
        .child(Text::new(label).size(13.0).color(Color::hex("#FFFFFF")))
}

//! `SizedBox` — a box of a given size: to size its child, or, empty, as a fixed gap.

use frus::{Alignment, Color, Container, Row, SizedBox, Text, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // A fixed width and height forces the child to that size.
        Box::new(section(
            "Width and height",
            SizedBox::new(filler("160 × 48")).width(160.0).height(48.0),
        )),
        // `square` is the same on both axes — an avatar, an icon slot.
        Box::new(section("Square", SizedBox::square(64.0, filler("64")))),
        // An empty one is a fixed gap: between two children of a row that has no
        // `spacing`, for instance.
        Box::new(section(
            "Empty, as a gap",
            Row::new()
                .child(SizedBox::square(40.0, filler("A")))
                .child(SizedBox::empty().width(48.0))
                .child(SizedBox::square(40.0, filler("B"))),
        )),
        // A fraction of the room its parent has: half of a 300 px frame.
        Box::new(section(
            "Fraction of the width",
            Container::new()
                .width(300.0)
                .border(1.0, Color::hex("#A5B4FC"))
                .child(
                    SizedBox::new(filler("half the frame"))
                        .width_fraction(0.5)
                        .height(40.0),
                ),
        )),
        // `expand` takes all the room it is offered; `shrink` takes only what its child
        // needs, inside a parent that would otherwise stretch it.
        Box::new(section(
            "Expand and shrink",
            Row::new()
                .spacing(12.0)
                .child(frame(SizedBox::expand(tag("expand"))))
                .child(frame(SizedBox::shrink(tag("shrink")))),
        )),
    ])
}

fn frame(child: impl Widget + 'static) -> Container {
    Container::new()
        .width(140.0)
        .height(64.0)
        .border(1.0, Color::hex("#A5B4FC"))
        .child(child)
}

fn filler(label: &str) -> Container {
    Container::new()
        .color(Color::hex("#6366F1"))
        .alignment(Alignment::CENTER)
        .child(Text::new(label).size(13.0).color(Color::hex("#FFFFFF")))
}

/// A label with no size of its own: it is as big as whatever sizes it.
fn tag(label: &str) -> Container {
    Container::new()
        .padding(8.0)
        .color(Color::hex("#6366F1"))
        .child(Text::new(label).size(13.0).color(Color::hex("#FFFFFF")))
}

//! `ConstrainedBox`, `LimitedBox`, `IntrinsicWidth` and `IntrinsicHeight` — change how
//! big a child is allowed to be, rather than setting its size outright.

use frus::{
    Align, Color, ColoredBox, Column, ConstrainedBox, Container, IntrinsicHeight, IntrinsicWidth,
    LimitedBox, Padding, Row, SizedBox, Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // A floor: the box is at least 120 px wide however short its label, the way
        // buttons keep a minimum width. The tint shows the box.
        Box::new(section(
            "Minimum width",
            Row::new()
                .spacing(8.0)
                .child(floor("OK"))
                .child(floor("A longer label")),
        )),
        // A ceiling: a paragraph never gets wider than 240 px, however wide the page — a
        // comfortable reading measure.
        Box::new(section(
            "Maximum width",
            ConstrainedBox::new(
                Text::new(
                    "This paragraph is capped at 240 px wide, so its lines stay short enough \
                     to read comfortably even on a wide window.",
                )
                .wrap(),
            )
            .max_width(240.0),
        )),
        // `tight` makes the box exactly that size, whatever the child would like.
        Box::new(section(
            "Tight",
            ConstrainedBox::tight(180.0, 48.0, pill("exactly 180 × 48")),
        )),
        // `LimitedBox` only caps an axis that has no end. This page scrolls, so its height
        // has none: a box that asks for all the room is held to 80 px. Where the room is
        // bounded the limit does nothing.
        Box::new(section(
            "LimitedBox in a scrolling page",
            LimitedBox::new(SizedBox::expand(
                Container::new()
                    .color(Color::hex("#C7D2FE"))
                    .child(Text::new("held to 80 px").color(Color::hex("#312E81"))),
            ))
            .max_height(80.0),
        )),
        // `IntrinsicWidth` sizes a column to its widest child, and the stretched children
        // all take that width: a menu whose items are all as wide as the longest one.
        Box::new(section(
            "IntrinsicWidth",
            IntrinsicWidth::width(
                Column::new()
                    .spacing(4.0)
                    .cross_axis_alignment(Align::Stretch)
                    .child(pill("Open"))
                    .child(pill("Save as…"))
                    .child(pill("Export to PDF")),
            ),
        )),
        // `IntrinsicHeight` does the same downwards: the side bar matches the height of
        // the text beside it, whatever that turns out to be.
        Box::new(section(
            "IntrinsicHeight",
            IntrinsicHeight::height(
                Row::new()
                    .spacing(8.0)
                    .cross_axis_alignment(Align::Stretch)
                    .child(Container::new().width(4.0).color(Color::hex("#6366F1")))
                    .child(
                        Text::new(
                            "A quoted line,\nas tall as it needs to be,\nwith a bar beside it.",
                        )
                        .wrap(),
                    ),
            ),
        )),
    ])
}

fn pill(label: &str) -> Container {
    Container::new()
        .padding(10.0)
        .radius(6.0)
        .color(Color::hex("#6366F1"))
        .child(Text::new(label).size(13.0).color(Color::hex("#FFFFFF")))
}

/// A label in a box with a 120 px floor; the tint is the box, not the label.
fn floor(label: &str) -> ColoredBox {
    ColoredBox::new(
        Color::hex("#C7D2FE"),
        ConstrainedBox::new(Padding::new(
            10.0,
            Text::new(label).size(13.0).color(Color::hex("#312E81")),
        ))
        .min_width(120.0),
    )
}

//! `UnconstrainedBox`, `OverflowBox`, `SizedOverflowBox` and `ConstraintsTransformBox` —
//! let a child be a size its parent did not offer.

use frus::{
    Alignment, AxisConstraint, Color, ConstraintsTransformBox, Container, MainAxisSize,
    OverflowBox, Row, SizedOverflowBox, Text, UnconstrainedBox, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // A fixed-size container stretches its child to fill it (left). Wrapped in an
        // `UnconstrainedBox`, the child keeps its natural size instead (right).
        Box::new(section(
            "UnconstrainedBox",
            Wrap::new()
                .gap(12.0)
                .run_gap(12.0)
                .child(frame(tag("stretched")))
                .child(frame(UnconstrainedBox::new(tag("natural size")))),
        )),
        // `OverflowBox` lays its child out at a size of its own and lets it spill past
        // the box without moving anything around it. It does not clip.
        Box::new(section(
            "OverflowBox",
            Container::new().padding(24.0).child(
                Container::new()
                    .width(80.0)
                    .height(40.0)
                    .color(Color::hex("#C7D2FE"))
                    .child(
                        OverflowBox::new(
                            Container::new()
                                .radius(8.0)
                                .border(2.0, Color::hex("#4F46E5")),
                        )
                        .width(120.0)
                        .height(72.0),
                    ),
            ),
        )),
        // `SizedOverflowBox` takes a stated size in the layout (a 24 px slot here) and
        // shows a bigger child in it, anchored by its alignment.
        Box::new(section(
            "SizedOverflowBox",
            Container::new().padding(16.0).child(
                Row::new()
                    .main_axis_size(MainAxisSize::Min)
                    .child(tag("before"))
                    .child(
                        SizedOverflowBox::new(
                            24.0,
                            24.0,
                            Container::new()
                                .width(40.0)
                                .height(40.0)
                                .radius(20.0)
                                .color(Color::hex("#F59E0B")),
                        )
                        .alignment(Alignment::CENTER),
                    )
                    .child(tag("after")),
            ),
        )),
        // The general form: say per axis what the child is given. Here the child gets a
        // fixed 140 px across, whatever the page offers, and its natural height down.
        Box::new(section(
            "ConstraintsTransformBox",
            ConstraintsTransformBox::new(
                Container::new()
                    .padding(8.0)
                    .color(Color::hex("#E0E7FF"))
                    .child(Text::new("Laid out at exactly 140 px wide, wrapping.").wrap()),
            )
            .width(AxisConstraint::Fixed(140.0))
            .height(AxisConstraint::Unbounded)
            .alignment(Alignment::TOP_LEFT),
        )),
    ])
}

fn frame(child: impl Widget + 'static) -> Container {
    Container::new()
        .width(160.0)
        .height(72.0)
        .border(1.0, Color::hex("#A5B4FC"))
        .child(child)
