//! `FittedBox` — scales its child to fit its box, following a `BoxFit` rule.
//!
//! Unlike `Transform::scale`, the scale is worked out from the layout: put the same
//! child in a bigger box and it grows with it.

use frus::{Align, Alignment, BoxFit, Color, Column, Container, FittedBox, Text, Widget, Wrap};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // The same 80 × 40 badge in a 140 × 90 box under each rule. `Contain` shows all
        // of it, `Cover` fills the box and crops, `Fill` stretches it out of shape,
        // `ScaleDown` only ever shrinks, `None` leaves it at its own size.
        Box::new(section(
            "Each BoxFit",
            Wrap::new()
                .gap(12.0)
                .run_gap(12.0)
                .child(fitted("Contain", BoxFit::Contain))
                .child(fitted("Cover", BoxFit::Cover))
                .child(fitted("Fill", BoxFit::Fill))
                .child(fitted("FitWidth", BoxFit::FitWidth))
                .child(fitted("FitHeight", BoxFit::FitHeight))
                .child(fitted("ScaleDown", BoxFit::ScaleDown))
                .child(fitted("None", BoxFit::None)),
        )),
        // The everyday use: a label scaled to fill a slot whatever its own size — a big
        // figure on a dashboard tile.
        Box::new(section(
            "Growing a label to its slot",
            Container::new().border(1.0, Color::hex("#A5B4FC")).child(
                FittedBox::new(BoxFit::Contain)
                    .width(240.0)
                    .height(64.0)
                    .child(Text::new("1 234").size(14.0)),
            ),
        )),
    ])
}

fn fitted(name: &str, fit: BoxFit) -> Column {
    Column::new()
        .cross_axis_alignment(Align::Start)
        .spacing(4.0)
        .child(Text::new(name).size(12.0))
        .child(
            Container::new()
                .color(Color::hex("#EEF2FF"))
                .border(1.0, Color::hex("#A5B4FC"))
                .clip()
                .child(FittedBox::new(fit).width(140.0).height(90.0).child(badge())),
        )
}

fn badge() -> Container {
    Container::new()
        .width(80.0)
        .height(40.0)
        .radius(6.0)
        .color(Color::hex("#6366F1"))
        .alignment(Alignment::CENTER)
        .child(Text::new("80 × 40").size(13.0).color(Color::hex("#FFFFFF")))
}

//! `FractionallySizedBox` — a box sized as a fraction of the room its parent offers.

use frus::{
    component, Alignment, Color, Column, Container, Curve, FractionallySizedBox, Slider, Text,
    Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // Fractions of a fixed frame: 75 % of the width, 50 % of the height.
        Box::new(section(
            "Width and height factors",
            Container::new()
                .width(280.0)
                .height(120.0)
                .color(Color::hex("#EEF2FF"))
                .child(
                    FractionallySizedBox::new()
                        .width_factor(0.75)
                        .height_factor(0.5)
                        .child(fill("75 % × 50 %")),
                ),
        )),
        // Live: drag the slider and the bar takes that share of the width. `animated`
        // makes it glide to each new size instead of jumping — a progress bar.
        Box::new(section("Animated, driven by state", live_bar())),
    ])
}

/// A component keeps the slider's value between frames (`use_state`); every change
/// rebuilds it with the new factor.
fn live_bar() -> impl Widget {
    component(|cx| {
        let share = cx.use_state(|| 0.4_f32);
        let current = share.get();
        Box::new(
            Column::new()
                .spacing(8.0)
                .child(
                    Container::new()
                        .width(280.0)
                        .height(32.0)
                        .radius(6.0)
                        .color(Color::hex("#EEF2FF"))
                        .child(
                            FractionallySizedBox::new()
                                .width_factor(current)
                                .animated(0.25, Curve::ease_out())
                                .child(fill(&format!("{:.0} %", current * 100.0))),
                        ),
                )
                .child(
                    Slider::new(current)
                        .width(280.0)
                        .on_change(move |value| share.set(value)),
                ),
        )
    })
}

fn fill(label: &str) -> Container {
    Container::new()
        .radius(6.0)
        .color(Color::hex("#6366F1"))
        .alignment(Alignment::CENTER)
        .child(Text::new(label).size(13.0).color(Color::hex("#FFFFFF")))
}

//! `Wrap` and `ListBody` — a row that flows onto new lines when it runs out of room,
//! and a plain list of children one after the other.

use frus::{AlignContent, Color, Container, Justify, ListBody, Text, Widget, Wrap};

use crate::common::shared::{section, sections};

const TAGS: [&str; 10] = [
    "rust",
    "layout",
    "widgets",
    "desktop",
    "android",
    "web",
    "themes",
    "text",
    "gestures",
    "animation",
];

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // Tags, filters, chips: as many per line as fit, the rest on the next line.
        // `gap` spaces them along a line, `run_gap` spaces the lines. Narrow the window
        // and watch them reflow.
        Box::new(section(
            "Tags that reflow",
            TAGS.iter()
                .fold(Wrap::new().gap(8.0).run_gap(8.0), |wrap, tag| {
                    wrap.child(chip(tag))
                }),
        )),
        // In a fixed width, `justify` places each line's items and `align_lines` places
        // the lines in the box.
        Box::new(section(
            "Centred lines",
            Container::new().color(Color::hex("#EEF2FF")).child(
                TAGS.iter().fold(
                    Wrap::new()
                        .width(260.0)
                        .padding(8.0)
                        .gap(6.0)
                        .run_gap(6.0)
                        .justify(Justify::Center)
                        .align_lines(AlignContent::Center),
                    |wrap, tag| wrap.child(chip(tag)),
                ),
            ),
        )),
        // `ListBody` lays its children out one after the other along an axis, each at
        // its own size — the body of a list without the scrolling.
        Box::new(section(
            "ListBody",
            ListBody::vertical()
                .gap(4.0)
                .child(row("First entry"))
                .child(row("Second entry"))
                .child(row("Third entry")),
        )),
    ])
}

fn chip(label: &str) -> Container {
    Container::new()
        .padding_each(6.0, 12.0, 6.0, 12.0)
        .radius(16.0)
        .color(Color::hex("#6366F1"))
        .child(Text::new(label).size(13.0).color(Color::hex("#FFFFFF")))
}

fn row(label: &str) -> Container {
    Container::new()
        .padding(10.0)
        .radius(6.0)
        .border(1.0, Color::hex("#C7D2FE"))
        .child(Text::new(label))
}

//! `IndexedStack` — several children in one box, only one of them shown: the panels of
//! a tab set, the steps of a wizard.
//!
//! The box is as big as the biggest child, so switching panels does not make the page
//! jump.

use frus::{
    component, Align, Alignment, Color, Column, Container, IndexedStack, SegmentedButton, Text,
    Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![Box::new(section("Switching panels", panels()))])
}

/// The selected index is state: a component keeps it between frames, and the segmented
/// button changes it.
fn panels() -> impl Widget {
    component(|cx| {
        let selected = cx.use_state(|| 0_usize);
        let index = selected.get();
        // A segmented button reports the segment that was tapped; the closure stores it.
        let on_select = move |segment: usize| selected.set(segment);
        Box::new(
            Column::new()
                .cross_axis_alignment(Align::Start)
                .spacing(12.0)
                .child(
                    SegmentedButton::new(index, on_select)
                        .segment("Inbox")
                        .segment("Drafts")
                        .segment("Archive"),
                )
                .child(
                    IndexedStack::new(index)
                        .child(panel("Inbox", "3 unread messages", "#6366F1", 80.0))
                        .child(panel("Drafts", "Nothing saved yet", "#F59E0B", 140.0))
                        .child(panel("Archive", "128 messages", "#10B981", 110.0)),
                ),
        )
    })
}

/// Panels of different heights: the stack keeps the tallest one's height for all of them.
fn panel(title: &str, body: &str, color: &str, height: f32) -> Container {
    Container::new()
        .width(280.0)
        .height(height)
        .padding(12.0)
        .radius(8.0)
        .color(Color::hex(color))
        .alignment(Alignment::TOP_LEFT)
        .child(
            Column::new()
                .cross_axis_alignment(Align::Start)
                .spacing(4.0)
                .child(Text::new(title).size(18.0).color(Color::hex("#FFFFFF")))
                .child(Text::new(body).color(Color::hex("#FFFFFF"))),
        )
}

//! `Baseline`, `IgnoreBaseline` and `Align::Baseline` — line text up on the line its
//! letters sit on, not on the tops or middles of the boxes.

use frus::{
    Align, Baseline, Border, BorderSide, Color, Container, IgnoreBaseline, MainAxisSize, Row,
    Stack, Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // Centred, a big number and its small unit do not read as one line: the unit
        // floats halfway up.
        Box::new(section("Centred (the default)", price(Align::Center))),
        // On their baselines they share a line, whatever their sizes.
        Box::new(section("Align::Baseline", price(Align::Baseline))),
        // A row aligned on baselines follows the lowest one it finds. `IgnoreBaseline`
        // takes a piece out of the reckoning — here, the badge's text, which would
        // otherwise drag the line down to its own.
        Box::new(section(
            "IgnoreBaseline",
            Row::new()
                .main_axis_size(MainAxisSize::Min)
                .cross_axis_alignment(Align::Baseline)
                .spacing(8.0)
                .child(Text::new("Release notes").size(22.0))
                .child(
                    IgnoreBaseline::new().child(
                        Container::new()
                            .padding_each(2.0, 6.0, 2.0, 6.0)
                            .radius(4.0)
                            .color(Color::hex("#F59E0B"))
                            .child(Text::new("beta").size(11.0).color(Color::hex("#FFFFFF"))),
                    ),
                ),
        )),
        // `Baseline` puts its child's baseline a set distance below its top — to pin a
        // label to a rule drawn elsewhere. The grey line is 32 px down; so is the text's
        // baseline.
        Box::new(section(
            "Baseline at 32 px",
            Stack::new()
                .layer(
                    Container::new()
                        .width(220.0)
                        .height(32.0)
                        .box_border(Border {
                            bottom: BorderSide::new(Color::hex("#94A3B8"), 1.0),
                            ..Border::NONE
                        }),
                )
                .layer(Baseline::new(32.0).child(Text::new("Sits on the rule").size(18.0))),
        )),
    ])
}

fn price(align: Align) -> Row {
    Row::new()
        .main_axis_size(MainAxisSize::Min)
        .cross_axis_alignment(align)
        .spacing(4.0)
        .child(Text::new("42").size(48.0))
        .child(Text::new(".99").size(20.0))
        .child(Text::new("EUR / month").size(13.0))
}

//! `RotatedBox` — turns its child by whole quarter turns, and the layout turns with it.
//!
//! The difference from `Transform::rotate` is the layout: a rotated box swaps its width
//! and height, so its neighbours make room for the turned child. A transform only moves
//! the pixels, and the neighbours still see the unturned box.

use frus::{Align, Color, Container, Insets, MainAxisSize, Padding, RotatedBox, Row, Text, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // 0 to 3 quarter turns, clockwise. The odd ones are taller than wide.
        Box::new(section(
            "Quarter turns",
            Row::new()
                .main_axis_size(MainAxisSize::Min)
                .cross_axis_alignment(Align::Start)
                .spacing(12.0)
                .child(RotatedBox::new(0).child(label("0 turns")))
                .child(RotatedBox::new(1).child(label("1 turn")))
                .child(RotatedBox::new(2).child(label("2 turns")))
                .child(RotatedBox::new(3).child(label("3 turns"))),
        )),
        // The usual use: a vertical caption beside content, taking only the width of
        // one line.
        Box::new(section(
            "Vertical caption",
            Row::new()
                .main_axis_size(MainAxisSize::Min)
                .spacing(8.0)
                .child(RotatedBox::new(3).child(Padding::new(
                    Insets::symmetric(4.0, 0.0),
                    Text::new("SALES 2026").size(12.0),
                )))
                .child(
                    Container::new()
                        .width(200.0)
                        .height(100.0)
                        .radius(6.0)
                        .color(Color::hex("#E0E7FF")),
                ),
        )),
    ])
}

fn label(text: &str) -> Container {
    Container::new()
        .padding_each(6.0, 12.0, 6.0, 12.0)
        .radius(6.0)
        .color(Color::hex("#6366F1"))
