//! `SafeArea` — keeps its child clear of the parts of the screen the system has taken:
//! the status bar, a notch or camera cut-out, the gesture handle, the keyboard.
//!
//! On desktop those insets are zero and `SafeArea` changes nothing, so the same screen
//! code is right everywhere. Wrap the body of a page that draws edge to edge in one.

use frus::{Color, Container, Edges, Insets, SafeArea, Text, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // `build` hands you the screen's current metrics: here, the insets it is keeping
        // clear on this device. On a desktop window they are all zero.
        Box::new(section(
            "The insets on this device",
            SafeArea::build(|media| {
                let p = media.padding;
                Text::new(format!(
                    "top {:.0}, right {:.0}, bottom {:.0}, left {:.0}",
                    p.top, p.right, p.bottom, p.left
                ))
            }),
        )),
        // Every edge, plus a minimum padding of 12 px so the content never touches the
        // frame even where the system takes nothing.
        Box::new(section(
            "All edges, with a minimum",
            framed(
                SafeArea::new(content("Kept clear of every system bar"))
                    .minimum(Insets::uniform(12.0)),
            ),
        )),
        // A list that should run under the gesture handle drops the bottom edge; a form
        // adds `avoid_keyboard` to move up when the on-screen keyboard opens.
        Box::new(section(
            "Without the bottom edge, avoiding the keyboard",
            framed(
                SafeArea::new(content("Runs under the handle, rises above the keyboard"))
                    .edges(Edges::ALL.without_bottom())
                    .avoid_keyboard(),
            ),
        )),
    ])
}

fn framed(child: impl Widget + 'static) -> Container {
    Container::new()
        .width(300.0)
        .color(Color::hex("#E0E7FF"))
        .child(child)
}

fn content(text: &str) -> Container {
    Container::new()
        .padding(10.0)
        .color(Color::hex("#6366F1"))
        .child(Text::new(text).color(Color::hex("#FFFFFF")).wrap())
}

//! `LayoutBuilder` and `OrientationBuilder` — build from the room actually given, not
//! from the window's size, so a component adapts wherever it is placed.
//!
//! The content is built on the fly every frame from the box: it keeps no state of its
//! own, so keep the closure cheap and put any state outside it.

use frus::{
    Align, Alignment, Color, Column, Container, Expanded, LayoutBuilder, Orientation,
    OrientationBuilder, Row, SizedBox, Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // The closure receives the size of its box. Resize the window to see the number
        // (and the layout) change.
        Box::new(section(
            "The box it was given",
            LayoutBuilder::new(|size| {
                Container::new()
                    .padding(12.0)
                    .color(Color::hex("#E0E7FF"))
                    .child(Text::new(format!("{:.0} px wide", size.width)))
            }),
        )),
        // The common use: one arrangement when there is room, another when there is not.
        // The same card, at two widths.
        Box::new(section(
            "Side by side when it fits",
            Column::new()
                .cross_axis_alignment(Align::Start)
                .spacing(12.0)
                .child(SizedBox::new(card()).width(320.0))
                .child(SizedBox::new(card()).width(200.0)),
        )),
        // `OrientationBuilder` answers the simpler question: is the box wider than tall?
        // Here it is asked about two fixed boxes.
        Box::new(section(
            "OrientationBuilder",
            Row::new()
                .spacing(12.0)
                .child(SizedBox::new(oriented()).width(160.0).height(90.0))
                .child(SizedBox::new(oriented()).width(90.0).height(160.0)),
        )),
    ])
}

/// A picture and a text: in a row from 260 px up, stacked below that.
fn card() -> LayoutBuilder {
    LayoutBuilder::new(|size| -> Box<dyn Widget> {
        let picture = Container::new()
            .width(80.0)
            .height(60.0)
            .radius(6.0)
            .color(Color::hex("#6366F1"));
        let caption =
            Text::new(format!("{:.0} px: ", size.width) + "a caption beside or under the picture")
                .wrap();
        if size.width >= 260.0 {
            Box::new(
                Row::new()
                    .spacing(12.0)
                    .child(picture)
                    .child(Expanded::new(caption)),
            )
        } else {
            Box::new(
                Column::new()
                    .cross_axis_alignment(Align::Start)
                    .spacing(8.0)
                    .child(picture)
                    .child(caption),
            )
        }
    })
}

fn oriented() -> LayoutBuilder {
    OrientationBuilder::new(|orientation| {
        let (label, color) = match orientation {
            Orientation::Landscape => ("Landscape", "#10B981"),
            Orientation::Portrait => ("Portrait", "#F59E0B"),
        };
        Container::new()
            .color(Color::hex(color))
            .alignment(Alignment::CENTER)
            .child(Text::new(label).color(Color::hex("#FFFFFF")))
    })
}

//! `CustomMultiChildLayout` — children measured and placed by a function you write, for
//! arrangements no row, column or stack can express.
//!
//! Each child is named by a key. The function gets the layout's size, measures each
//! child under constraints it chooses (`layout_child`), and says where it goes
//! (`position_child`). A child can be measured before another is placed, so one can be
//! put against another's size.

use frus::{
    ChildAxis, ChildConstraints, Color, Container, CustomMultiChildLayout, Point, Size, Text,
    Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // A label that hangs off the corner of whatever it annotates: its place depends
        // on the box's measured size, which only a custom layout can know in advance.
        Box::new(section(
            "A note pinned to a box's corner",
            CustomMultiChildLayout::new(|size, layout| {
                let card = layout.layout_child(
                    "card",
                    ChildConstraints::loose(Size::new(size.width.min(220.0), size.height)),
                );
                layout.position_child("card", Point::new(0.0, 16.0));
                // The note is placed from the card's size: its top-right corner.
                let note = layout.layout_child("note", ChildConstraints::free());
                layout.position_child(
                    "note",
                    Point::new(card.width - note.width / 2.0, 16.0 - note.height / 2.0),
                );
            })
            // The layout's own size does not depend on its children: give it one.
            .width(280.0)
            .height(110.0)
            .child(
                "card",
                Container::new()
                    .padding(16.0)
                    .radius(8.0)
                    .color(Color::hex("#E0E7FF"))
                    .child(Text::new("Quarterly report\nDue on Friday").wrap()),
            )
            .child(
                "note",
                Container::new()
                    .padding_each(2.0, 8.0, 2.0, 8.0)
                    .radius(10.0)
                    .color(Color::hex("#EF4444"))
                    .child(Text::new("late").size(12.0).color(Color::hex("#FFFFFF"))),
            ),
        )),
        // A staircase: each step starts where the previous one ended, exactly 96 px
        // wide. `ChildAxis` sets each axis on its own.
        Box::new(section(
            "Steps placed one after another",
            ["Plan", "Build", "Ship"].iter().enumerate().fold(
                CustomMultiChildLayout::new(|_size, layout| {
                    let mut at = Point::new(0.0, 0.0);
                    for key in 0..3_usize {
                        let step = layout.layout_child(
                            key,
                            ChildConstraints::free().width(ChildAxis::Exactly(96.0)),
                        );
                        layout.position_child(key, at);
                        at = Point::new(at.x + step.width, at.y + step.height);
                    }
                })
                .width(300.0)
                .height(120.0),
                |layout, (key, label)| {
                    layout.child(
                        key,
                        Container::new()
                            .padding(8.0)
                            .color(Color::hex("#6366F1"))
                            .child(Text::new(*label).color(Color::hex("#FFFFFF"))),
                    )
                },
            ),
        )),
    ])
}

//! `OverflowBar` — a row of buttons that becomes a column when they stop fitting.
//!
//! Unlike `Wrap`, it folds all of its children or none: never a second line with one
//! button stranded on it. It is the bar for dialog actions, which must survive a larger
//! system font size.

use frus::{Align, Button, Color, Container, Justify, OverflowBar, Variant, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // Short labels with room enough: one line, pushed to the end as dialog actions
        // are.
        Box::new(section(
            "Fits on one line",
            framed(320.0, actions(["Cancel", "Keep", "Delete"])),
        )),
        // Longer labels in a narrower box: the buttons fold into a column, aligned at
        // the end, with `overflow_spacing` between them — never a squashed row.
        Box::new(section(
            "Too narrow: folds into a column",
            framed(
                240.0,
                actions(["Cancel", "Keep a copy", "Delete permanently"]),
            ),
        )),
    ])
}

fn actions([cancel, keep, delete]: [&str; 3]) -> OverflowBar {
    // A button with no `on_press` is disabled; these do nothing but stay enabled.
    OverflowBar::new()
        .spacing(8.0)
        .alignment(Justify::End)
        .overflow_spacing(4.0)
        .overflow_alignment(Align::End)
        .child(Button::new(cancel).variant(Variant::Text).on_press(|| ()))
        .child(Button::new(keep).variant(Variant::Outlined).on_press(|| ()))
        .child(Button::new(delete).on_press(|| ()))
}

fn framed(width: f32, bar: OverflowBar) -> Container {
    Container::new()
        .width(width)
        .padding(12.0)
        .radius(8.0)
        .border(1.0, Color::hex("#C7D2FE"))
        .child(bar)
}

//! `TwoPane` and `responsive` — adapt a screen to its size class: a list and its detail
//! side by side on a wide window, one at a time on a phone.
//!
//! The size class (`Compact` under 600 px, `Medium` up to 840, `Expanded` above) is a
//! plain value: take it from the window, or, as here, from the room a `LayoutBuilder`
//! reports — or from a switch, to show both arrangements on one screen.

use frus::{
    component, responsive, Align, Button, Color, Column, Container, Expanded, LayoutBuilder,
    OverflowBox, SegmentedButton, SizeClass, SizedBox, Text, TwoPane, Variant, Widget,
};

use crate::common::shared::{section, sections};

const MAILS: [(&str, &str); 4] = [
    ("Ada", "The engine notes are attached."),
    ("Grace", "Can we move the review to Monday?"),
    ("Linus", "Patch v3 is on the list."),
    ("Barbara", "Slides for Thursday's talk."),
];

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // Switch the size class: `Expanded` shows both panes, anything smaller shows the
        // list, or the detail once an item is opened (`show_detail`), with a way back.
        Box::new(section("TwoPane", mail())),
        // `responsive(width)` picks the variant for the width's size class, falling back
        // to the nearest one given. Resize the window to change it.
        Box::new(section(
            "responsive",
            LayoutBuilder::new(|size| {
                responsive(size.width)
                    .compact(badge("Compact layout", "#F59E0B"))
                    .medium(badge("Medium layout", "#6366F1"))
                    .expanded(badge("Expanded layout", "#10B981"))
            }),
        )),
    ])
}

fn mail() -> impl Widget {
    component(|cx| {
        let wide = cx.use_state(|| true);
        let open = cx.use_state(|| 0_usize);
        let showing_detail = cx.use_state(|| false);

        let class = if wide.get() {
            SizeClass::Expanded
        } else {
            SizeClass::Compact
        };

        // The list: tapping an item opens it.
        let list = MAILS.iter().enumerate().fold(
            Column::new().cross_axis_alignment(Align::Stretch),
            |list, (i, (from, _))| {
                let (open, showing_detail) = (open.clone(), showing_detail.clone());
                let selected = i == open.get();
                list.child(
                    Container::new()
                        .padding(12.0)
                        .color(if selected {
                            Color::hex("#E0E7FF")
                        } else {
                            Color::hex("#F8FAFC")
                        })
                        .on_click(move || {
                            open.set(i);
                            showing_detail.set(true);
                        })
                        .child(Text::new(*from).color(Color::hex("#0F172A"))),
                )
            },
        );

        let (from, body) = MAILS[open.get()];
        let back = showing_detail.clone();
        let detail = Container::new()
            .padding(16.0)
            .color(Color::hex("#FFFFFF"))
            .child(
                Column::new()
                    .spacing(8.0)
                    .cross_axis_alignment(Align::Start)
                    .child(Text::new(from).size(18.0).color(Color::hex("#0F172A")))
                    .child(Text::new(body).color(Color::hex("#334155")).wrap())
                    // Only the single-pane arrangement needs a way back to the list.
                    .child(if wide.get() {
                        Box::new(SizedBox::empty()) as Box<dyn Widget>
                    } else {
                        Box::new(
                            Button::new("Back to the list")
                                .variant(Variant::Text)
                                .on_press(move || back.set(false)),
                        )
                    }),
            );

        let on_select = move |segment: usize| wide.set(segment == 0);
        Box::new(
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    SegmentedButton::new(usize::from(class != SizeClass::Expanded), on_select)
                        .segment("Expanded")
                        .segment("Compact"),
                )
                // A two-pane shell fills the room it is given; in a scrolling page that
                // room has to be bounded.
                .child(
                    SizedBox::new(
                        Container::new().border(1.0, Color::hex("#CBD5E1")).child(
                            TwoPane::new(class)
                                .ratio(0.4)
                                .show_detail(showing_detail.get())
                                .list(pane(list))
                                .detail(pane(detail)),
                        ),
                    )
                    .width(320.0)
                    .height(200.0),
                ),
        )
    })
}

/// A pane's content, asking for no width of its own.
///
/// `TwoPane` lets each pane start from its content's natural width before it shares out
/// the room by `ratio`, so a long unwrapped line in the detail would push both panes
/// past the frame. `OverflowBox` takes no size from its child, and `Expanded` then grows
/// it to the whole pane, so the ratio alone decides the widths and the text wraps
/// inside them.
fn pane(content: impl Widget + 'static) -> Expanded {
    Expanded::new(OverflowBox::new(content))
}

fn badge(label: &str, color: &str) -> Container {
    Container::new()
        .padding(12.0)
        .radius(8.0)
        .color(Color::hex(color))
        .child(Text::new(label).color(Color::hex("#FFFFFF")))
}

//! `Placeholder` — a crossed box standing in for a widget you have not written yet, so
//! the shape of a layout is readable before any of it is built.

use frus::{Align, Color, Column, MainAxisSize, Placeholder, Row, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // `fallback` gives it a size of its own (400 × 400 unless told otherwise).
        Box::new(section(
            "A sized stand-in",
            Placeholder::new().fallback(200.0, 100.0),
        )),
        // Sketching a screen: a header, a side bar and a content area, before any of
        // them exist. The colour and the stroke width can be changed, to tell the parts
        // apart.
        Box::new(section(
            "Sketching a layout",
            Column::new()
                .spacing(8.0)
                .cross_axis_alignment(Align::Start)
                .child(Placeholder::new().fallback(300.0, 40.0))
                .child(
                    Row::new()
                        .main_axis_size(MainAxisSize::Min)
                        .spacing(8.0)
                        .child(
                            Placeholder::new()
                                .color(Color::hex("#F59E0B"))
                                .fallback(80.0, 140.0),
                        )
                        .child(
                            Placeholder::new()
                                .color(Color::hex("#6366F1"))
                                .stroke(1.0)
                                .fallback(212.0, 140.0),
                        ),
                ),
        )),
    ])
}

//! `Text` — a run of text in one style: size, weight, colour, slant, decoration,
//! alignment, wrapping and line limits are all set on the widget.

use frus::{
    Align, Color, Column, Container, FontWeight, Row, Text, TextAlign, TextDecoration,
    TextOverflow, Widget, Wrap,
};

use crate::common::shared::{section, sections};

const LONG: &str = "Text wraps at the width it is given. This sentence is long enough to need \
                    several lines in a narrow box, which is where alignment, line limits and \
                    ellipses start to matter.";

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // Unstyled, a text takes the theme's body style and colour, so it reads right in
        // light and dark mode without any setting.
        Box::new(section("Default", Text::new("Hello, frus!"))),
        // Sizes are logical pixels; they grow with the reader's system font size.
        Box::new(section(
            "Sizes",
            Wrap::new()
                .gap(16.0)
                .run_gap(8.0)
                .align(Align::Baseline)
                .child(Text::new("12 px").size(12.0))
                .child(Text::new("16 px").size(16.0))
                .child(Text::new("24 px").size(24.0))
                .child(Text::new("32 px").size(32.0)),
        )),
        Box::new(section(
            "Weights and italic",
            Wrap::new()
                .gap(16.0)
                .run_gap(8.0)
                .child(Text::new("Regular").weight(FontWeight::Regular))
                .child(Text::new("Medium").weight(FontWeight::Medium))
                .child(Text::new("SemiBold").weight(FontWeight::SemiBold))
                .child(Text::new("Bold").weight(FontWeight::Bold))
                .child(Text::new("Italic").italic()),
        )),
        // A fixed colour does not follow the theme: keep it for meaning (errors,
        // success), and let ordinary text inherit.
        Box::new(section(
            "Colours",
            Wrap::new()
                .gap(16.0)
                .run_gap(8.0)
                .child(Text::new("Indigo").color(Color::hex("#4F46E5")))
                .child(Text::new("Error").color(Color::hex("#DC2626")))
                .child(Text::new("Success").color(Color::hex("#16A34A"))),
        )),
        // Lines under, through or over the text; the line can have its own colour.
        Box::new(section(
            "Decoration",
            Wrap::new()
                .gap(16.0)
                .run_gap(8.0)
                .child(Text::new("Underline").underline())
                .child(Text::new("Strikethrough").strikethrough())
                .child(Text::new("Overline").decoration(TextDecoration::OVERLINE))
                .child(
                    Text::new("Red underline")
                        .underline()
                        .decoration_color(Color::hex("#DC2626")),
                ),
        )),
        // Alignment places the lines inside the text's box, so it shows when the box is
        // wider than the text: here, 300 px.
        Box::new(section(
            "Alignment",
            Column::new()
                .spacing(6.0)
                .child(boxed(Text::new("Start").align(TextAlign::Start)))
                .child(boxed(Text::new("Center").align(TextAlign::Center)))
                .child(boxed(Text::new("End").align(TextAlign::End)))
                .child(boxed(Text::new(LONG).align(TextAlign::Justify))),
        )),
        // A line limit, and what happens to the rest: an ellipsis, a fade, or a hard cut.
        Box::new(section(
            "Line limits",
            Column::new()
                .spacing(8.0)
                .child(boxed(Text::new(LONG).max_lines(2).ellipsis()))
                .child(boxed(
                    Text::new(LONG).max_lines(1).overflow(TextOverflow::Fade),
                ))
                .child(boxed(
                    Text::new(LONG).no_wrap().overflow(TextOverflow::Clip),
                )),
        )),
        // `height` sets the line height as a multiple of the size: 1.6 airs a paragraph
        // out, 1.0 packs it.
        Box::new(section(
            "Line height",
            Row::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    Container::new()
                        .width(150.0)
                        .child(Text::new(LONG).size(13.0).height(1.0)),
                )
                .child(
                    Container::new()
                        .width(150.0)
                        .child(Text::new(LONG).size(13.0).height(1.6)),
                ),
        )),
    ])
}

/// A 300 px box with a faint outline, so you can see the text's room.
fn boxed(text: Text) -> Container {
    Container::new()
        .width(300.0)
        .padding(6.0)
        .border(1.0, Color::hex("#CBD5E1"))
        .child(text)
}

//! `TextStyle` — a style as a value: define it once, share it, merge it, and hand it to
//! `Text::styled`, a `TextSpan` or a whole subtree with `DefaultTextStyle`.
//!
//! Every field of a style is optional. A style that only says "size 20" leaves the
//! weight and colour to whatever is around it — which is what makes styles layer.

use frus::{
    Align, Color, Column, DefaultTextStyle, FontWeight, Text, TextAlign, TextStyle, Widget,
};

use crate::common::shared::{section, sections};

/// A style shared by several texts: a `const`, since every builder is `const fn`.
const LABEL: TextStyle = TextStyle::new(12.0)
    .weight(FontWeight::SemiBold)
    .letter_spacing(1.2)
    .color(Color::rgb(0.39, 0.40, 0.95));

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // `Text::styled` takes a whole style at once.
        Box::new(section(
            "A shared style",
            Column::new()
                .cross_axis_alignment(Align::Start)
                .spacing(4.0)
                .child(Text::styled("SECTION ONE", LABEL))
                .child(Text::styled("SECTION TWO", LABEL)),
        )),
        // `merge` lays one style over another: what the second says wins, what it leaves
        // open is kept. Here, the label made bigger and red.
        Box::new(section(
            "Merging",
            Text::styled(
                "OVERRIDDEN",
                LABEL.merge(TextStyle::new(18.0).color(Color::hex("#DC2626"))),
            ),
        )),
        // Letter spacing and line height are part of the style.
        Box::new(section(
            "Letter spacing",
            Column::new()
                .cross_axis_alignment(Align::Start)
                .spacing(4.0)
                .child(Text::styled(
                    "tight",
                    TextStyle::new(18.0).letter_spacing(-1.0),
                ))
                .child(Text::styled("normal", TextStyle::new(18.0)))
                .child(Text::styled(
                    "wide",
                    TextStyle::new(18.0).letter_spacing(4.0),
                )),
        )),
        // `DefaultTextStyle::around` gives every text in a subtree a default — the way a
        // card or a toolbar styles all its text at once. A text's own settings still win.
        Box::new(section(
            "DefaultTextStyle for a subtree",
            DefaultTextStyle {
                style: TextStyle::new(15.0).italic().color(Color::hex("#0F766E")),
                align: Some(TextAlign::Start),
                ..DefaultTextStyle::NONE
            }
            .around(
                Column::new()
                    .cross_axis_alignment(Align::Start)
                    .spacing(4.0)
                    .child(Text::new("Inherits the italic teal default."))
                    .child(Text::new("So does this one."))
                    .child(Text::new("This one asks for bold.").weight(FontWeight::Bold)),
            ),
        )),
    ])
}

//! `RichText` and `TextSpan` — one paragraph in several styles: a bold word, a link-
//! coloured phrase, a price in two sizes.
//!
//! A `TextSpan` is a tree: each span has its own text and children, and a child
//! inherits whatever its parent's style says unless it says otherwise.

use frus::{
    Color, Container, FontFamily, FontWeight, RichText, TextAlign, TextDecoration, TextOverflow,
    TextSpan, TextStyle, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // The basics: plain text, then children that change one thing each.
        Box::new(section(
            "Mixed styles in one line",
            RichText::new(
                TextSpan::new("frus is ")
                    .child(TextSpan::new("fast").bold())
                    .child(TextSpan::new(", "))
                    .child(TextSpan::new("portable").italic())
                    .child(TextSpan::new(" and "))
                    .child(
                        TextSpan::new("yours")
                            .underline()
                            .color(Color::hex("#4F46E5")),
                    )
                    .child(TextSpan::new(".")),
            ),
        )),
        // Inheritance: the outer span sets size and colour once; the children only say
        // what differs.
        Box::new(section(
            "Inherited style",
            RichText::new(
                TextSpan::new("Total: ")
                    .style(TextStyle::new(16.0).color(Color::hex("#475569")))
                    .child(
                        TextSpan::new("€42")
                            .size(32.0)
                            .weight(FontWeight::Bold)
                            .color(Color::hex("#0F172A")),
                    )
                    .child(TextSpan::new(".99").size(18.0).color(Color::hex("#0F172A")))
                    .child(TextSpan::new(" / month")),
            ),
        )),
        // A whole span can carry a full `TextStyle` — here monospace for inline code —
        // and a decoration in a colour of its own.
        Box::new(section(
            "Inline code and a coloured strikethrough",
            RichText::new(
                TextSpan::new("Call ")
                    .child(
                        TextSpan::new("Text::new()")
                            .style(TextStyle::NONE.family(FontFamily::Monospace))
                            .color(Color::hex("#BE185D")),
                    )
                    .child(TextSpan::new(" instead of "))
                    .child(
                        TextSpan::new("label()")
                            .decoration(TextDecoration::STRIKETHROUGH)
                            .decoration_color(Color::hex("#DC2626")),
                    )
                    .child(TextSpan::new(".")),
            ),
        )),
        // A paragraph wraps, aligns and truncates like a `Text` does; the base style is
        // what every span starts from.
        Box::new(section(
            "A wrapped, centred paragraph",
            Container::new().width(300.0).child(
                RichText::new(
                    TextSpan::new("Rich text ")
                        .child(TextSpan::new("wraps").bold())
                        .child(TextSpan::new(
                            " at the width it is given, keeps each span's style across the \
                             line breaks, and can be ",
                        ))
                        .child(TextSpan::new("centred").italic())
                        .child(TextSpan::new(" or cut short after a number of lines.")),
                )
                .base_style(TextStyle::new(15.0).height(1.4))
                .align(TextAlign::Center)
                .max_lines(3)
                .overflow(TextOverflow::Ellipsis),
            ),
        )),
    ])
}

//! The text theme (`theme.text`) — the app's type scale: fifteen named styles from
//! `display_large` down to `label_small`, and `Text::heading` for titles.
//!
//! Use the scale instead of raw sizes, so every screen shares one hierarchy and a theme
//! change restyles the whole app.

use frus::{component, Align, Column, Text, TextStyle, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // A page title and a section title, from the scale. `heading()` changes nothing
        // drawn: it tells screen readers this is a title, so their users can jump between
        // headings.
        Box::new(section("Headings", headings())),
        Box::new(section("The whole scale", scale())),
    ])
}

/// The theme is read from the build context, so a component is needed to reach it.
fn headings() -> impl Widget {
    component(|cx| {
        let text = &cx.theme().text;
        Box::new(
            Column::new()
                .spacing(8.0)
                .cross_axis_alignment(Align::Start)
                .child(Text::styled("Account settings", text.headline_small).heading())
                .child(Text::styled("Notifications", text.title_medium).heading())
                .child(Text::styled(
                    "Choose which messages reach you, and how.",
                    text.body_medium,
                )),
        )
    })
}

fn scale() -> impl Widget {
    component(|cx| {
        let text = &cx.theme().text;
        let styles: [(&str, TextStyle); 15] = [
            ("display_large", text.display_large),
            ("display_medium", text.display_medium),
            ("display_small", text.display_small),
            ("headline_large", text.headline_large),
            ("headline_medium", text.headline_medium),
            ("headline_small", text.headline_small),
            ("title_large", text.title_large),
            ("title_medium", text.title_medium),
            ("title_small", text.title_small),
            ("body_large", text.body_large),
            ("body_medium", text.body_medium),
            ("body_small", text.body_small),
            ("label_large", text.label_large),
            ("label_medium", text.label_medium),
            ("label_small", text.label_small),
        ];
        let column = Column::new()
            .spacing(6.0)
            .cross_axis_alignment(Align::Start);
        // The display sizes are wide: let them wrap rather than run off a phone screen.
        Box::new(styles.into_iter().fold(column, |column, (name, style)| {
            column.child(Text::styled(name, style).wrap())
        }))
    })
}

//! `FontFamily` — which typeface a text is set in: the default sans-serif, a serif, the
//! monospace face, or a font you registered by name.

use frus::{Align, Column, FontFamily, Text, TextStyle, Widget};

use crate::common::shared::{section, sections};

const SAMPLE: &str = "The quick brown fox jumps over the lazy dog";

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // What text gets when it says nothing.
        Box::new(section(
            "SansSerif (the default)",
            Text::new(SAMPLE).family(FontFamily::SansSerif),
        )),
        // A serif face, where the platform or the application has one; otherwise the
        // default is used.
        Box::new(section(
            "Serif",
            Text::new(SAMPLE).family(FontFamily::Serif),
        )),
        // Monospace: every character the same width, so columns line up — code, keys,
        // tables of numbers.
        Box::new(section(
            "Monospace",
            Column::new()
                .cross_axis_alignment(Align::Start)
                .spacing(2.0)
                .child(Text::new("fn main() {").family(FontFamily::Monospace))
                .child(Text::new("    println!(\"hi\");").family(FontFamily::Monospace))
                .child(Text::new("}").family(FontFamily::Monospace))
                .child(Text::new("1 111.00").family(FontFamily::Monospace))
                .child(Text::new("   42.50").family(FontFamily::Monospace)),
        )),
        // Your own font: register its bytes once at start-up with
        // `frus::fonts::add_font(include_bytes!("../res/fonts/Brand.ttf").to_vec())`, then
        // name its family. A name that matches no font falls back to the default rather
        // than showing nothing — as this one does.
        Box::new(section(
            "Named (falls back when missing)",
            Text::styled(
                SAMPLE,
                TextStyle::NONE.family(FontFamily::Named("Brand Sans")),
            ),
        )),
    ])
}

//! `Text::selectable` and `SelectionArea` — text the reader can select and copy: one
//! text on its own, or a selection that runs across several.
//!
//! Text is not selectable by default: a label on a button should take the tap, not
//! start a selection. Make selectable what a reader may want to copy — an order
//! number, an address, an error message, an article.

use frus::{Align, Color, Column, Container, FontFamily, SelectionArea, Text, ToolbarItem, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // One selectable text: drag across it, double-click a word, or press Ctrl+A
        // once it has focus, then Ctrl+C. On a touch screen, long-press.
        Box::new(section(
            "One selectable text",
            Column::new()
                .cross_axis_alignment(Align::Start)
                .spacing(6.0)
                .child(Text::new("Your order number:"))
                .child(
                    Text::new("ORDER-4417-XK")
                        .family(FontFamily::Monospace)
                        .size(18.0)
                        .selectable(),
                ),
        )),
        // `SelectionArea` wraps a subtree, and the selection runs from one text into the
        // next, in reading order — select from the title into the second paragraph.
        Box::new(section(
            "A selection across several texts",
            Container::new()
                .width(320.0)
                .padding(12.0)
                .border(1.0, Color::hex("#CBD5E1"))
                .child(SelectionArea::around(
                    Column::new()
                        .cross_axis_alignment(Align::Start)
                        .spacing(8.0)
                        .child(Text::new("Release notes").size(18.0))
                        .child(Text::new(
                            "The first paragraph of an article. A selection can start here…",
                        ))
                        .child(Text::new("…and end in this one, as on a web page.")),
                )),
        )),
        // The bar over a selection can be changed: here it offers Copy only, since a
        // one-line code has nothing worth "Select all".
        Box::new(section(
            "Custom selection bar",
            SelectionArea::around(Text::new("WIFI-PASSWORD-2026").family(FontFamily::Monospace))
                .selection_toolbar(|_, items: Vec<ToolbarItem>| {
                    items
                        .into_iter()
                        .filter(|item| item.label() == "Copy")
                        .collect()
                }),
        )),
    ])
}

//! `Kbd` — a keyboard key cap, for showing shortcuts in menus, tooltips and help pages.

use frus::{Align, Column, FontWeight, Kbd, MainAxisSize, Row, SizedBox, Text, TextStyle, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        Box::new(section(
            "Single keys",
            Row::new()
                .main_axis_size(MainAxisSize::Min)
                .spacing(8.0)
                .child(Kbd::new("Esc"))
                .child(Kbd::new("Enter"))
                .child(Kbd::new("Tab"))
                .child(Kbd::new("F5")),
        )),
        // A combination is keys and "+" signs in a row; centring them across the row
        // keeps the signs level with the caps.
        Box::new(section(
            "Shortcuts",
            Column::new()
                .spacing(8.0)
                .cross_axis_alignment(Align::Start)
                .child(shortcut("Save", &["Ctrl", "S"]))
                .child(shortcut("Command palette", &["Ctrl", "Shift", "P"]))
                .child(shortcut("Close the window", &["Alt", "F4"])),
        )),
        // The cap's text style can be changed — bigger and bold here, for a help screen.
        Box::new(section(
            "Custom style",
            Kbd::new("Space").text_style(TextStyle::new(18.0).weight(FontWeight::Bold)),
        )),
    ])
}

/// "Label   Ctrl + S": a description and its keys.
fn shortcut(label: &str, keys: &[&str]) -> Row {
    let row = Row::new()
        .main_axis_size(MainAxisSize::Min)
        .spacing(4.0)
        .child(SizedBox::new(Text::new(label)).width(150.0));
    keys.iter().enumerate().fold(row, |row, (i, key)| {
        let row = if i > 0 {
            row.child(Text::new("+"))
        } else {
            row
        };
        row.child(Kbd::new(*key))
    })
}

//! `Button` — the labelled button, in its five variants: filled, tonal, elevated,
//! outlined and text. One widget, one `variant`, everything else shared.

use frus::{
    Button, ButtonStyle, Color, Icon, IconAlignment, Icons, Insets, State, StateContext,
    StatefulWidget, Text, Variant, Widget, WidgetState, WidgetStateProperty, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(ButtonDemo.into_widget())
}

/// The demo keeps one number — how many times a button was pressed — so that every
/// press visibly does something.
struct ButtonDemo;

struct ButtonDemoState {
    presses: u32,
    last: &'static str,
}

impl StatefulWidget for ButtonDemo {
    type State = ButtonDemoState;

    fn create_state(&self) -> ButtonDemoState {
        ButtonDemoState {
            presses: 0,
            last: "nothing yet",
        }
    }
}

impl ButtonDemoState {
    fn pressed(&mut self, which: &'static str) {
        self.presses += 1;
        self.last = which;
    }
}

impl State for ButtonDemoState {
    type Widget = ButtonDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        // A button with no `on_press` is disabled; `cx.callback` is what makes it live.
        let press =
            |which: &'static str| cx.callback(move |s: &mut ButtonDemoState| s.pressed(which));

        sections(vec![
            Box::new(Text::new(format!(
                "Pressed {} times — last: {}",
                self.presses, self.last
            ))),
            // From the loudest to the quietest. Use one `Filled` per screen for the main
            // action, `Tonal` beside it, `Outlined`/`Text` for the secondary ones, and
            // `Elevated` when the button sits over busy content.
            Box::new(section(
                "Variants",
                Wrap::new()
                    .gap(8.0)
                    .run_gap(8.0)
                    .child(Button::new("Filled").on_press(press("Filled")))
                    .child(
                        Button::new("Tonal")
                            .variant(Variant::Tonal)
                            .on_press(press("Tonal")),
                    )
                    .child(
                        Button::new("Elevated")
                            .variant(Variant::Elevated)
                            .on_press(press("Elevated")),
                    )
                    .child(
                        Button::new("Outlined")
                            .variant(Variant::Outlined)
                            .on_press(press("Outlined")),
                    )
                    .child(
                        Button::new("Text")
                            .variant(Variant::Text)
                            .on_press(press("Text")),
                    )
                    // `Danger` is a filled button in the error colours: for the action
                    // that destroys something.
                    .child(
                        Button::new("Delete")
                            .variant(Variant::Danger)
                            .on_press(press("Delete")),
                    ),
            )),
            // An icon goes before the label, or after it with `IconAlignment::End`.
            Box::new(section(
                "With an icon",
                Wrap::new()
                    .gap(8.0)
                    .run_gap(8.0)
                    .child(
                        Button::new("Send")
                            .icon(Icon::new(Icons::SEND))
                            .on_press(press("Send")),
                    )
                    .child(
                        Button::new("Next")
                            .variant(Variant::Outlined)
                            .icon(Icon::new(Icons::ARROW_FORWARD))
                            .icon_alignment(IconAlignment::End)
                            .on_press(press("Next")),
                    ),
            )),
            // `enabled(false)` greys a button out and makes it ignore presses — for an
            // action that is not possible yet (a form that is still invalid, say).
            Box::new(section(
                "Disabled",
                Wrap::new()
                    .gap(8.0)
                    .run_gap(8.0)
                    .child(
                        Button::new("Filled")
                            .enabled(false)
                            .on_press(press("never")),
                    )
                    .child(
                        Button::new("Outlined")
                            .variant(Variant::Outlined)
                            .enabled(false)
                            .on_press(press("never")),
                    ),
            )),
            // The common overrides have their own setters: colours, corners, padding,
            // height and text size. Anything they do not set comes from the theme.
            Box::new(section(
                "Custom colours, radius and padding",
                Wrap::new()
                    .gap(8.0)
                    .run_gap(8.0)
                    .child(
                        Button::new("Square")
                            .color(Color::hex("#0F766E"))
                            .label_color(Color::hex("#FFFFFF"))
                            .radius(4.0)
                            .on_press(press("Square")),
                    )
                    .child(
                        Button::new("Roomy")
                            .variant(Variant::Outlined)
                            .border_color(Color::hex("#7C3AED"))
                            .border_width(2.0)
                            .label_color(Color::hex("#7C3AED"))
                            .padding(32.0)
                            .height(48.0)
                            .on_press(press("Roomy")),
                    )
                    .child(
                        Button::new("Big text")
                            .variant(Variant::Tonal)
                            .size(18.0)
                            .on_press(press("Big text")),
                    ),
            )),
            // `ButtonStyle` describes the look **state by state**: here the fill changes
            // while the pointer is over the button and while it is held down.
            Box::new(section(
                "Per-state style",
                Button::new("Hover and press me")
                    .style(
                        ButtonStyle::new()
                            .background_color(
                                WidgetStateProperty::new()
                                    .when(WidgetState::Pressed, Color::hex("#B45309"))
                                    .when(WidgetState::Hovered, Color::hex("#D97706"))
                                    .otherwise(Color::hex("#F59E0B")),
                            )
                            .foreground_color(WidgetStateProperty::all(Color::hex("#1C1917")))
                            .padding(WidgetStateProperty::all(Insets::symmetric(28.0, 12.0))),
                    )
                    .on_press(press("Per-state")),
            )),
            // `with_child` takes any widget as the content.
            Box::new(section(
                "Any content",
                Button::with_child(Text::new("Custom child").italic())
                    .variant(Variant::Outlined)
                    .on_press(press("Custom child")),
            )),
        ])
    }
}

//! `IconButton` — a square button holding one icon, for compact actions in toolbars,
//! list rows and app bars.

use frus::{
    Color, IconButton, IconButtonVariant, Icons, Row, State, StateContext, StatefulWidget, Text,
    Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(IconButtonDemo.into_widget())
}

struct IconButtonDemo;

struct IconButtonDemoState {
    favorite: bool,
    bookmarked: bool,
    likes: u32,
}

impl StatefulWidget for IconButtonDemo {
    type State = IconButtonDemoState;

    fn create_state(&self) -> IconButtonDemoState {
        IconButtonDemoState {
            favorite: false,
            bookmarked: true,
            likes: 0,
        }
    }
}

impl State for IconButtonDemoState {
    type Widget = IconButtonDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let like = || cx.callback(|s: &mut IconButtonDemoState| s.likes += 1);

        sections(vec![
            // `label` is what a screen reader announces and what the tooltip says: an
            // icon alone means nothing to someone who cannot see it, so always give one.
            Box::new(section(
                "Variants",
                Wrap::new()
                    .gap(8.0)
                    .run_gap(8.0)
                    .child(
                        IconButton::new(Icons::THUMB_UP)
                            .label("Like")
                            .on_press(like()),
                    )
                    .child(
                        IconButton::new(Icons::THUMB_UP)
                            .label("Like")
                            .variant(IconButtonVariant::Filled)
                            .on_press(like()),
                    )
                    .child(
                        IconButton::new(Icons::THUMB_UP)
                            .label("Like")
                            .variant(IconButtonVariant::Tonal)
                            .on_press(like()),
                    )
                    .child(
                        IconButton::new(Icons::THUMB_UP)
                            .label("Like")
                            .variant(IconButtonVariant::Outlined)
                            .on_press(like()),
                    ),
            )),
            Box::new(Text::new(format!("Liked {} times", self.likes))),
            // A toggle: `selected` swaps to the filled look. The state is yours — the
            // button only shows it — so the press flips a field.
            Box::new(section(
                "Selected (toggle)",
                Row::new()
                    .spacing(8.0)
                    .child(
                        IconButton::new(if self.favorite {
                            Icons::FAVORITE
                        } else {
                            Icons::FAVORITE_BORDER
                        })
                        .label("Favourite")
                        .selected(self.favorite)
                        .on_press(
                            cx.callback(|s: &mut IconButtonDemoState| s.favorite = !s.favorite),
                        ),
                    )
                    .child(
                        IconButton::new(if self.bookmarked {
                            Icons::BOOKMARK
                        } else {
                            Icons::BOOKMARK_BORDER
                        })
                        .label("Bookmark")
                        .variant(IconButtonVariant::Filled)
                        .selected(self.bookmarked)
                        .on_press(
                            cx.callback(|s: &mut IconButtonDemoState| s.bookmarked = !s.bookmarked),
                        ),
                    ),
            )),
            // Disabled: no press to answer, greyed out.
            Box::new(section(
                "Disabled",
                Row::new()
                    .spacing(8.0)
                    .child(
                        IconButton::new(Icons::DELETE)
                            .label("Delete")
                            .enabled(false),
                    )
                    .child(
                        IconButton::new(Icons::DELETE)
                            .label("Delete")
                            .variant(IconButtonVariant::Filled)
                            .enabled(false),
                    ),
            )),
            // Size, icon size, colours and corners are all yours to change.
            Box::new(section(
                "Custom size and colours",
                Row::new()
                    .spacing(8.0)
                    .child(
                        IconButton::new(Icons::SHARE)
                            .label("Share")
                            .size(56.0)
                            .icon_size(32.0)
                            .color(Color::hex("#DCFCE7"))
                            .icon_color(Color::hex("#166534"))
                            .radius(12.0)
                            .on_press(like()),
                    )
                    // A glyph works where the icon set has nothing that fits.
                    .child(IconButton::glyph("½").label("Half").on_press(like())),
            )),
        ])
    }
}

