            // decide. Here each press flips its own flag.
            Box::new(section(
                "Many on at once",
                ToggleButtons::new(
                    self.format.clone(),
                    cx.handler(|s: &mut ToggleDemoState, i: usize| s.format[i] = !s.format[i]),
