//! `PopupMenuButton` and `MenuItem` — a list of actions that floats over a button and
//! closes on a click outside. For the "more" menu of a row or an app bar.

use frus::{
    Button, Callback, IconButton, Icons, MenuItem, PopupMenuButton, Row, State, StateContext,
    StatefulWidget, Text, Variant, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(PopupDemo.into_widget())
}

struct PopupDemo;

/// Menus are **controlled**: the application keeps which one is open. Here at most one
/// is, so a single field says which.
struct PopupDemoState {
    open: Option<Menu>,
    last: String,
    show_grid: bool,
}

#[derive(Clone, Copy, PartialEq)]
enum Menu {
    Simple,
    Rich,
}

impl PopupDemoState {
    fn toggle(&mut self, menu: Menu) {
        self.open = if self.open == Some(menu) {
            None
        } else {
            Some(menu)
        };
    }

    /// An item was chosen: remember it, and close the menu.
    fn chose(&mut self, what: &str) {
        self.last = what.to_string();
        self.open = None;
    }
}

impl StatefulWidget for PopupDemo {
    type State = PopupDemoState;

    fn create_state(&self) -> PopupDemoState {
        PopupDemoState {
            open: None,
            last: "nothing yet".into(),
            show_grid: true,
        }
    }
}

impl State for PopupDemoState {
    type Widget = PopupDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let pick = |what: &'static str| -> Callback {
            cx.callback(move |s: &mut PopupDemoState| s.chose(what))
        };
        // A click outside the menu sends this.
        let close = cx.callback(|s: &mut PopupDemoState| s.open = None);

        // The anchor is any widget; here an icon button that opens and closes the menu.
        let simple = PopupMenuButton::new(
            IconButton::new(Icons::MORE_VERT)
                .label("More")
                .on_press(cx.callback(|s: &mut PopupDemoState| s.toggle(Menu::Simple))),
            self.open == Some(Menu::Simple),
            close.clone(),
        )
        .item("Rename", pick("Rename"))
        .item("Duplicate", pick("Duplicate"))
        .item("Delete", pick("Delete"));

        // `MenuItem` covers the rows that are not just words: an icon, a tick, a
        // keyboard shortcut, a rule between groups, a row that is unavailable.
        let rich = PopupMenuButton::new(
            Button::new("Edit")
                .variant(Variant::Outlined)
                .on_press(cx.callback(|s: &mut PopupDemoState| s.toggle(Menu::Rich))),
            self.open == Some(Menu::Rich),
            close,
        )
        .entry(MenuItem::icon(Icons::CONTENT_CUT, "Cut", pick("Cut")).shortcut("Ctrl+X"))
        .entry(MenuItem::icon(Icons::CONTENT_COPY, "Copy", pick("Copy")).shortcut("Ctrl+C"))
        .entry(MenuItem::icon(Icons::CONTENT_PASTE, "Paste", pick("Paste")).enabled(false))
        .divider()
        .entry(MenuItem::checked(
            "Show grid",
            self.show_grid,
            cx.callback(|s: &mut PopupDemoState| {
                s.show_grid = !s.show_grid;
                s.open = None;
            }),
        ));
        // The panel's look (shape, elevation, padding) comes from the theme's
        // `MenuTheme`, so every menu of the app agrees.

        sections(vec![
            Box::new(section(
                "Simple and rich menus",
                Row::new().spacing(24.0).child(simple).child(rich),
            )),
            Box::new(Text::new(format!(
                "Last action: {} · grid {}",
                self.last,
                if self.show_grid { "on" } else { "off" }
            ))),
        ])
    }
}

//! `MenuAnchor` — a floating panel with **any content**, anchored to a widget and closed
//! by a click outside. A popup menu is a list of rows; this is for everything else.

use frus::{
    Align, Button, Column, FontWeight, Insets, MenuAnchor, Slider, State, StateContext,
    StatefulWidget, Text, Variant, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(AnchorDemo.into_widget())
}

struct AnchorDemo;

struct AnchorDemoState {
    open: bool,
    volume: f32,
}

impl StatefulWidget for AnchorDemo {
    type State = AnchorDemoState;

    fn create_state(&self) -> AnchorDemoState {
        AnchorDemoState {
            open: false,
            volume: 0.4,
        }
    }
}

impl State for AnchorDemoState {
    type Widget = AnchorDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        // The panel holds live widgets: dragging the slider changes the state while the
        // panel stays open.
        let panel = Column::new()
            .spacing(8.0)
            .cross_axis_alignment(Align::Start)
            .child(Text::new("Volume").weight(FontWeight::SemiBold))
            .child(
                Slider::new(self.volume)
                    .width(200.0)
                    .on_change(cx.handler(|s: &mut AnchorDemoState, v: f32| s.volume = v)),
            )
            .child(
                Button::new("Done")
                    .variant(Variant::Text)
                    .on_press(cx.callback(|s: &mut AnchorDemoState| s.open = false)),
            );

        let anchor = MenuAnchor::new(
            Button::new(format!("Volume: {:.0}%", self.volume * 100.0))
                .variant(Variant::Tonal)
                .on_press(cx.callback(|s: &mut AnchorDemoState| s.open = !s.open)),
            self.open,
            cx.callback(|s: &mut AnchorDemoState| s.open = false),
        )
        .content(panel)
        .menu_padding(Insets::uniform(16.0))
        .radius(16.0);

        sections(vec![Box::new(section("A panel with a slider", anchor))])
    }
}

//! `MenuBar`, `SubmenuButton` and `MenuPath` — the File / Edit / View menus along the
//! top of a desktop window, with submenus inside them.

use frus::{
    Callback, MenuBar, MenuItem, MenuPath, State, StateContext, StatefulWidget, SubmenuButton,
    Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(MenuBarDemo.into_widget())
}

struct MenuBarDemo;

/// Which menu is open is a **path** — the menu on the bar, then the submenu inside it —
/// kept by the application like any other state.
struct MenuBarDemoState {
    path: MenuPath,
    last: String,
    word_wrap: bool,
}

impl MenuBarDemoState {
    fn chose(&mut self, what: &str) {
        self.last = what.to_string();
        self.path = MenuPath::closed();
    }
}

impl StatefulWidget for MenuBarDemo {
    type State = MenuBarDemoState;

    fn create_state(&self) -> MenuBarDemoState {
        MenuBarDemoState {
            path: MenuPath::closed(),
            last: "nothing yet".into(),
            word_wrap: true,
        }
    }
}

impl State for MenuBarDemoState {
    type Widget = MenuBarDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let pick = |what: &'static str| -> Callback {
            cx.callback(move |s: &mut MenuBarDemoState| s.chose(what))
        };

        let file = SubmenuButton::new("File")
            .item(MenuItem::new("New", pick("New")).shortcut("Ctrl+N"))
            .item(MenuItem::new("Open…", pick("Open")).shortcut("Ctrl+O"))
            // A row that opens a menu beside this one.
            .submenu(
                SubmenuButton::new("Open recent")
                    .item(MenuItem::new("notes.txt", pick("notes.txt")))
                    .item(MenuItem::new("todo.md", pick("todo.md"))),
            )
            .divider()
            .item(MenuItem::new("Quit", pick("Quit")));
        let edit = SubmenuButton::new("Edit")
            .item(MenuItem::new("Undo", pick("Undo")).shortcut("Ctrl+Z"))
            .item(MenuItem::new("Redo", pick("Redo")).enabled(false));
        let view = SubmenuButton::new("View").item(MenuItem::checked(
            "Word wrap",
            self.word_wrap,
            cx.callback(|s: &mut MenuBarDemoState| {
                s.word_wrap = !s.word_wrap;
                s.path = MenuPath::closed();
            }),
        ));

        // The bar reports the path it should have next — a menu opened, moved to,
        // or everything closed — and the handler stores it.
        let bar = MenuBar::new(
            &self.path,
            cx.handler(|s: &mut MenuBarDemoState, path: MenuPath| s.path = path),
        )
        .menu(file)
        .menu(edit)
        .menu(view);

        sections(vec![
            Box::new(section("A window's menus", bar)),
            Box::new(Text::new(format!(
                "Last command: {} · word wrap {}",
                self.last,
                if self.word_wrap { "on" } else { "off" }
            ))),
        ])
    }
}

//! `DropdownButton` and `DropdownOption` — a button showing the current choice, whose
//! options float below it. For picking one value from a short, closed list.

use frus::{
    Color, Container, DropdownButton, DropdownOption, Row, State, StateContext, StatefulWidget,
    Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(DropdownDemo.into_widget())
}

const FRUITS: [&str; 4] = ["Apple", "Banana", "Cherry", "Grape"];
const COLORS: [(&str, &str); 4] = [
    ("Red", "#EF4444"),
    ("Green", "#22C55E"),
    ("Blue", "#3B82F6"),
    ("Purple", "#A855F7"),
];

struct DropdownDemo;

struct DropdownDemoState {
    fruit: usize,
    fruit_open: bool,
    color: usize,
    color_open: bool,
}

impl StatefulWidget for DropdownDemo {
    type State = DropdownDemoState;

    fn create_state(&self) -> DropdownDemoState {
        DropdownDemoState {
            fruit: 0,
            fruit_open: false,
            color: 2,
            color_open: false,
        }
    }
}

impl State for DropdownDemoState {
    type Widget = DropdownDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        // Controlled twice over: the application holds the choice **and** whether the
        // list is open. The header press toggles it; a pick stores the index and closes.
        let fruits = DropdownButton::new(
            FRUITS[self.fruit],
            cx.callback(|s: &mut DropdownDemoState| s.fruit_open = !s.fruit_open),
        )
        .selected(self.fruit)
        .width(200.0)
        .options(
            self.fruit_open,
            &FRUITS,
            cx.handler(|s: &mut DropdownDemoState, i: usize| {
                s.fruit = i;
                s.fruit_open = false;
            }),
        );

        // Options that are not just words: a swatch beside the name. The last one is
        // shown but cannot be picked.
        let options = COLORS
            .iter()
            .enumerate()
            .map(|(i, (name, hex))| {
                let option = DropdownOption::widget(
                    Row::new()
                        .spacing(8.0)
                        .child(
                            Container::new()
                                .width(14.0)
                                .height(14.0)
                                .radius(7.0)
                                .color(Color::hex(hex)),
                        )
                        .child(Text::new(*name)),
                );
                option.enabled(i != COLORS.len() - 1)
            })
            .collect();
        let colors = DropdownButton::new(
            COLORS[self.color].0,
            cx.callback(|s: &mut DropdownDemoState| s.color_open = !s.color_open),
        )
        .selected(self.color)
        .width(200.0)
        .menu_radius(12.0)
        .options_widgets(
            self.color_open,
            options,
            cx.handler(|s: &mut DropdownDemoState, i: usize| {
                s.color = i;
                s.color_open = false;
            }),
        );

        sections(vec![
            Box::new(section("Words", fruits)),
            Box::new(section("Custom rows, one unavailable", colors)),
            Box::new(Text::new(format!(
                "{} · {}",
                FRUITS[self.fruit], COLORS[self.color].0
            ))),
        ])
    }
}

//! `DropdownMenu` — a dropdown that looks like a text field and filters its choices as
//! you type. For a closed list too long to scan (countries, time zones).

use frus::{DropdownMenu, State, StateContext, StatefulWidget, Text, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(DropdownMenuDemo.into_widget())
}

const COUNTRIES: [&str; 8] = [
    "Argentina",
    "Belgium",
    "Canada",
    "Denmark",
    "France",
    "Ghana",
    "Japan",
    "Kenya",
];

struct DropdownMenuDemo;

struct DropdownMenuDemoState {
    /// What is typed while the menu is open. The field shows the **selected** choice
    /// again as soon as the menu closes, so a half-typed query never looks like a value.
    query: String,
    open: bool,
    selected: Option<usize>,
}

impl StatefulWidget for DropdownMenuDemo {
    type State = DropdownMenuDemoState;

    fn create_state(&self) -> DropdownMenuDemoState {
        DropdownMenuDemoState {
            query: String::new(),
            open: false,
            selected: None,
        }
    }
}

impl State for DropdownMenuDemoState {
    type Widget = DropdownMenuDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let menu = DropdownMenu::new(
            self.query.clone(),
            self.open,
            // Typing keeps the menu open and narrows the list.
            cx.handler(|s: &mut DropdownMenuDemoState, query: String| {
                s.query = query;
                s.open = true;
            }),
            cx.callback(|s: &mut DropdownMenuDemoState| s.open = !s.open),
        )
        .label("Country")
        .placeholder("Type to filter")
        .width(260.0)
        .max_visible(5)
        .selected(self.selected)
        // The index is into the full list, whatever the filter left showing.
        .options(
            &COUNTRIES,
            cx.handler(|s: &mut DropdownMenuDemoState, i: usize| {
                s.selected = Some(i);
                s.open = false;
                s.query.clear();
            }),
        );

        sections(vec![
            Box::new(section("Filtering as you type", menu)),
            Box::new(Text::new(match self.selected {
                Some(i) => format!("Selected: {}", COUNTRIES[i]),
                None => "Nothing selected".to_string(),
            })),
        ])
    }
}

