//! `CheckboxListTile`, `RadioListTile` and `SwitchListTile` — list rows whose **whole
//! width** works one control. For settings screens: a tap anywhere on the row toggles,
//! not only on the 20-pixel box.

use frus::{
    Align, CheckboxListTile, Color, Column, ConstrainedBox, ControlAffinity, Icon, Icons,
    RadioListTile, State, StateContext, StatefulWidget, SwitchListTile, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(TilesDemo.into_widget())
}

const THEMES: [&str; 3] = ["System", "Light", "Dark"];

struct TilesDemo;

struct TilesDemoState {
    wifi: bool,
    bluetooth: bool,
    sync: bool,
    backup: bool,
    theme: usize,
}

impl StatefulWidget for TilesDemo {
    type State = TilesDemoState;

    fn create_state(&self) -> TilesDemoState {
        TilesDemoState {
            wifi: true,
            bluetooth: false,
            sync: true,
            backup: false,
            theme: 0,
        }
    }
}

impl State for TilesDemoState {
    type Widget = TilesDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        // The rows take the message to send, not the new value: flip the field in it.
        let switches = Column::new()
            .cross_axis_alignment(Align::Stretch)
            .child(
                SwitchListTile::new(
                    self.wifi,
                    cx.callback(|s: &mut TilesDemoState| s.wifi = !s.wifi),
                )
                .title("Wi-Fi")
                .subtitle(if self.wifi { "Connected" } else { "Off" })
                .secondary(Icon::new(Icons::WIFI)),
            )
            .child(
                SwitchListTile::new(
                    self.bluetooth,
                    cx.callback(|s: &mut TilesDemoState| s.bluetooth = !s.bluetooth),
                )
                .title("Bluetooth")
                .secondary(Icon::new(Icons::BLUETOOTH))
                .active_color(Color::hex("#2563EB")),
            );

        // The control goes at the end by default; `Leading` puts it in front, where a
        // checkbox in a list usually sits.
        let checkboxes = Column::new()
            .cross_axis_alignment(Align::Stretch)
            .child(
                CheckboxListTile::new(
                    self.sync,
                    cx.callback(|s: &mut TilesDemoState| s.sync = !s.sync),
                )
                .title("Sync contacts")
                .subtitle("Every hour, over Wi-Fi")
                .control_affinity(ControlAffinity::Leading),
            )
            .child(
                CheckboxListTile::new(
                    self.backup,
                    cx.callback(|s: &mut TilesDemoState| s.backup = !s.backup),
                )
                .title("Back up photos")
                .control_affinity(ControlAffinity::Leading)
                .enabled(self.sync),
            );

        // Radio rows: each is "selected or not"; the state keeps which one is.
        let radios = THEMES.iter().enumerate().fold(
            Column::new().cross_axis_alignment(Align::Stretch),
            |column, (i, name)| {
                column.child(
                    RadioListTile::new(
                        self.theme == i,
                        cx.callback(move |s: &mut TilesDemoState| s.theme = i),
                    )
                    .title(*name)
                    .control_affinity(ControlAffinity::Leading),
                )
            },
        );

        // A list row stretches to the width it is given; `ConstrainedBox` bounds it.
        sections(vec![
            Box::new(section(
                "SwitchListTile",
                ConstrainedBox::new(switches).max_width(400.0),
            )),
            Box::new(section(
                "CheckboxListTile (the second needs the first)",
                ConstrainedBox::new(checkboxes).max_width(400.0),
            )),
            Box::new(section(
                "RadioListTile",
                ConstrainedBox::new(radios).max_width(400.0),
            )),
        ])
    }
}

//! `Slider` — a value picked by dragging along a track: continuous, or in steps with
//! `divisions`, with a bubble showing the value while dragging.

use frus::{
    Color, Insets, Padding, ShowValueIndicator, Slider, State, StateContext, StatefulWidget, Text,
    Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(SliderDemo.into_widget())
}

struct SliderDemo;

struct SliderDemoState {
    volume: f32,
    rating: f32,
    temperature: f32,
    /// Changed only when a drag **ends**: for work too costly to do on every pixel.
    committed: f32,
}

impl StatefulWidget for SliderDemo {
    type State = SliderDemoState;

    fn create_state(&self) -> SliderDemoState {
        SliderDemoState {
            volume: 0.5,
            rating: 3.0,
            temperature: 21.0,
            committed: 21.0,
        }
    }
}

impl State for SliderDemoState {
    type Widget = SliderDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        sections(vec![
            // From 0 to 1 unless told otherwise.
            Box::new(section(
                "Continuous",
                Slider::new(self.volume)
                    .width(300.0)
                    .on_change(cx.handler(|s: &mut SliderDemoState, v: f32| s.volume = v)),
            )),
            Box::new(Text::new(format!("Volume: {:.0}%", self.volume * 100.0))),
            // `divisions` snaps to steps; `value_label` writes the bubble, shown here all
            // the time (by default only while dragging). The padding is the bubble's room.
            Box::new(section(
                "Steps with a value label",
                Padding::new(
                    Insets::new(28.0, 0.0, 0.0, 0.0),
                    Slider::new(self.rating)
                        .range(1.0, 5.0)
                        .divisions(4)
                        .value_label(|v| format!("{v:.0} stars"))
                        .show_value_indicator(ShowValueIndicator::AlwaysVisible)
                        .width(300.0)
                        .on_change(cx.handler(|s: &mut SliderDemoState, v: f32| s.rating = v)),
                ),
            )),
            // `on_change_end` fires once, on release.
            Box::new(section(
                "Custom range, colours and change end",
                Slider::new(self.temperature)
                    .range(10.0, 30.0)
                    .divisions(40)
                    .value_label(|v| format!("{v:.1} °C"))
                    .active_color(Color::hex("#DC2626"))
                    .inactive_color(Color::hex("#FECACA"))
                    .thumb_color(Color::hex("#991B1B"))
                    .width(300.0)
                    .on_change(cx.handler(|s: &mut SliderDemoState, v: f32| s.temperature = v))
                    .on_change_end(cx.handler(|s: &mut SliderDemoState, v: f32| s.committed = v)),
            )),
            Box::new(Text::new(format!(
                "Dragging: {:.1} °C · saved: {:.1} °C",
                self.temperature, self.committed
            ))),
            // A second, lighter track: how much of a video is buffered, say.
            Box::new(section(
                "Secondary track, disabled",
                Slider::new(0.3)
                    .secondary_track_value(0.7)
                    .width(300.0)
                    .enabled(false),
            )),
        ])
    }
}

