}

//! `Badge` — the small mark that says "there is something here": a count on an inbox,
//! a dot on a bell.

use frus::{
    Badge, Button, Color, Colors, Icon, Icons, Positioned, Row, Stack, Text, Variant, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let unread = cx.use_state(|| 3u32);

        // A badge is a standalone mark. To pin one to an icon's corner, lay both in a
        // `Stack` and place the badge with `Positioned`.
        let inbox = Stack::new()
            .width(36.0)
            .height(32.0)
            .layer(
                Positioned::new(Icon::new(Icons::MAIL))
                    .left(0.0)
                    .bottom(0.0),
            )
            .layer(
                Positioned::new(
                    // A count of zero hides the label and leaves a dot — or, as here, the
                    // application drops the badge altogether.
                    if unread.get() > 0 {
                        Box::new(Badge::new(count_label(unread.get()))) as Box<dyn Widget>
                    } else {
                        Box::new(Row::new())
                    },
                )
                .right(0.0)
                .top(0.0),
            );

        let more = unread.clone();
        let clear = unread.clone();

        sections(vec![
            // With a label it is a pill carrying a number or a word.
            Box::new(section(
                "Labelled",
                Row::new()
                    .spacing(12.0)
                    .child(Badge::new("1"))
                    .child(Badge::new("42"))
                    .child(Badge::new("999+"))
                    .child(Badge::new("NEW")),
            )),
            // Without one it is a dot: something happened, without saying how much.
            Box::new(section(
                "Dot",
                Row::new()
                    .spacing(12.0)
                    .child(Badge::dot())
                    .child(Badge::dot().small_size(10.0)),
            )),
            // Colours and sizes are the theme's by default and yours to override.
            Box::new(section(
                "Custom colours and size",
                Row::new()
                    .spacing(12.0)
                    .child(
                        Badge::new("PRO")
                            .background_color(Color::hex("#7C3AED"))
                            .text_color(Colors::WHITE),
                    )
                    .child(
                        Badge::new("12")
                            .background_color(Color::hex("#16A34A"))
                            .large_size(22.0)
                            .padding(8.0),
                    ),
            )),
            // A live count on an icon.
            Box::new(section(
                "On an icon",
                Row::new()
                    .spacing(16.0)
                    .child(inbox)
                    .child(
                        Button::new("New mail")
                            .variant(Variant::Tonal)
                            .on_press(move || more.update(|n| *n += 1)),
                    )
                    .child(
                        Button::new("Mark all read")
                            .variant(Variant::Text)
                            .on_press(move || clear.set(0)),
                    ),
            )),
            Box::new(Text::new(format!("{} unread", unread.get()))),
        ])
    }))
}

/// Counts above 99 are shown as "99+", so the pill stays small.
pub fn count_label(count: u32) -> String {
    if count > 99 {
        "99+".to_string()
    } else {
        count.to_string()
    }
}

//! `Icon` — a vector icon from the bundled set (`Icons::…`), or one of your own,
//! scaled and coloured to the theme.

use frus::{
    Align, Color, Column, Expanded, Icon, IconData, Icons, Path, Point, Row, Text, Widget, Wrap,
};

use crate::common::shared::{section, sections};

/// An icon of your own: a path on the same 24 × 24 grid the bundled ones use, y
/// downwards. A function pointer keeps it a `const`, declared like `Icons::STAR`.
const DIAMOND: IconData = IconData::custom(diamond);

fn diamond() -> Path {
    Path::new()
        .move_to(Point::new(12.0, 2.0))
        .line_to(Point::new(22.0, 12.0))
        .line_to(Point::new(12.0, 22.0))
        .line_to(Point::new(2.0, 12.0))
        .close()
}

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let theme = cx.theme();

        // The filled style is always bundled. Outlined, rounded and sharp each sit behind
        // a cargo feature (`icons-outlined`, `icons-rounded`, `icons-sharp`), so an app
        // pays only for the artwork it uses. Looking one up by name says whether it is in
        // this build: `None` means the feature is off.
        let outlined = Icons::by_name("favorite_outlined");
        let style_row = match outlined {
            Some(icon) => Row::new()
                .spacing(12.0)
                .child(Icon::new(Icons::FAVORITE))
                .child(Icon::new(icon))
                .child(Text::new("filled and outlined")),
            None => Row::new()
                .spacing(12.0)
                .child(Icon::new(Icons::FAVORITE))
                // `Expanded` gives the sentence the rest of the row, and `wrap` lets it
                // break into lines there instead of running past the edge.
                .child(Expanded::new(
                    Text::new(
                        "Only the filled style is in this build; enable `icons-outlined` for more.",
                    )
                    .wrap(),
                )),
        };

        sections(vec![
            // An icon takes the theme's icon size (24) and colour unless told otherwise.
            Box::new(section(
                "Bundled icons",
                Wrap::new()
                    .gap(16.0)
                    .run_gap(12.0)
                    .child(Icon::new(Icons::HOME))
                    .child(Icon::new(Icons::SEARCH))
                    .child(Icon::new(Icons::SETTINGS))
                    .child(Icon::new(Icons::STAR))
                    .child(Icon::new(Icons::DELETE))
                    .child(Icon::new(Icons::CLOUD_UPLOAD))
                    .child(Icon::new(Icons::ARROW_BACK)),
            )),
            Box::new(section(
                "Sizes",
                Row::new()
                    .spacing(16.0)
                    .child(Icon::new(Icons::ALARM).size(16.0))
                    .child(Icon::new(Icons::ALARM).size(24.0))
                    .child(Icon::new(Icons::ALARM).size(36.0))
                    .child(Icon::new(Icons::ALARM).size(48.0)),
            )),
            // Theme colours keep icons right in light and dark mode; a literal colour is
            // for brand marks and status.
            Box::new(section(
                "Colours",
                Row::new()
                    .spacing(16.0)
                    .child(Icon::new(Icons::CHECK_CIRCLE).color(theme.primary))
                    .child(Icon::new(Icons::ERROR).color(theme.error))
                    .child(Icon::new(Icons::INFO).color(theme.muted))
                    .child(Icon::new(Icons::WARNING).color(Color::hex("#F59E0B"))),
            )),
            Box::new(section("Styles", style_row)),
            Box::new(section(
                "Your own icon",
                Column::new()
                    .cross_axis_alignment(Align::Start)
                    .spacing(8.0)
                    .child(
                        Row::new()
                            .spacing(16.0)
                            .child(Icon::new(DIAMOND))
                            .child(Icon::new(DIAMOND).size(40.0).color(theme.primary)),
                    ),
            )),
        ])
    }))
}

//! `Image` — a bitmap fitted into a box: embedded with `asset!`, made from pixels, or
//! fetched over the network. `ImageIcon` puts a picture where an icon goes.

use frus::{
    Align, BoxFit, Color, Column, Container, Expanded, Icon, Icons, Image, ImageData, ImageIcon,
    ImageState, Row, Skeleton, Text, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let theme = cx.theme();

        // Pixels you make yourself become an image with `ImageData::from_rgba`. The
        // renderer caches a picture by its identity, so make it once (`use_memo`) rather
        // than on every build, which would upload a new texture each frame.
        let gradient = cx.use_memo((), || {
            let (w, h) = (64u32, 64u32);
            let mut rgba = Vec::with_capacity((w * h * 4) as usize);
            for y in 0..h {
                for x in 0..w {
                    rgba.extend_from_slice(&[(x * 4) as u8, (y * 4) as u8, 200, 255]);
                }
            }
            ImageData::from_rgba(w, h, rgba).into_handle()
        });

        // A network image is in one of three states, and the view says what each looks
        // like. This gallery is built without the `net` feature, so there is no fetcher
        // and the request reports why it failed instead of waiting for ever.
        let remote = Image::network("https://example.com/photo.png")
            .size(120.0, 80.0)
            .placeholder(Skeleton::new().radius(8.0));
        let remote: Box<dyn Widget> = match remote.state() {
            ImageState::Ready => Box::new(remote),
            ImageState::Loading => Box::new(Skeleton::new().width(120.0).height(80.0)),
            ImageState::Failed(why) => Box::new(
                Row::new()
                    .spacing(8.0)
                    .child(Icon::new(Icons::BROKEN_IMAGE).color(theme.error))
                    // The reason can be long: `Expanded` keeps it to the room the icon
                    // leaves, so it wraps rather than overflows.
                    .child(Expanded::new(
                        Text::new(format!("Could not load: {why}"))
                            .wrap()
                            .color(theme.muted),
                    )),
            ),
        };

        sections(vec![
            // `asset!` embeds the file at compile time — no path to get wrong at run time.
            // The path is relative to this source file. Give one side and the other
            // follows the picture's own ratio.
            Box::new(section(
                "From an asset",
                Row::new()
                    .spacing(16.0)
                    .child(
                        frus::asset!("../../../../res/mipmap-xxxhdpi/ic_launcher.png").width(96.0),
                    )
                    .child(
                        frus::asset!("../../../../res/mipmap-xxxhdpi/ic_launcher.png")
                            .width(48.0)
                            .opacity(0.5)
                            .semantic_label("frus logo, faded"),
                    ),
            )),
            // `fit` decides how the picture fills a box of another shape.
            Box::new(section(
                "Fit",
                Wrap::new()
                    .gap(16.0)
                    .run_gap(16.0)
                    .child(fitted("Contain", BoxFit::Contain))
                    .child(fitted("Cover", BoxFit::Cover))
                    .child(fitted("Fill", BoxFit::Fill)),
            )),
            Box::new(section(
                "From pixels",
                Image::new((*gradient).clone()).size(96.0, 96.0),
            )),
            // An image as an icon: same size rules as `Icon`, in its own colours unless
            // tinted (tinting suits white or grey artwork).
            Box::new(section(
                "ImageIcon",
                Row::new()
                    .spacing(16.0)
                    .child(ImageIcon::new(frus::asset!(
                        "../../../../res/mipmap-xxxhdpi/ic_launcher.png"
                    )))
                    .child(
                        ImageIcon::new(frus::asset!(
                            "../../../../res/mipmap-xxxhdpi/ic_launcher.png"
                        ))
                        .size(40.0),
                    )
                    .child(Text::new("next to text, at icon size")),
            )),
            // While a network picture is on its way, `placeholder` fills its box with a
            // colour, a shimmering skeleton or a smaller picture.
            Box::new(section("Network, with a placeholder", remote)),
        ])
    }))
}

/// The logo in a wide 140 × 70 box, fitted one way, with the box outlined so the
/// difference shows.
fn fitted(label: &str, fit: BoxFit) -> Column {
    Column::new()
        .cross_axis_alignment(Align::Start)
        .spacing(4.0)
        .child(
            Container::new().border(1.0, Color::hex("#A1A1AA")).child(
                frus::asset!("../../../../res/mipmap-xxxhdpi/ic_launcher.png")
                    .size(140.0, 70.0)
                    .fit(fit),
            ),
        )
        .child(Text::new(label).size(12.0))
}

//! `Divider` and `VerticalDivider` — a thin rule in the theme's colours, across a column
//! or down a row.

use frus::{Align, Color, Column, Container, Divider, Row, Text, VerticalDivider, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // A divider is as wide as it is allowed to be, inside a band of `height` (16 by
        // default) that leaves room above and below. A column centres its children
        // unless told to stretch them, so `Align::Stretch` is what lets it run across.
        Box::new(section(
            "Divider",
            Container::new().width(300.0).child(
                Column::new()
                    .cross_axis_alignment(Align::Stretch)
                    .child(Text::new("Inbox"))
                    .child(Divider::new())
                    .child(Text::new("Archive"))
                    .child(Divider::new())
                    .child(Text::new("Trash")),
            ),
        )),
        // Indents line a rule up with the text of a list rather than with its edge.
        Box::new(section(
            "Indented, thicker, coloured",
            Container::new().width(300.0).child(
                Column::new()
                    .cross_axis_alignment(Align::Stretch)
                    .child(Divider::new().indent(56.0))
                    .child(Divider::new().indent(16.0).end_indent(16.0))
                    .child(
                        Divider::new()
                            .height(24.0)
                            .thickness(4.0)
                            .radius(2.0)
                            .color(Color::hex("#6366F1")),
                    ),
            ),
        )),
        // A vertical divider separates items in a row; the row needs a height for the
        // rule to run down.
        Box::new(section(
            "VerticalDivider",
            Container::new().height(40.0).child(
                Row::new()
                    .cross_axis_alignment(Align::Stretch)
                    .child(Text::new("Bold"))
                    .child(VerticalDivider::new())
                    .child(Text::new("Italic"))
                    .child(VerticalDivider::new().width(24.0).thickness(2.0))
                    .child(Text::new("Underline"))
                    .child(VerticalDivider::new().indent(8.0).end_indent(8.0))
                    .child(Text::new("Strike")),
            ),
        )),
    ])
}

//! `ListTile` — one row of a list: something in front, one to three lines of text, and
//! something behind. The shape of a settings line, a contact, a menu entry.

use frus::{
    Align, CircleAvatar, Column, Container, Divider, Icon, Icons, ListTile, Switch, Text, Widget,
};

use crate::common::shared::{section, sections};

const ROOMS: [(&str, &str); 3] = [
    ("Living room", "3 lights on"),
    ("Kitchen", "All off"),
    ("Bedroom", "1 light on"),
];

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let selected = cx.use_state(|| 0usize);
        let wifi = cx.use_state(|| true);

        // `selected` tints the tile and its text with the theme's accent; `on_tap` makes
        // the whole row pressable.
        let rooms = ROOMS.iter().enumerate().fold(
            Column::new().cross_axis_alignment(Align::Stretch),
            |list, (i, (room, status))| {
                let select = selected.clone();
                list.child(
                    ListTile::new()
                        .leading(Icon::new(Icons::LIGHTBULB))
                        .title(*room)
                        .subtitle(*status)
                        .selected(selected.get() == i)
                        .on_tap(move || select.set(i)),
                )
            },
        );

        let toggle = wifi.clone();
        sections(vec![
            // One line: a title, with an icon in front and a chevron behind.
            Box::new(section(
                "One line",
                list(
                    Column::new()
                        .cross_axis_alignment(Align::Stretch)
                        .child(
                            ListTile::new()
                                .leading(Icon::new(Icons::PERSON))
                                .title("Account")
                                .trailing(Icon::new(Icons::CHEVRON_RIGHT)),
                        )
                        .child(Divider::new().height(1.0))
                        .child(
                            ListTile::new()
                                .leading(Icon::new(Icons::NOTIFICATIONS))
                                .title("Notifications")
                                .trailing(Icon::new(Icons::CHEVRON_RIGHT)),
                        ),
                ),
            )),
            // Two lines: a subtitle under the title, and any widget behind — here a live
            // switch, which keeps its own tap.
            Box::new(section(
                "Two lines, with a control",
                list(
                    ListTile::new()
                        .leading(CircleAvatar::initials("Home Network"))
                        .title("Wi-Fi")
                        .subtitle(if wifi.get() { "Connected" } else { "Off" })
                        .trailing(Switch::new(wifi.get()).on_toggle(move |on: bool| toggle.set(on))),
                ),
            )),
            // Three lines: a subtitle long enough to wrap onto a second line.
            Box::new(section(
                "Three lines",
                list(
                    ListTile::new()
                        .leading(CircleAvatar::initials("Grace Hopper"))
                        .title("Grace Hopper")
                        .subtitle("Re: compiler meeting — I moved it to Thursday so that everyone can make it.")
                        .three_line()
                        .trailing(Text::new("9:41")),
                ),
            )),
            Box::new(section("Selectable", list(rooms))),
            // Dense tiles are shorter, for a compact list; disabled ones dim and ignore taps.
            Box::new(section(
                "Dense and disabled",
                list(
                    Column::new()
                        .cross_axis_alignment(Align::Stretch)
                        .child(
