//! `DataTable` — a table of text rows that sorts, filters, paginates and selects for
//! you, while the state it shows (sort, page, query, selection) stays in your app.

use frus::{
    Align, Button, Column, DataTable, State, StateContext, StatefulWidget, Text, Variant, Widget,
};

pub const PEOPLE: [(&str, &str, u32); 12] = [
    ("Ada", "Research", 92),
    ("Alan", "Research", 88),
    ("Barbara", "Platform", 75),
    ("Dennis", "Platform", 81),
    ("Edsger", "Research", 67),
    ("Frances", "Compilers", 95),
    ("Grace", "Compilers", 99),
    ("Ken", "Platform", 72),
    ("Linus", "Kernel", 84),
    ("Margaret", "Flight", 97),
    ("Niklaus", "Compilers", 70),
    ("Radia", "Networks", 90),
];

pub const PER_PAGE: usize = 5;

pub fn example() -> Box<dyn Widget> {
    Box::new(PeopleTable.into_widget())
}

/// The demo is a small `StatefulWidget`: the table's whole state lives in one struct, and
/// each handler changes it through a method — the same shape as a real page.
pub struct PeopleTable;

#[derive(Default)]
pub struct PeopleTableState {
    /// The sorted column and its direction; `None` keeps the source order.
    pub sort: Option<(usize, bool)>,
    /// 1-based page.
    page: usize,
    query: String,
    /// Checked rows, as indices into `PEOPLE` (the table translates through sorting).
    pub checked: Vec<usize>,
}

impl PeopleTableState {
    /// A click on a header: a new column sorts ascending, the same one flips.
    pub fn sort_by(&mut self, column: usize) {
        let ascending = match self.sort {
            Some((current, ascending)) if current == column => !ascending,
            _ => true,
        };
        self.sort = Some((column, ascending));
        self.page = 1;
    }

    fn search(&mut self, query: String) {
        self.query = query;
        self.page = 1;
    }

    pub fn toggle(&mut self, row: usize) {
        if let Some(at) = self.checked.iter().position(|&r| r == row) {
            self.checked.remove(at);
        } else {
            self.checked.push(row);
        }
    }

    /// The header box: everything, or nothing if everything was already checked.
    pub fn toggle_all(&mut self) {
        if self.checked.len() == PEOPLE.len() {
            self.checked.clear();
        } else {
            self.checked = (0..PEOPLE.len()).collect();
        }
    }
}

impl StatefulWidget for PeopleTable {
    type State = PeopleTableState;

    fn create_state(&self) -> PeopleTableState {
        PeopleTableState {
            page: 1,
            ..PeopleTableState::default()
        }
    }
}

impl State for PeopleTableState {
    type Widget = PeopleTable;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let rows = PEOPLE
            .iter()
            .map(|(name, team, score)| vec![name.to_string(), team.to_string(), score.to_string()]);

        let mut table = DataTable::new(["Name", "Team", "Score"], rows)
            .column_widths(&[110.0, 110.0, 70.0])
            // Searching filters every column, before sorting and paging.
            .searchable(
                self.query.as_str(),
                cx.handler(|s: &mut Self, q: String| s.search(q)),
            )
            .empty_text("Nobody matches that search")
            // A header click reports the column; the app decides the direction.
            .on_sort(cx.handler(|s: &mut Self, column: usize| s.sort_by(column)))
            // Checkboxes for multi-selection, with a "check all" box in the header.
            .checkboxes(
                cx.handler(|s: &mut Self, row: usize| s.toggle(row)),
                cx.callback(Self::toggle_all),
            )
            .selected(&self.checked)
            // Shown above the table only while rows are checked.
            .bulk_actions({
                let clear = cx.callback(|s: &mut Self| s.checked.clear());
                move || {
                    vec![Box::new(
                        Button::new("Clear")
                            .variant(Variant::Text)
                            .on_press(clear.clone()),
                    ) as Box<dyn Widget>]
                }
            })
            .paginated(
                self.page,
                PER_PAGE,
                cx.handler(|s: &mut Self, page: usize| s.page = page),
            );
        if let Some((column, ascending)) = self.sort {
            table = table.sorted(column, ascending);
        }

        Box::new(
            Column::new()
                .spacing(8.0)
                .cross_axis_alignment(Align::Start)
                .child(table)
                .child(
                    Text::new(format!("{} checked", self.checked.len())).color(cx.theme().muted),
                ),
        )
    }
}

//! `Table` — a grid of rows and columns that only shows what it is handed: the app
//! sorts its own data and decides what is selected. Cells can be text or widgets.

use frus::{Badge, Color, Colors, Icons, Table, Text, Widget};

use crate::common::shared::{section, sections};

/// One planet: name, moons, and how far from the sun (in astronomical units).
pub const PLANETS: [(&str, u32, f32); 5] = [
    ("Mercury", 0, 0.39),
    ("Venus", 0, 0.72),
    ("Earth", 1, 1.0),
    ("Mars", 2, 1.52),
    ("Jupiter", 95, 5.2),
];

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let sort = cx.use_state(|| (0usize, true));
        let selected = cx.use_state(|| None::<usize>);

        // The base `Table` does not reorder anything: on a header click the app sorts its
        // own rows and hands them back, with `sorted` to draw the arrow.
        let (column, ascending) = sort.get();
        let rows = sorted_planets(column, ascending);

        let on_sort = sort.clone();
        let on_select = selected.clone();
        let sortable = rows
            .iter()
            .fold(
                Table::new(3)
                    .header(&["Planet", "Moons", "Distance (AU)"])
                    .header_icons(&[Some(Icons::PUBLIC), None, None])
                    .column_widths(&[120.0, 80.0, 120.0]),
                |table, &(name, moons, au)| {
                    table.row(&[
                        name,
                        moons.to_string().as_str(),
                        format!("{au:.2}").as_str(),
                    ])
                },
            )
            .sorted(column, ascending)
            .on_sort(move |clicked: usize| {
                on_sort.update(|(c, asc)| {
                    *asc = if *c == clicked { !*asc } else { true };
                    *c = clicked;
                })
            })
            // A row click reports the row as displayed; this table shows the app's order.
            .on_select_row(move |row: usize| on_select.set(Some(row)))
            .selected(&selected.get().into_iter().collect::<Vec<_>>());

        let picked = selected
            .get()
            .and_then(|row| rows.get(row))
            .map_or("Click a row".to_string(), |(name, ..)| {
                format!("Selected: {name}")
            });

        sections(vec![
            Box::new(section("Sortable and selectable", sortable)),
            Box::new(Text::new(picked).color(cx.theme().muted)),
            // A cell can be any widget: build it in a closure, which the table calls again
            // on every rebuild.
            Box::new(section(
                "Widget cells",
                Table::new(2)
                    .header(&["Service", "Status"])
                    .column_widths(&[160.0, 120.0])
                    .widget_row(vec![
                        Box::new(|| Box::new(Text::new("API")) as Box<dyn Widget>),
                        Box::new(|| Box::new(status("Up", "#16A34A")) as Box<dyn Widget>),
                    ])
                    .widget_row(vec![
                        Box::new(|| Box::new(Text::new("Billing")) as Box<dyn Widget>),
                        Box::new(|| Box::new(status("Degraded", "#D97706")) as Box<dyn Widget>),
                    ])
                    .widget_row(vec![
                        Box::new(|| Box::new(Text::new("Search")) as Box<dyn Widget>),
                        Box::new(|| Box::new(status("Down", "#DC2626")) as Box<dyn Widget>),
                    ]),
            )),
        ])
    }))
}

/// A coloured label for a status cell.
pub fn status(label: &str, hex: &str) -> Badge {
    Badge::new(label)
        .background_color(Color::hex(hex))
        .text_color(Colors::WHITE)
}

/// The planets ordered by one column — the sorting the app owns.
pub fn sorted_planets(column: usize, ascending: bool) -> Vec<(&'static str, u32, f32)> {
    let mut rows = PLANETS.to_vec();
    rows.sort_by(|a, b| match column {
        1 => a.1.cmp(&b.1),
        2 => a.2.total_cmp(&b.2),
        _ => a.0.cmp(b.0),
    });
    if !ascending {
        rows.reverse();
    }
    rows
}

//! `BarChart` and `LineChart` — self-painted, themed views of a series of
//! `(label, value)` pairs: bars to compare amounts, a line to read a trend.

use frus::{BarChart, Color, LineChart, Text, Widget};

use crate::common::shared::{section, sections};

const MONTHS: [&str; 6] = ["Jan", "Feb", "Mar", "Apr", "May", "Jun"];
const WEB: [f32; 6] = [12.0, 18.0, 15.0, 22.0, 28.0, 31.0];
const MOBILE: [f32; 6] = [8.0, 11.0, 17.0, 19.0, 21.0, 30.0];

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let picked = cx.use_state(|| None::<(usize, usize)>);
        let hidden = cx.use_state(Vec::<usize>::new);
        let stacked = cx.use_state(|| false);

        let series = || MONTHS.iter().copied().zip(WEB);
        let mobile_color = Color::hex("#F59E0B");

        // Clicking a bar reports `(category, series)`; `selected` rings the one the app
        // pinned. The chart fills the width it is given.
        let pick = picked.clone();
        let clickable = BarChart::new(series())
            .height(180.0)
            .grid(4)
            .on_point(move |category: usize, series: usize| pick.set(Some((category, series))))
            .selected(picked.get());
        let caption = match picked.get() {
            Some((category, _)) => format!("{}: {} visits", MONTHS[category], WEB[category]),
            None => "Click a bar".to_string(),
        };

        // Several series share one scale: grouped side by side, or stacked. A clickable
        // legend lets the reader hide one — the hidden list is the app's state.
        let toggle_series = hidden.clone();
        let flip = stacked.clone();
        let grouped = BarChart::new(series())
            .name("Web")
            .series("Mobile", mobile_color, MOBILE)
            .height(180.0)
            .grid(4)
            .legend(true)
            .stacked(stacked.get())
            .hidden(hidden.get())
            .on_legend(move |index: usize| {
                toggle_series.update(|hidden| {
                    if let Some(at) = hidden.iter().position(|&h| h == index) {
                        hidden.remove(at);
                    } else {
                        hidden.push(index);
                    }
                })
            });

        sections(vec![
            Box::new(section("Bar chart", clickable)),
            Box::new(Text::new(caption).color(cx.theme().muted)),
            Box::new(section("Two series, clickable legend", grouped)),
            Box::new(
                frus::Button::new(if stacked.get() {
                    "Group the bars"
                } else {
                    "Stack the bars"
                })
                .variant(frus::Variant::Outlined)
                .on_press(move || flip.update(|s| *s = !*s)),
            ),
            // The same data as a trend line; `area` fills under it.
            Box::new(section(
                "Line chart",
                LineChart::new(series()).height(160.0).grid(4).area(true),
            )),
            Box::new(section(
                "Two lines",
                LineChart::new(series())
                    .name("Web")
                    .series("Mobile", mobile_color, MOBILE)
                    .height(160.0)
                    .grid(4)
                    .legend(true),
            )),
        ])
    }))
}

