//! `Tree` — a hierarchy (files, categories, an org chart) shown as indented rows that
//! expand and collapse. The app owns the structure and which nodes are open, and hands
//! the tree only the rows that are visible.

use std::collections::HashSet;

use frus::{Align, Column, Text, Tree, Widget};

/// One node: its id, its parent's id (`None` at the root), and its label.
pub const NODES: [(u64, Option<u64>, &str); 9] = [
    (1, None, "src"),
    (2, Some(1), "features"),
    (3, Some(2), "display.rs"),
    (4, Some(2), "navigation.rs"),
    (5, Some(1), "lib.rs"),
    (6, None, "assets"),
    (7, Some(6), "logo.png"),
    (8, None, "Cargo.toml"),
    (9, None, "README.md"),
];

/// A visible row: `(id, depth, label, has children, is expanded)`, what `Tree::node` takes.
pub type VisibleRow = (u64, usize, &'static str, bool, bool);

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let expanded = cx.use_state(|| HashSet::from([1u64]));
        let selected = cx.use_state(|| None::<u64>);

        let toggle = expanded.clone();
        let select = selected.clone();
        // The chevron toggles a node; a click anywhere else on the row selects it.
        let tree = expanded.with(visible_rows).into_iter().fold(
            Tree::new(move |id: u64| {
                toggle.update(|open| {
                    if !open.remove(&id) {
                        open.insert(id);
                    }
                })
            })
            .on_select(move |id: u64| select.set(Some(id)))
            .selected(selected.get()),
            |tree, (id, depth, label, expandable, open)| {
                tree.node(id, depth, label, expandable, open)
            },
        );

        let label = selected
            .get()
            .and_then(|id| NODES.iter().find(|(n, ..)| *n == id))
            .map_or("Nothing selected".to_string(), |(_, _, name)| {
                format!("Selected: {name}")
            });

        Box::new(
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(frus::Container::new().width(300.0).child(tree))
                .child(Text::new(label).color(cx.theme().muted)),
        )
    }))
}

/// The rows to show: every root, and the children of every expanded node, depth first.
pub fn visible_rows(expanded: &HashSet<u64>) -> Vec<VisibleRow> {
    fn walk(parent: Option<u64>, depth: usize, expanded: &HashSet<u64>, out: &mut Vec<VisibleRow>) {
        for &(id, _, label) in NODES.iter().filter(|(_, p, _)| *p == parent) {
            let has_children = NODES.iter().any(|(_, p, _)| *p == Some(id));
            let open = expanded.contains(&id);
            out.push((id, depth, label, has_children, open));
            if has_children && open {
                walk(Some(id), depth + 1, expanded, out);
            }
        }
    }
    let mut rows = Vec::new();
    walk(None, 0, expanded, &mut rows);
    rows
}

//! `Breadcrumb` — the trail from the top of a hierarchy to the current page. Every
//! segment but the last can be clicked to go back up.

use frus::{Align, Breadcrumb, Button, Column, Text, Variant, Widget};

const PATH: [&str; 5] = ["Home", "Documents", "Projects", "frus", "Roadmap"];

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        // How deep we are: the trail shows `PATH[..=depth]`.
        let depth = cx.use_state(|| PATH.len() - 1);

        // `on_select(i)` reports the segment clicked; going there means cutting the trail.
        let go_up = depth.clone();
        let trail = PATH[..=depth.get()].iter().fold(
            Breadcrumb::new(move |i: usize| go_up.set(i)),
            |trail, label| trail.crumb(*label),
        );

        let reset = depth.clone();
        Box::new(
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(trail)
                .child(
                    Text::new(format!("Current page: {}", PATH[depth.get()]))
                        .color(cx.theme().muted),
                )
                .child(
                    Button::new("Back to Roadmap")
                        .variant(Variant::Outlined)
                        .enabled(depth.get() + 1 < PATH.len())
                        .on_press(move || reset.set(PATH.len() - 1)),
                ),
        )
    }))
}

//! `AlertDialog` — a modal box that asks a question and waits for the answer: an
//! optional icon, a title, some content and the buttons that answer it.
//!
//! There is no "show dialog" call. A dialog is **controlled** like every overlay: it is
//! built around a body (`.body(..)`), the application keeps whether it is open, and the
//! buttons change that flag.

use frus::{
    AlertDialog, Align, Button, Column, Icon, Icons, State, StateContext, StatefulWidget, Text,
    Variant, Widget, Wrap,
};

use crate::common::shared::section;

pub fn example() -> Box<dyn Widget> {
    Box::new(AlertDialogDemo.into_widget())
}

struct AlertDialogDemo;

#[derive(Clone, Copy, PartialEq)]
enum Open {
    None,
    Discard,
    Delete,
}

struct AlertDialogDemoState {
    open: Open,
    answer: &'static str,
}

impl AlertDialogDemoState {
    /// Every button of a dialog closes it, and says what was answered.
    fn answer(&mut self, answer: &'static str) {
        self.answer = answer;
        self.open = Open::None;
    }
}

impl StatefulWidget for AlertDialogDemo {
    type State = AlertDialogDemoState;

    fn create_state(&self) -> AlertDialogDemoState {
        AlertDialogDemoState {
            open: Open::None,
            answer: "nothing yet",
        }
    }
}

impl State for AlertDialogDemoState {
    type Widget = AlertDialogDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let answer =
            |what: &'static str| cx.callback(move |s: &mut AlertDialogDemoState| s.answer(what));

        // What the dialogs open over: the buttons that open them.
        let body = Column::new()
            .spacing(16.0)
            .cross_axis_alignment(Align::Start)
            .child(section(
                "Open a dialog",
                Wrap::new()
                    .gap(8.0)
                    .run_gap(8.0)
                    .child(Button::new("Discard draft").on_press(
                        cx.callback(|s: &mut AlertDialogDemoState| s.open = Open::Discard),
                    ))
                    .child(
                        Button::new("Delete account")
                            .variant(Variant::Danger)
                            .on_press(
                                cx.callback(|s: &mut AlertDialogDemoState| s.open = Open::Delete),
                            ),
                    ),
            ))
            .child(Text::new(format!("Answer: {}", self.answer)));

        // A title, a sentence, two text buttons. A tap on the scrim around it sends
        // `on_dismiss`, so this one can be left without answering.
        let discard = AlertDialog::new(self.open == Open::Discard)
            .title("Discard draft?")
            .content("Your message has not been sent.")
            .action(
                Button::new("Keep editing")
                    .variant(Variant::Text)
                    .on_press(answer("kept")),
            )
            .action(
                Button::new("Discard")
                    .variant(Variant::Text)
                    .on_press(answer("discarded")),
            )
            .on_dismiss(answer("dismissed"))
            .body(body);

        // An icon centres the title. No `on_dismiss`: the scrim is inert, and the
        // question must be answered with a button.
        let delete = AlertDialog::new(self.open == Open::Delete)
            .icon(Icon::new(Icons::WARNING))
            .title("Delete your account?")
            .content("Everything you stored will be removed. This cannot be undone.")
            .action(
                Button::new("Cancel")
                    .variant(Variant::Text)
                    .on_press(answer("cancelled")),
            )
            .action(
                Button::new("Delete")
                    .variant(Variant::Danger)
                    .on_press(answer("deleted")),
            )
            .body(discard);

        Box::new(delete)
    }
}

//! `Dialog` — the modal surface on its own: rounded, raised, held off the window's edges,
//! with **any content** in it. For what is not a title-and-buttons question: a small form,
//! a picture, a progress report.

use frus::{
    Align, Button, Column, Dialog, FontWeight, Insets, Justify, Padding, Row, State, StateContext,
    StatefulWidget, Text, TextField, Variant, Widget,
};

use crate::common::shared::section;

pub fn example() -> Box<dyn Widget> {
    Box::new(DialogDemo.into_widget())
}

pub struct DialogDemo;

pub struct DialogDemoState {
    pub open: bool,
    /// What is being typed in the dialog, kept apart from the saved value so that
    /// Cancel can throw it away.
    pub draft: String,
    pub name: String,
}

impl DialogDemoState {
    pub fn open(&mut self) {
        self.draft = self.name.clone();
        self.open = true;
    }

    pub fn save(&mut self) {
        self.name = self.draft.trim().to_string();
        self.open = false;
    }

    pub fn cancel(&mut self) {
        self.open = false;
    }
}

impl StatefulWidget for DialogDemo {
    type State = DialogDemoState;

    fn create_state(&self) -> DialogDemoState {
        DialogDemoState {
            open: false,
            draft: String::new(),
            name: "My playlist".into(),
        }
    }
}

impl State for DialogDemoState {
    type Widget = DialogDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let body = section(
            "A form in a dialog",
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(Text::new(format!("Playlist: {}", self.name)))
                .child(Button::new("Rename").on_press(cx.callback(DialogDemoState::open))),
        );

        // The content is ours to lay out: a heading, a field, a row of buttons.
        let content = Column::new()
            .spacing(16.0)
            .cross_axis_alignment(Align::Stretch)
            .child(
                Text::new("Rename playlist")
                    .size(20.0)
                    .weight(FontWeight::SemiBold),
            )
            .child(
                TextField::new(&self.draft)
                    .label("Name")
                    .on_input(cx.handler(|s: &mut DialogDemoState, t: String| s.draft = t))
                    .on_submit(cx.callback(DialogDemoState::save)),
            )
            .child(
                Row::new()
                    .spacing(8.0)
                    .main_axis_alignment(Justify::End)
                    .child(
                        Button::new("Cancel")
                            .variant(Variant::Text)
                            .on_press(cx.callback(DialogDemoState::cancel)),
                    )
                    .child(
                        Button::new("Save")
                            .enabled(!self.draft.trim().is_empty())
                            .on_press(cx.callback(DialogDemoState::save)),
                    ),
            );

        // Corners, widths and the room around it override the defaults (a 28-radius
        // surface at least 280 wide); `background` and `elevation` work the same way.
        let dialog = Dialog::new(self.open)
            .child(Padding::new(24.0, content))
            .radius(16.0)
            .max_width(360.0)
            .inset_padding(Insets::symmetric(16.0, 24.0))
            .on_dismiss(cx.callback(DialogDemoState::cancel))
            .body(body);

        Box::new(dialog)
    }
}

//! `SimpleDialog` and `SimpleDialogOption` — a modal list of choices, answered by
//! picking one row. No buttons: choosing **is** the answer.

use frus::{
    Align, Button, Column, Icon, Icons, Row, SimpleDialog, SimpleDialogOption, State, StateContext,
    StatefulWidget, Text, Widget,
};

use crate::common::shared::section;

pub fn example() -> Box<dyn Widget> {
    Box::new(SimpleDialogDemo.into_widget())
}

const ACCOUNTS: [&str; 3] = ["ada@example.com", "grace@example.com", "alan@example.com"];

struct SimpleDialogDemo;

struct SimpleDialogDemoState {
    open: bool,
    account: usize,
}

impl StatefulWidget for SimpleDialogDemo {
    type State = SimpleDialogDemoState;

    fn create_state(&self) -> SimpleDialogDemoState {
        SimpleDialogDemoState {
            open: false,
            account: 0,
        }
    }
}

impl State for SimpleDialogDemoState {
    type Widget = SimpleDialogDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let body = section(
            "Choose from a list",
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(Text::new(format!(
                    "Signed in as {}",
                    ACCOUNTS[self.account]
                )))
                .child(
                    Button::new("Switch account")
                        .on_press(cx.callback(|s: &mut SimpleDialogDemoState| s.open = true)),
                ),
        );

        // Each option sends its own message; `build()` turns it into the full-width row.
        let dialog = ACCOUNTS.iter().enumerate().fold(
            SimpleDialog::new(self.open).title("Switch account"),
            |dialog, (i, account)| {
                dialog.option(
                    SimpleDialogOption::with_child(
                        Row::new()
                            .spacing(16.0)
                            .cross_axis_alignment(Align::Center)
                            .child(Icon::new(Icons::PERSON))
                            .child(Text::new(*account)),
                    )
                    .on_press(cx.callback(move |s: &mut SimpleDialogDemoState| {
                        s.account = i;
                        s.open = false;
                    }))
                    .build(),
                )
            },
        );
        // A plain text row works too.
        let dialog = dialog
            .option(
                SimpleDialogOption::new(
                    "Cancel",
                    cx.callback(|s: &mut SimpleDialogDemoState| s.open = false),
                )
                .build(),
            )
            .on_dismiss(cx.callback(|s: &mut SimpleDialogDemoState| s.open = false))
            .body(body);

        Box::new(dialog)
    }
}

//! `AboutDialog`, `AboutListTile` and `LicensePage` — the "about this app" box and the
//! page listing the licences of everything the app ships. Every distributed app owes
//! that page; `frus::licenses::add_all(include_str!(..))` fills it from a file generated
//! out of the app's real dependency graph.

use frus::{
    AboutDialog, AboutListTile, Align, Column, ConstrainedBox, Icon, Icons, LicenseNotice,
    LicensePage, Package, State, StateContext, StatefulWidget, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(AboutDemo.into_widget())
}

/// Notices of our own, so the page has something to show. A real app registers the
/// generated file at start-up instead, and `LicensePage::new` reads that registry.
fn sample_notices() -> Vec<LicenseNotice> {
    vec![
        LicenseNotice {
            packages: vec![
                Package::new("frus", "0.3.0"),
                Package::new("frus-widgets", "0.3.0"),
            ],
            text: "MIT License\n\nPermission is hereby granted, free of charge, to any person \
                   obtaining a copy of this software…"
                .into(),
        },
        LicenseNotice {
            packages: vec![Package::new("serde", "1.0.228")],
            text: "Apache License, Version 2.0…".into(),
        },
    ]
}

struct AboutDemo;

struct AboutDemoState {
    about_open: bool,
    showing_licences: bool,
    /// Which package's licence the page has open; `None` is the list.
    package: Option<usize>,
}

impl StatefulWidget for AboutDemo {
    type State = AboutDemoState;

    fn create_state(&self) -> AboutDemoState {
        AboutDemoState {
            about_open: false,
            showing_licences: false,
            package: None,
        }
    }
}

impl State for AboutDemoState {
    type Widget = AboutDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let mut column = Column::new()
            .spacing(24.0)
            .cross_axis_alignment(Align::Stretch);

        // The row a settings screen or a drawer ends with. It only says "open"; the
        // application opens the box.
        column = column.child(section(
            "AboutListTile",
            AboutListTile::new(cx.callback(|s: &mut AboutDemoState| s.about_open = true))
                .application("frus widgets")
                .subtitle("Version 0.1.0")
                .build(),
        ));

        // The page is a column and does not scroll itself: in an app it goes in the
        // page's scroll view, usually on its own route.
        if self.showing_licences {
            column = column.child(section(
                "LicensePage",
                LicensePage::new(
                    self.package,
                    cx.handler(|s: &mut AboutDemoState, which: Option<usize>| s.package = which),
                )
                .notices(sample_notices())
                .application("frus widgets")
                .version("0.1.0")
                .legalese("The gallery itself is MIT OR Apache-2.0.")
                .build(),
            ));
        }

        let body = ConstrainedBox::new(column).max_width(480.0);

        // An alert dialog underneath: name, version, legal line, a way to the licences and
        // a way out. `on_close` also closes it on a tap outside.
        let about = AboutDialog::new(self.about_open)
            .application("frus widgets")
            .version("Version 0.1.0")
            .legalese("A gallery of every frus widget.")
            .icon(Icon::new(Icons::INFO))
            .on_licences(cx.callback(|s: &mut AboutDemoState| {
                s.about_open = false;
                s.showing_licences = true;
            }))
            .on_close(cx.callback(|s: &mut AboutDemoState| s.about_open = false))
            .body(body);

        sections(vec![Box::new(about)])
    }
}

//! `SnackBar`, `SnackBarQueue` and `ScaffoldMessenger` — a short message at the bottom
//! of the screen that goes away by itself.
//!
//! The three split the job: `SnackBar` is the bar, `ScaffoldMessenger` is the layer that
//! places it over the screen, and `SnackBarQueue` — plain application state — decides
//! which message shows and when it leaves.

use std::time::Duration;

use frus::{
    host, Align, Button, Color, Column, Container, ScaffoldMessenger, SnackBar, SnackBarBehavior,
    SnackBarKind, SnackBarPosition, SnackBarQueue, Stack, State, StateContext, StateHandle,
    StatefulWidget, Text, Variant, Widget, Wrap,
};

use crate::common::shared::{section, sections};

/// The preview is phone-sized: it fits a phone's page and reads like a screen.
pub const PREVIEW_WIDTH: f32 = 320.0;

pub fn example() -> Box<dyn Widget> {
    Box::new(SnackBarDemo.into_widget())
}

/// How long a message stays, and how long its fade-out takes.
pub const SHOWN: Duration = Duration::from_millis(3000);
pub const FADE: Duration = Duration::from_millis(300);

/// One queued message. The id tells a timer whether the message it was started for is
/// still the one on screen.
#[derive(Clone)]
pub struct Toast {
    id: u64,
    text: String,
    kind: SnackBarKind,
    undo: bool,
}

pub struct SnackBarDemo;

pub struct SnackBarDemoState {
    queue: SnackBarQueue<Toast>,
    next_id: u64,
    archived: u32,
}

impl SnackBarDemoState {
    /// Queues a message; returns its id when it went straight on screen, so the caller
    /// starts its timer.
    pub fn push(&mut self, text: &str, kind: SnackBarKind, undo: bool) -> Option<u64> {
        let id = self.next_id;
        self.next_id += 1;
        let was_empty = self.queue.is_empty();
        // The queue's own clock is not used: timers below decide when a message leaves.
        self.queue.push(
            Toast {
                id,
                text: text.into(),
                kind,
                undo,
            },
            0.0,
        );
        was_empty.then_some(id)
    }

    /// The id of the message on screen, if any.
    pub fn current_id(&self) -> Option<u64> {
        self.queue.current().map(|toast| toast.id)
    }

    /// Removes the current message; returns the next one's id so its timer starts.
    pub fn dismiss(&mut self) -> Option<u64> {
        self.queue.dismiss();
        self.current_id()
    }
}

/// The message `id` stays `SHOWN`, fades for `FADE`, then makes room for the next one.
/// A message already closed by its action or its cross is not touched again.
pub fn expire_later(handle: StateHandle<SnackBarDemoState>, id: u64) {
    host::after(SHOWN, move || {
        if handle.read(|s| s.current_id()) != Some(id) {
            return;
        }
        handle.set_state(|s| s.queue.start_leaving());
        let handle = handle.clone();
        host::after(FADE, move || {
            if handle.read(|s| s.current_id()) != Some(id) {
                return;
            }
            let mut next = None;
            handle.set_state(|s| next = s.dismiss());
            if let Some(next) = next {
                expire_later(handle.clone(), next);
            }
        });
    });
}

impl StatefulWidget for SnackBarDemo {
    type State = SnackBarDemoState;

    fn create_state(&self) -> SnackBarDemoState {
        SnackBarDemoState {
            queue: SnackBarQueue::new(),
            next_id: 0,
            archived: 0,
        }
    }
}

impl State for SnackBarDemoState {
    type Widget = SnackBarDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let show = |text: &'static str, kind: SnackBarKind, undo: bool| {
            let handle = cx.handle();
            move || {
                let mut started = None;
                handle.set_state(|s| {
                    if undo {
                        s.archived += 1;
                    }
                    started = s.push(text, kind, undo);
                });
                if let Some(id) = started {
                    expire_later(handle.clone(), id);
                }
            }
        };
        // The action and the cross close the message at once.
        let close = {
            let handle = cx.handle();
            move || {
                let mut next = None;
                handle.set_state(|s| next = s.dismiss());
                if let Some(next) = next {
                    expire_later(handle.clone(), next);
                }
            }
        };
        let undo = {
            let close = close.clone();
            let handle = cx.handle();
            move || {
                handle.set_state(|s| s.archived = s.archived.saturating_sub(1));
                close();
            }
        };

        let buttons = Wrap::new()
            .gap(8.0)
            .run_gap(8.0)
            .child(Button::new("Info").on_press(show("Message sent", SnackBarKind::Info, false)))
            .child(
                Button::new("Success")
                    .variant(Variant::Tonal)
                    .on_press(show("Profile saved", SnackBarKind::Success, false)),
            )
            .child(Button::new("Error").variant(Variant::Danger).on_press(show(
                "Could not connect",
                SnackBarKind::Error,
                false,
            )))
            .child(
                Button::new("Archive (with Undo)")
                    .variant(Variant::Outlined)
                    .on_press(show("Chat archived", SnackBarKind::Info, true)),
            );

        // A stand-in for the screen: the messenger layer goes **on top** of it in a
        // `Stack`, and anchors its bar to the bottom. In an app the stack is the whole
        // window, around the `Scaffold`.
        let theme = cx.theme();
        let mut screen = Stack::new().width(PREVIEW_WIDTH).height(200.0).layer(
            Container::new()
                .width(PREVIEW_WIDTH)
                .height(200.0)
                .radius(12.0)
                .border(1.0, theme.outline_variant)
                .color(theme.surface)
                .child(Text::new(format!("{} archived", self.archived)).color(theme.muted))
                .padding(16.0),
        );
        if let Some(toast) = self.queue.current() {
            // A floating bar takes its own width, and keeps a margin around it.
            let mut bar = SnackBar::new(toast.text.clone())
                .behavior(SnackBarBehavior::Floating)
                .width(PREVIEW_WIDTH - 40.0)
                .close_icon(close.clone());
            bar = match toast.kind {
                SnackBarKind::Success => bar.success(),
                SnackBarKind::Error => bar.error(),
                SnackBarKind::Info => bar,
            };
            if toast.undo {
                bar = bar.action("Undo", undo.clone().into());
            }
            let layer = ScaffoldMessenger::new(SnackBarPosition::BottomCenter).toast(bar);
            // Fade in while showing, out while leaving.
            screen = screen.layer(if self.queue.is_leaving() {
                layer.fade_out(0.3)
            } else {
                layer.fade_in(0.25)
            });
        }

        sections(vec![
            Box::new(section(
                "Queued messages",
                Column::new()
                    .spacing(12.0)
                    .cross_axis_alignment(Align::Stretch)
                    .child(buttons)
                    .child(screen),
            )),
            // A bar is a widget like any other: here, still, to compare the looks.
            Box::new(section(
                "Kinds and looks",
                Column::new()
                    .spacing(8.0)
                    .cross_axis_alignment(Align::Stretch)
                    .child(SnackBar::new("Fixed: square, flush with the edges"))
                    .child(
                        SnackBar::new("Floating, with an action")
                            .behavior(SnackBarBehavior::Floating)
                            .action("Retry", cx.callback(|_: &mut SnackBarDemoState| {})),
                    )
                    .child(
                        SnackBar::new("Success")
                            .success()
                            .behavior(SnackBarBehavior::Floating),
                    )
                    .child(
                        SnackBar::new("Error")
                            .error()
                            .behavior(SnackBarBehavior::Floating),
                    )
                    .child(
                        SnackBar::new("Custom colours")
                            .behavior(SnackBarBehavior::Floating)
                            .background(Color::hex("#312E81"))
                            .text_color(Color::hex("#E0E7FF")),
                    ),
            )),
        ])
    }
}

//! `BottomSheet` — a modal panel that slides up from the bottom of the window, over a
//! scrim, for a few contextual actions or a short form. A tap on the scrim closes it.
//!
//! In a page with a `Scaffold`, `Scaffold::bottom_sheet(panel, open, toggle)` does the
//! same in one call; here the sheet is built around the demo itself.

use frus::{
    Align, BottomSheet, Button, Column, FontWeight, Icon, Icons, Insets, ListTile, Padding, State,
    StateContext, StatefulWidget, Text, Widget,
};

use crate::common::shared::section;

pub fn example() -> Box<dyn Widget> {
    Box::new(BottomSheetDemo.into_widget())
}

struct BottomSheetDemo;

struct BottomSheetDemoState {
    /// The sheet is controlled: open while this says so.
    open: bool,
    last: &'static str,
}

impl BottomSheetDemoState {
    fn choose(&mut self, what: &'static str) {
        self.last = what;
        self.open = false;
    }
}

impl StatefulWidget for BottomSheetDemo {
    type State = BottomSheetDemoState;

    fn create_state(&self) -> BottomSheetDemoState {
        BottomSheetDemoState {
            open: false,
            last: "nothing yet",
        }
    }
}

impl State for BottomSheetDemoState {
    type Widget = BottomSheetDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let choose =
            |what: &'static str| cx.callback(move |s: &mut BottomSheetDemoState| s.choose(what));

        // What the sheet holds: a heading and a few actions as list rows.
        let actions = Column::new()
            .cross_axis_alignment(Align::Stretch)
            .child(
                Text::new("Share photo")
                    .size(16.0)
                    .weight(FontWeight::SemiBold),
            )
            .child(
                ListTile::new()
                    .leading(Icon::new(Icons::LINK))
                    .title("Copy link")
                    .on_tap(choose("Copy link")),
            )
            .child(
                ListTile::new()
                    .leading(Icon::new(Icons::EMAIL))
                    .title("Send by email")
                    .on_tap(choose("Send by email")),
            )
            .child(
                ListTile::new()
                    .leading(Icon::new(Icons::DOWNLOAD))
                    .title("Save to device")
                    .on_tap(choose("Save to device")),
            );
        let actions = Padding::new(Insets::new(16.0, 8.0, 24.0, 8.0), actions);

        // What stays behind the sheet.
        let body = section(
            "Contextual actions",
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    Button::new("Share")
                        .icon(Icon::new(Icons::SHARE))
                        .on_press(cx.callback(|s: &mut BottomSheetDemoState| s.open = true)),
                )
                .child(Text::new(format!("Chosen: {}", self.last))),
        );

        // `sheet` sets the content and `body` finishes the widget, so say everything
        // else before `body`.
        let sheet = BottomSheet::new(self.open)
            .on_dismiss(cx.callback(|s: &mut BottomSheetDemoState| s.open = false))
            .sheet(actions)
            .body(body);

        Box::new(sheet)
    }
}

//! `DraggableScrollableSheet` — a panel along the bottom that follows the finger between
//! the heights it may rest at, and hands the gesture over to the list inside it (the
//! "nearby places" sheet of a map). It is not modal: the page behind stays usable.

use frus::{
    host, keyed, Align, Button, Column, Container, Curve, DraggableScrollableSheet, Flex,
    FontWeight, Justify, Row, SheetTo, SingleChildScrollView, Stack, State, StateContext,
    StatefulWidget, Text, Variant, Widget, Wrap,
};

use crate::common::shared::{section, sections};

/// The preview is phone-sized: it fits a phone's page and reads like a screen.
const PREVIEW_WIDTH: f32 = 320.0;

pub fn example() -> Box<dyn Widget> {
    Box::new(SheetDemo.into_widget())
}

/// The key that lets code move the sheet (`host::sheet_to`).
const PLACES_SHEET: &str = "places-sheet";

const PLACES: [&str; 10] = [
    "Bakery", "Bookshop", "Café", "Cinema", "Library", "Market", "Museum", "Park", "Pharmacy",
    "Station",
];

struct SheetDemo;

struct SheetDemoState {
    /// Lowered all the way, the sheet sends `on_dismiss` and the page removes it.
    hidden: bool,
}

impl StatefulWidget for SheetDemo {
    type State = SheetDemoState;

    fn create_state(&self) -> SheetDemoState {
        SheetDemoState { hidden: false }
    }
}

impl State for SheetDemoState {
    type Widget = SheetDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let theme = cx.theme();

        // The sheet draws nothing itself: the surface, its corners and the drag handle
        // are the content's.
        let list = PLACES.iter().fold(
            Column::new().cross_axis_alignment(Align::Start),
            |list, place| list.child(Container::new().padding(12.0).child(Text::new(*place))),
        );
        let handle = Row::new().main_axis_alignment(Justify::Center).child(
            Container::new()
                .width(36.0)
                .height(4.0)
                .radius(2.0)
                .color(theme.muted)
                .margin(10.0),
        );
        let panel = Container::new()
            .color(theme.scheme.surface_container_high)
            .radius(20.0)
            // The list scrolls inside the sheet: the column fills the panel and the
            // scroll view takes what the handle and the title leave.
            .child(
                Flex::column()
                    .flex(1.0)
                    .align(Align::Stretch)
                    .child(handle)
                    .child(
                        Container::new().padding(12.0).child(
                            Text::new("Nearby places")
                                .size(18.0)
                                .weight(FontWeight::SemiBold),
                        ),
                    )
                    .child(SingleChildScrollView::new().flex(1.0).child(list)),
            );

        // The sheet fills the box it is in and sits along its bottom. Its heights are
        // shares of that box: it rests at a quarter, a half or all of it.
        let mut map = Stack::new().width(PREVIEW_WIDTH).height(320.0).layer(
            Container::new()
                .width(PREVIEW_WIDTH)
                .height(320.0)
                .radius(12.0)
                .color(theme.scheme.surface_container)
                .padding(16.0)
                .child(Text::new("The page behind the sheet").color(theme.muted)),
        );
        if !self.hidden {
            map = map.layer(keyed(
                PLACES_SHEET,
                DraggableScrollableSheet::new(panel)
                    .initial(0.5)
                    .min(0.25)
                    .snap_sizes([0.5])
                    .on_dismiss(cx.callback(|s: &mut SheetDemoState| s.hidden = true)),
            ));
        }

        let controls = Wrap::new()
            .gap(8.0)
            .run_gap(8.0)
            .child(
                Button::new("Show the sheet")
                    .enabled(self.hidden)
                    .on_press(cx.callback(|s: &mut SheetDemoState| s.hidden = false)),
            )
            // Moving the sheet from code is an effect, not state: where it rests
            // afterwards is the sheet's own, as if a finger had put it there.
            .child(
                Button::new("Raise it")
                    .variant(Variant::Outlined)
                    .on_press(|| {
                        host::sheet_to(PLACES_SHEET, SheetTo::size(1.0).animate(0.3, Curve::ease()))
                    }),
            );

        sections(vec![Box::new(section(
            "Drag the handle or the list",
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Stretch)
                .child(controls)
                .child(map),
        ))])
    }
}

//! `MaterialBanner` — a message across the top of the content that stays until one of its
//! actions is taken. Between a snack bar (gone in seconds) and a dialog (blocks
//! everything): for something important that can wait, like "you are offline".

use frus::{
    Align, Button, Color, Column, Icon, Icons, MaterialBanner, State, StateContext, StatefulWidget,
    Text, TextStyle, Variant, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(BannerDemo.into_widget())
}

struct BannerDemo;

struct BannerDemoState {
    offline: bool,
    update: bool,
}

impl StatefulWidget for BannerDemo {
    type State = BannerDemoState;

    fn create_state(&self) -> BannerDemoState {
        BannerDemoState {
            offline: true,
            update: true,
        }
    }
}

impl State for BannerDemoState {
    type Widget = BannerDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        // A banner is in the flow, not over it: showing it is simply building it.
        let offline: Box<dyn Widget> = if self.offline {
            MaterialBanner::new("You are offline. Changes will sync when you reconnect.")
                .leading(Icon::new(Icons::CLOUD_OFF))
                .action(
                    Button::new("Dismiss")
                        .variant(Variant::Text)
                        .on_press(cx.callback(|s: &mut BannerDemoState| s.offline = false)),
                )
                .action(
                    Button::new("Retry")
                        .variant(Variant::Text)
                        .on_press(cx.callback(|s: &mut BannerDemoState| s.offline = false)),
                )
                .build()
        } else {
            Box::new(
                Button::new("Show again")
                    .variant(Variant::Outlined)
                    .on_press(cx.callback(|s: &mut BannerDemoState| s.offline = true)),
            )
        };

        // Colours, padding and where the actions go are yours to change.
        let update: Box<dyn Widget> = if self.update {
            MaterialBanner::new("A new version is ready.")
                .leading(Icon::new(Icons::DOWNLOAD).color(Color::hex("#065F46")))
                .background(Color::hex("#D1FAE5"))
                .content_text_style(TextStyle::new(14.0).color(Color::hex("#064E3B")))
                .force_actions_below(true)
                .action(
                    Button::new("Later")
                        .variant(Variant::Text)
                        .on_press(cx.callback(|s: &mut BannerDemoState| s.update = false)),
                )
                .action(
                    Button::new("Update")
                        .on_press(cx.callback(|s: &mut BannerDemoState| s.update = false)),
                )
                .build()
        } else {
            Box::new(
                Button::new("Show again")
                    .variant(Variant::Outlined)
                    .on_press(cx.callback(|s: &mut BannerDemoState| s.update = true)),
            )
        };

        sections(vec![
            Box::new(section("Actions beside the message", offline)),
            Box::new(section(
                "Actions below, custom colours",
                Column::new()
                    .spacing(8.0)
                    .cross_axis_alignment(Align::Stretch)
                    .child_boxed(update)
                    .child(Text::new("The content goes on under the banner.")),
            )),
        ])
    }
}

