//! `LinearProgressIndicator` and `CircularProgressIndicator` — how far along some work is.
//! **Determinate** when you know the share done (a download), **indeterminate** when you
//! do not (waiting for a server).

use std::time::Duration;

use frus::{
    Align, Button, CircularProgressIndicator, Color, Column, LinearProgressIndicator, Row, State,
    StateContext, StatefulWidget, Text, Variant, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(ProgressDemo.into_widget())
}

pub struct ProgressDemo;

pub struct ProgressDemoState {
    /// From 0 to 1.
    pub progress: f32,
    pub running: bool,
}

impl ProgressDemoState {
    /// One tick of the fake download: 2% more, stopping at the end.
    pub fn tick(&mut self) {
        self.progress = (self.progress + 0.02).min(1.0);
        if self.progress >= 1.0 {
            self.running = false;
        }
    }

    pub fn start(&mut self) {
        if self.progress >= 1.0 {
            self.progress = 0.0;
        }
        self.running = true;
    }
}

impl StatefulWidget for ProgressDemo {
    type State = ProgressDemoState;

    fn create_state(&self) -> ProgressDemoState {
        ProgressDemoState {
            progress: 0.35,
            running: false,
        }
    }
}

impl State for ProgressDemoState {
    type Widget = ProgressDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        // The timer exists only while a build asks for it: pause, and it stops.
        if self.running {
            cx.use_interval(
                Duration::from_millis(100),
                cx.callback(ProgressDemoState::tick),
            );
        }

        let controls = Row::new()
            .spacing(8.0)
            .child(
                Button::new(if self.running { "Pause" } else { "Start" }).on_press(cx.callback(
                    |s: &mut ProgressDemoState| {
                        if s.running {
                            s.running = false
                        } else {
                            s.start()
                        }
                    },
                )),
            )
            .child(
                Button::new("Reset")
                    .variant(Variant::Outlined)
                    .on_press(cx.callback(|s: &mut ProgressDemoState| {
                        s.progress = 0.0;
                        s.running = false;
                    })),
            );

        sections(vec![
            // `new(value)` with a value from 0 to 1.
            Box::new(section(
                "Determinate",
                Column::new()
                    .spacing(16.0)
                    .cross_axis_alignment(Align::Start)
                    .child(controls)
                    .child(LinearProgressIndicator::new(self.progress).width(300.0))
                    .child(
                        Row::new()
                            .spacing(16.0)
                            .cross_axis_alignment(Align::Center)
                            .child(CircularProgressIndicator::determinate(self.progress))
                            .child(Text::new(format!("{:.0}%", self.progress * 100.0))),
                    ),
            )),
            // No value: the bar runs and the arc spins for as long as they are shown.
            Box::new(section(
                "Indeterminate",
                Column::new()
                    .spacing(16.0)
                    .cross_axis_alignment(Align::Start)
                    .child(LinearProgressIndicator::indeterminate().width(300.0))
                    .child(CircularProgressIndicator::new()),
            )),
            // Colours, thickness, size and corners are all overridable.
            Box::new(section(
                "Custom look",
                Column::new()
                    .spacing(16.0)
                    .cross_axis_alignment(Align::Start)
                    .child(
                        LinearProgressIndicator::new(self.progress)
                            .width(300.0)
                            .min_height(10.0)
                            .radius(5.0)
                            .color(Color::hex("#16A34A"))
                            .track_color(Color::hex("#DCFCE7")),
                    )
                    .child(
                        Row::new()
                            .spacing(24.0)
                            .child(
                                CircularProgressIndicator::new()
                                    .size(24.0)
                                    .stroke_width(3.0),
                            )
                            .child(
                                CircularProgressIndicator::determinate(self.progress)
                                    .size(64.0)
                                    .stroke_width(8.0)
                                    .color(Color::hex("#DB2777"))
                                    .track_color(Color::hex("#FCE7F3")),
                            ),
                    ),
            )),
        ])
    }
}

//! `Skeleton` — a pulsing grey placeholder in the shape of content that is still loading.
//! Better than a spinner when you know the layout: the page does not jump when the data
//! arrives.

use std::time::Duration;

use frus::{
    Align, Button, CircleAvatar, Column, Row, Skeleton, State, StateContext, StatefulWidget, Text,
    Variant, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(SkeletonDemo.into_widget())
}

struct SkeletonDemo;

struct SkeletonDemoState {
    loading: bool,
}

impl StatefulWidget for SkeletonDemo {
    type State = SkeletonDemoState;

    fn create_state(&self) -> SkeletonDemoState {
        SkeletonDemoState { loading: true }
    }
}

/// The row as it looks while loading: blocks the size of the avatar and the two lines.
fn loading_row() -> Row {
    Row::new()
        .spacing(12.0)
        .cross_axis_alignment(Align::Center)
        .child(Skeleton::new().width(40.0).height(40.0).radius(20.0))
        .child(
            Column::new()
                .cross_axis_alignment(Align::Start)
                .spacing(6.0)
                .child(Skeleton::new().width(160.0).height(14.0))
                .child(Skeleton::new().width(100.0).height(12.0)),
        )
}

/// The same row once loaded: same sizes, so nothing moves.
fn loaded_row(name: &str, role: &str) -> Row {
    Row::new()
        .spacing(12.0)
        .cross_axis_alignment(Align::Center)
        .child(CircleAvatar::initials(name).radius(20.0))
        .child(
            Column::new()
                .spacing(2.0)
                .cross_axis_alignment(Align::Start)
                .child(Text::new(name))
                .child(Text::new(role).size(12.0)),
        )
}

impl State for SkeletonDemoState {
    type Widget = SkeletonDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        // Pretend the data takes two seconds to arrive.
        if self.loading {
            cx.use_interval(
                Duration::from_secs(2),
                cx.callback(|s: &mut SkeletonDemoState| s.loading = false),
            );
        }

        let people = [
            ("Ada", "Engineer"),
            ("Grace", "Admiral"),
            ("Alan", "Mathematician"),
        ];
        let list = people.iter().fold(
            Column::new()
                .cross_axis_alignment(Align::Start)
                .spacing(16.0),
            |list, (name, role)| {
                if self.loading {
                    list.child(loading_row())
                } else {
                    list.child(loaded_row(name, role))
                }
            },
        );

        sections(vec![
            Box::new(section(
                "A list while it loads",
                Column::new()
                    .spacing(16.0)
                    .cross_axis_alignment(Align::Start)
                    .child(
                        Button::new("Load again")
                            .variant(Variant::Outlined)
                            .enabled(!self.loading)
                            .on_press(cx.callback(|s: &mut SkeletonDemoState| s.loading = true)),
                    )
                    .child(list),
            )),
            // Any size and corner: a picture, a heading, a paragraph.
            Box::new(section(
                "Shapes",
                Column::new()
                    .cross_axis_alignment(Align::Start)
                    .spacing(8.0)
                    .child(Skeleton::new().width(280.0).height(120.0).radius(12.0))
                    .child(Skeleton::new().width(200.0).height(20.0))
                    .child(Skeleton::new().width(280.0).height(12.0))
                    .child(Skeleton::new().width(240.0).height(12.0)),
            )),
        ])
    }
}

