//! `AppBar` — the bar at the top of a screen: a leading button, a title, actions, and
//! optionally a widget under it (tabs, a search field). Actions can fold into an
//! overflow menu when the bar runs out of width.

use frus::{
    AppBar, Badge, Color, Colors, Column, Container, IconButton, Icons, TabBar, Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let last = cx.use_state(|| "Nothing yet".to_string());
        let overflow_open = cx.use_state(|| false);
        let tab = cx.use_state(|| 0usize);

        // Every handler here records what was pressed, so the demo shows it.
        let said = |what: &'static str| {
            let last = last.clone();
            move || last.set(what.to_string())
        };

        // `primary(false)` because these bars sit inside a page: a primary bar is the one
        // at the very top of the screen, and makes room for the status bar on a phone.
        let standard = AppBar::new()
            .primary(false)
            .leading(
                IconButton::new(Icons::MENU)
                    .label("Menu")
                    .on_press(said("Menu")),
            )
            .title(Text::new("Inbox"))
            .action(
                IconButton::new(Icons::SEARCH)
                    .label("Search")
                    .on_press(said("Search")),
            )
            .action(Badge::new("3"))
            .build();

        // A centred title, and custom colours and depth.
        let centred = AppBar::new()
            .primary(false)
            .center_title(true)
            .background(Color::hex("#312E81"))
            .foreground(Colors::WHITE)
            .elevation(4.0)
            .leading(
                IconButton::new(Icons::ARROW_BACK)
                    .label("Back")
                    .on_press(said("Back")),
            )
            .title(Text::new("Profile"))
            .build();

        // Foldable actions are text buttons shown inline while they fit, and moved into
        // the `⋯` menu when the bar is too narrow. The menu's open state is the app's.
        let toggle = overflow_open.clone();
        let close_after = |what: &'static str| {
            let last = last.clone();
            let open = overflow_open.clone();
            frus::Callback::new(move || {
                last.set(what.to_string());
                open.set(false);
            })
        };
        let folding = AppBar::new()
            .primary(false)
            // The folding budget is the bar's width; a bar outside a full-width
            // screen says how wide it is.
            .width(320.0)
            .title(Text::new("Report"))
            .overflow(
                overflow_open.get(),
                frus::Callback::new(move || toggle.update(|o| *o = !*o)),
            )
            .foldable_action("Export", close_after("Export"))
            .foldable_action("Share", close_after("Share"))
            .foldable_action("Print", close_after("Print"))
            .foldable_action("Archive", close_after("Archive"))
            .build();

        // `bottom` puts a widget under the bar, inside its background — usually tabs.
        let pick = tab.clone();
        let tabs = TabBar::new(tab.get(), move |i: usize| {
            let pick = pick.clone();
            frus::Callback::new(move || pick.set(i))
        })
        .tab("Mail", Column::new())
        .tab("Chat", Column::new())
        .tab("Meet", Column::new());
        let with_bottom = AppBar::new()
            .primary(false)
            .title(Text::new("Messages"))
            .bottom(tabs)
            .build();

        sections(vec![
            Box::new(section("Leading, title and actions", framed(standard))),
            Box::new(section("Centred title, custom colours", framed(centred))),
            Box::new(section("Foldable actions", framed(folding))),
            Box::new(section("With a bottom", framed(with_bottom))),
            Box::new(Text::new(format!("Last pressed: {}", last.get())).color(cx.theme().muted)),
        ])
    }))
}

/// A bar is as wide as its screen; here the "screen" is a 320-pixel frame.
fn framed(bar: Box<dyn Widget>) -> Container {
    Container::new().width(320.0).child(bar)
}

//! `Scaffold` — the shell of a screen. You fill its slots (app bar, body, navigation,
//! drawer, floating action button, persistent footer) and it lays them out, keeping
//! clear of the system bars and the keyboard.

use frus::{
    Align, AppBar, Button, Center, Color, Column, Container, FabLocation, FloatingActionButton,
    Icons, ListTile, MediaQuery, Row, Scaffold, SegmentedButton, Size, State, StateContext,
    StatefulWidget, Switch, Text, Variant, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(ScaffoldDemo.into_widget())
}

struct ScaffoldDemo;

#[derive(Default)]
struct ScaffoldDemoState {
    /// Index into `LOCATIONS`.
    fab_at: usize,
    drawer_open: bool,
    footer: bool,
    tab: usize,
    count: u32,
}

const LOCATIONS: [(&str, FabLocation); 3] = [
    ("End", FabLocation::EndFloat),
    ("Center", FabLocation::CenterFloat),
    ("Start", FabLocation::StartFloat),
];

impl StatefulWidget for ScaffoldDemo {
    type State = ScaffoldDemoState;

    fn create_state(&self) -> ScaffoldDemoState {
        ScaffoldDemoState::default()
    }
}

impl State for ScaffoldDemoState {
    type Widget = ScaffoldDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let theme = cx.theme();
        let toggle_drawer = cx.callback(|s: &mut Self| s.drawer_open = !s.drawer_open);

        // The screen is built under a description of a 320 × 480 surface with no system
        // bars: the scaffold and its slots read the screen (`MediaQuery::of`) when they
        // are made, so a shell shown in part of a page — a preview, a device frame — is
        // made inside `scope`. A real screen writes none of this.
        let screen = MediaQuery::new(Size::new(320.0, 480.0)).scope(|| {
            // No leading button: a scaffold with a drawer gives its app bar the button that
            // opens it.
            let app_bar = AppBar::new().title(Text::new("Notes")).build();

            let body = Center::new(
                Column::new()
                    .cross_axis_alignment(Align::Start)
                    .spacing(8.0)
                    .child(Text::new(["Notes", "Reminders"][self.tab]).size(20.0))
                    .child(Text::new(format!("{} added", self.count)).color(theme.muted)),
            );

            let drawer = Column::new()
                .cross_axis_alignment(Align::Start)
                .child(
                    Container::new()
                        .padding(16.0)
                        .child(Text::new("Folders").size(18.0)),
                )
                .child(
                    ListTile::new()
                        .title("Personal")
                        .on_tap(toggle_drawer.clone()),
                )
                .child(ListTile::new().title("Work").on_tap(toggle_drawer.clone()));

            let mut shell = Scaffold::new()
                // Without a background the scaffold is transparent.
                .background(theme.background)
                .app_bar(app_bar)
                .body(body)
                // Destinations make a bottom navigation bar.
                .nav(self.tab, cx.handler(|s: &mut Self, i: usize| s.tab = i))
                .destination(Icons::NOTE, "Notes")
                .destination(Icons::ALARM, "Reminders")
                .drawer(drawer, self.drawer_open, toggle_drawer)
                .fab(
                    FloatingActionButton::new(Icons::ADD)
                        .on_press(cx.callback(|s: &mut Self| s.count += 1)),
                )
                .fab_location(LOCATIONS[self.fab_at].1);
            if self.footer {
                // Always visible above the navigation: the screen's committing actions.
                shell = shell.persistent_footer(
                    Row::new()
                        .spacing(8.0)
                        .main_axis_size(frus::MainAxisSize::Min)
                        .child(Button::new("Discard").variant(Variant::Text))
                        .child(Button::new("Save")),
                );
            }
            shell.build()
        });

        let fab_picker = LOCATIONS.iter().fold(
            SegmentedButton::new(
                self.fab_at,
                cx.handler(|s: &mut Self, i: usize| s.fab_at = i),
            ),
            |picker, (name, _)| picker.segment(*name),
        );

        sections(vec![
            Box::new(section("Floating action button location", fab_picker)),
            Box::new(section(
                "Persistent footer",
                Switch::new(self.footer)
                    .on_toggle(cx.handler(|s: &mut Self, on: bool| s.footer = on)),
            )),
            Box::new(section(
                "The screen (the menu button opens the drawer)",
                Container::new()
                    // The 1 px border sits inside the box, so the box is the screen plus 2 px.
                    .width(322.0)
                    .height(482.0)
                    .border(1.0, Color::hex("#A1A1AA"))
                    .clip()
                    .child(screen),
            )),
        ])
    }
}

//! `TabBar` — a row of tabs and the panel of the selected one. Primary for the top
//! level of a screen, secondary for a division inside it; icons, scrolling and swiping
//! between panels are all options.

use frus::{
    Center, Container, Icons, State, StateContext, StatefulWidget, TabBarVariant, Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(TabsDemo.into_widget())
}

struct TabsDemo;

/// One selected index per tab bar in the demo. The bar is **controlled**: it shows the
/// index it is given and reports a press; the state decides.
#[derive(Default)]
struct TabsDemoState {
    selected: [usize; 5],
}

impl StatefulWidget for TabsDemo {
    type State = TabsDemoState;

    fn create_state(&self) -> TabsDemoState {
        TabsDemoState::default()
    }
}

const TOPICS: [&str; 8] = [
    "World", "Business", "Science", "Health", "Sports", "Travel", "Culture", "Food",
];

impl State for TabsDemoState {
    type Widget = TabsDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        // A handler for bar `n`: the index it reports goes into slot `n`.
        let select = |n: usize| cx.handler(move |s: &mut Self, i: usize| s.selected[n] = i);
        let tabs = |n: usize| frus::TabBar::new(self.selected[n], select(n));

        // Only the selected tab's content is built; the bar is as tall as that panel.
        let primary = tabs(0)
            .tab("Flights", panel("Search flights"))
            .tab("Trips", panel("Your upcoming trips"))
            .tab("Explore", panel("Ideas for the weekend"));

        // The secondary variant: the indicator spans the whole tab and is square.
        let secondary = tabs(1)
            .variant(TabBarVariant::Secondary)
            .tab("Overview", panel("Overview"))
            .tab("Specifications", panel("Specifications"));

        // An icon over each label makes the row taller; `icon_only_tab` keeps the normal
        // height and uses the label only for screen readers.
        let with_icons = tabs(2)
            .icon_tab(Icons::DIRECTIONS_CAR, "Car", panel("By car"))
            .icon_tab(Icons::DIRECTIONS_TRANSIT, "Transit", panel("By transit"))
            .icon_tab(Icons::DIRECTIONS_BIKE, "Bike", panel("By bike"));
        let icon_only = tabs(3)
            .icon_only_tab(Icons::GRID_VIEW, "Grid", panel("Grid view"))
            .icon_only_tab(Icons::VIEW_LIST, "List", panel("List view"));

        // Many tabs on a narrow screen: each takes the room its label needs and the bar
        // scrolls sideways.
        let scrollable = TOPICS.iter().fold(tabs(4).scrollable(true), |bar, topic| {
            bar.tab(*topic, panel(&format!("Latest in {topic}")))
        });

        // Swipeable: a drag across the panel changes tab. A swipeable set fills the
        // height it is given, so inside a scrolling page it needs a bounded box.
        let swipeable = Container::new().width(320.0).height(180.0).child(
            frus::TabBar::new(self.selected[0], select(0))
                .swipeable(true)
                .tab("Flights", panel("Swipe sideways…"))
                .tab("Trips", panel("…to change tab"))
                .tab("Explore", panel("…like this")),
        );

        sections(vec![
            Box::new(section("Primary", narrow(primary))),
            Box::new(section("Secondary", narrow(secondary))),
            Box::new(section("Icons and labels", narrow(with_icons))),
