            SegmentedButton::new(
                self.labels,
                cx.handler(|s: &mut Self, i: usize| s.labels = i),
            ),
            |picker, (name, _)| picker.segment(*name),
        );

        sections(vec![
            Box::new(section("Labels", picker)),
            Box::new(section(
                "Extended",
                Switch::new(self.extended)
                    .on_toggle(cx.handler(|s: &mut Self, on: bool| s.extended = on)),
