//! `CollapsingHeader` — a tall header at the top of a scrolling page that shrinks to a
//! toolbar as the page scrolls, then stays pinned (or goes entirely).

use frus::{
    Align, CollapsingHeader, Color, Colors, Container, HeaderState, Icon, Icons, ListTile,
    ListView, Text, Widget,
};

use crate::common::shared::{section, sections};

/// How tall the header is before anything scrolls.
const EXPANDED: f32 = 160.0;
/// The frame the page sits in.
const FRAME_HEIGHT: f32 = 400.0;

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        Box::new(section("Pinned at toolbar height", framed(page(false)))),
        Box::new(section("Floating: goes away entirely", framed(page(true)))),
    ])
}

/// A list under a collapsing header.
fn page(floating: bool) -> Box<dyn Widget> {
    // The list's own top padding **is** the header's room: it scrolls away with the
    // content, and the header shrinks by exactly as much.
    let list = ListView::new(30, 56.0, |i| {
        ListTile::new()
            .leading(Icon::new(Icons::PLACE))
            .title(format!("Stop {}", i + 1))
    })
    .padding_each(EXPANDED, 0.0, 0.0, 0.0)
    // The frame's height less its 1 px border, top and bottom.
    .height(FRAME_HEIGHT - 2.0);

    // The builder runs every frame the header moves, with `fraction` going from 0
    // (expanded) to 1 (collapsed). Interpolate on it rather than on pixels, so the
    // header survives a change of either height.
    let header = CollapsingHeader::new(list, header);
    let header = if floating { header.floating() } else { header };
    Box::new(header.build())
}

fn header(state: HeaderState) -> Container {
    let title_size = 30.0 - 10.0 * state.fraction;
    // The header states its width: the band runs across the page.
    Container::new()
        .width(state.width)
        .height(state.height)
        .color(Color::hex("#4F46E5"))
        .padding_each(0.0, 16.0, 12.0, 16.0)
        .child(
            frus::Column::new()
                .main_axis_alignment(frus::Justify::End)
                .cross_axis_alignment(Align::Start)
                .child(
                    Text::new("Coastal route")
                        .size(title_size)
                        .color(Colors::WHITE),
                ),
        )
}

/// The page sits in a 320 × 400 frame, as it would fill a phone's screen.
fn framed(page: Box<dyn Widget>) -> Container {
    Container::new()
        .width(320.0)
        .height(FRAME_HEIGHT)
        .border(1.0, Color::hex("#A1A1AA"))
        .clip()
        .child(page)
}

//! `Steps` — the numbered indicator of a multi-step form or wizard: done steps show a
//! tick, the current one its number in the accent. The navigation (Back, Next) and the
//! validation of each step stay in your state.

use frus::{
    Align, Button, Column, Container, Justify, Row, State, StateContext, StatefulWidget, Steps,
    Switch, Text, Variant, Widget,
};

use crate::common::shared::{section, sections};

pub const STEPS: [&str; 3] = ["Account", "Plan", "Confirm"];

pub fn example() -> Box<dyn Widget> {
    Box::new(WizardDemo.into_widget())
}

pub struct WizardDemo;

#[derive(Default)]
pub struct WizardState {
    pub current: usize,
    /// Step 1's only question; the wizard cannot move on until it is answered.
    pub terms_accepted: bool,
    /// Step 2's choice.
    pub premium: bool,
    pub finished: bool,
}

impl WizardState {
    /// Whether step `i` is complete — what the indicator ticks, and what Next checks.
    pub fn is_done(&self, i: usize) -> bool {
        match i {
            0 => self.terms_accepted,
            1 => self.current > 1,
            _ => self.finished,
        }
    }

    /// Only the first step has a question that must be answered before moving on.
    fn can_advance(&self) -> bool {
        self.current != 0 || self.terms_accepted
    }

    pub fn next(&mut self) {
        if !self.can_advance() {
            return;
        }
        if self.current + 1 < STEPS.len() {
            self.current += 1;
        } else {
            self.finished = true;
        }
    }

    fn back(&mut self) {
        self.current = self.current.saturating_sub(1);
        self.finished = false;
    }

    /// A tap on a marker jumps back to a step already reached, never ahead of it.
    pub fn jump(&mut self, i: usize) {
        if i < self.current {
            self.current = i;
            self.finished = false;
        }
    }
}

impl StatefulWidget for WizardDemo {
    type State = WizardState;

    fn create_state(&self) -> WizardState {
        WizardState::default()
    }
}

impl State for WizardState {
    type Widget = WizardDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        // `completed` says which steps get a tick; without it, every step before the
        // current one counts as done.
        let indicator = Steps::new(STEPS)
            .current(self.current)
            .completed((0..STEPS.len()).map(|i| self.is_done(i)))
            .on_tap(cx.handler(|s: &mut Self, i: usize| s.jump(i)));

        let page: Box<dyn Widget> = match self.current {
            0 => Box::new(
                Row::new()
                    .spacing(12.0)
                    .main_axis_size(frus::MainAxisSize::Min)
                    .child(
                        Switch::new(self.terms_accepted)
                            .on_toggle(cx.handler(|s: &mut Self, on: bool| s.terms_accepted = on)),
                    )
                    .child(Text::new("I accept the terms")),
            ),
            1 => Box::new(
                Row::new()
                    .spacing(12.0)
                    .main_axis_size(frus::MainAxisSize::Min)
                    .child(
                        Switch::new(self.premium)
                            .on_toggle(cx.handler(|s: &mut Self, on: bool| s.premium = on)),
                    )
                    .child(Text::new("Premium plan")),
            ),
            _ => Box::new(Text::new(if self.finished {
                "All done — welcome aboard!".to_string()
            } else {
                format!("Plan: {}", if self.premium { "Premium" } else { "Free" })
            })),
        };

        let last = self.current + 1 == STEPS.len();
        let wizard = Container::new().width(320.0).child(
            Column::new()
                .spacing(20.0)
                .cross_axis_alignment(Align::Stretch)
                .child(indicator)
                .child(Container::new().height(48.0).child(page))
                .child(
                    Row::new()
                        .main_axis_alignment(Justify::SpaceBetween)
                        .child(
                            Button::new("Back")
                                .variant(Variant::Text)
                                .enabled(self.current > 0)
                                .on_press(cx.callback(Self::back)),
                        )
                        .child(
                            Button::new(if last { "Finish" } else { "Next" })
                                .enabled(self.can_advance() && !self.finished)
                                .on_press(cx.callback(Self::next)),
                        ),
                ),
        );

        sections(vec![
            Box::new(section("A three-step wizard", wizard)),
            // The indicator alone, in another colour, two steps in.
            Box::new(section(
                "Custom colour",
                Container::new().width(320.0).child(
                    Steps::new(["Cart", "Delivery", "Payment", "Done"])
                        .current(2)
                        .color(frus::Color::hex("#16A34A")),
                ),
            )),
        ])
    }
}

//! `Pagination` — a page picker: previous, a window of page numbers, next. Pages are
//! counted from 1, and the current page is the app's state.

use frus::{Align, Column, Pagination, Text, Widget};

use crate::common::shared::{section, sections};

const TOTAL: usize = 20;

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let page = cx.use_state(|| 1usize);
        let few = cx.use_state(|| 2usize);

        // A picker reports the page clicked; the app stores it and shows that page.
        let go = page.clone();
        let many = Pagination::new(page.get(), TOTAL, move |p: usize| {
            let go = go.clone();
            frus::Callback::new(move || go.set(p))
        });

        let go_few = few.clone();
        let short = Pagination::new(few.get(), 3, move |p: usize| {
            let go = go_few.clone();
            frus::Callback::new(move || go.set(p))
        });

        let first = (page.get() - 1) * 10 + 1;
        sections(vec![
            Box::new(section(
                "Many pages",
                Column::new()
                    .spacing(8.0)
                    .cross_axis_alignment(Align::Start)
                    .child(many)
                    .child(
                        Text::new(format!("Showing results {first}–{}", first + 9))
                            .color(cx.theme().muted),
                    ),
            )),
            Box::new(section("Three pages", short)),
            // Disabled: still shows where you are, but nothing can be picked.
            Box::new(section(
                "Disabled",
                Pagination::new(4, 9, |_| frus::Callback::new(|| {})).enabled(false),
            )),
        ])
    }))
}

