//! `SingleChildScrollView` — makes one child scrollable when it is bigger than the room
//! it has: down, across, or both ways. It builds the whole child, so it suits content of
//! a known, modest size; long lists want `ListView`.

use frus::{
    Align, Axis, Color, Column, Container, LinearProgressIndicator, Row, ScrollPosition,
    SingleChildScrollView, Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let progress = cx.use_state(|| 0.0f32);

        // Inside a page that already scrolls, a scroll view needs a bounded size: give it
        // a height (or put it in a box that has one).
        let report = progress.clone();
        let vertical = SingleChildScrollView::new()
            .height(160.0)
            .width(320.0)
            .padding(12.0)
            // `on_scroll` reports where the area is as it moves.
            .on_scroll(move |position: ScrollPosition| report.set(position.fraction_y()))
            .child(paragraphs(12));

        // Sideways: a row wider than the screen.
        let horizontal = SingleChildScrollView::new()
            .axis(Axis::Horizontal)
            .width(320.0)
            .child((0..12).fold(Row::new().spacing(8.0), |row, i| row.child(swatch(i))));

        // Both ways at once, for a big canvas or a wide table. `thumb_visibility` keeps
        // the scrollbars on screen instead of fading out.
        let both = SingleChildScrollView::new()
            .axis(Axis::Both)
            .width(320.0)
            .height(160.0)
            .thumb_visibility(true)
            .child(
                (0..10).fold(
                    Column::new()
                        .cross_axis_alignment(Align::Start)
                        .spacing(8.0),
                    |column, r| {
                        column.child(
                            (0..10)
                                .fold(Row::new().spacing(8.0), |row, c| row.child(swatch(r + c))),
                        )
                    },
                ),
            );

        sections(vec![
            Box::new(section(
                "Vertical, reporting its position",
                Column::new()
                    .cross_axis_alignment(Align::Start)
                    .spacing(8.0)
                    .child(
                        Container::new()
                            .width(320.0)
                            .child(LinearProgressIndicator::new(progress.get())),
                    )
                    .child(vertical),
            )),
            Box::new(section("Horizontal", horizontal)),
            Box::new(section("Both axes", both)),
        ])
    }))
}

/// Enough text to scroll.
fn paragraphs(count: usize) -> Column {
    (1..=count).fold(
        Column::new()
            .cross_axis_alignment(Align::Start)
            .spacing(8.0),
        |column, i| {
            column.child(
                Text::new(format!(
                    "Paragraph {i}. Scroll views build all of their content."
                ))
                .wrap(),
            )
        },
    )
}

/// A coloured square, its hue picked from the index.
fn swatch(i: usize) -> Container {
    const HUES: [&str; 6] = [
        "#F87171", "#FBBF24", "#34D399", "#60A5FA", "#A78BFA", "#F472B6",
    ];
    Container::new()
        .width(64.0)
        .height(64.0)
        .radius(8.0)
        .color(Color::hex(HUES[i % HUES.len()]))
}

//! `ListView` — a virtualised list: only the rows on screen are built, laid out and
//! painted, so ten thousand rows cost what ten do. Every row has the same extent.

use frus::{
    Axis, CircleAvatar, Color, Column, Container, Icon, Icons, ListTile, ListView, Text, Widget,
};

use crate::common::shared::{section, sections};

const COUNT: usize = 10_000;

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let tapped = cx.use_state(|| None::<usize>);

        // `ListView::new(count, extent, build)`: `build(index)` is called only for the
        // rows in view, every frame they are in view. So a row is a plain widget made
        // from the index — not a component with hooks of its own; state that a row
        // shows lives above the list, like `tapped` here.
        let on_tap = tapped.clone();
        let selected = tapped.get();
        let long_list = ListView::new(COUNT, 56.0, move |i| {
            let on_tap = on_tap.clone();
            ListTile::new()
                .leading(Icon::new(Icons::RECEIPT))
                .title(format!("Invoice #{}", i + 1))
                .subtitle(format!("{:.2} €", (i as f32 * 7.31) % 500.0))
                .selected(selected == Some(i))
                .on_tap(move || on_tap.set(Some(i)))
        })
        // A list is 200 px tall unless told otherwise; inside a scrolling page it must
        // have a bounded height.
        .height(280.0)
        .width(320.0);

        // `axis(Axis::Horizontal)` turns it on its side: the extent becomes a width.
        let shelf = ListView::new(50, 72.0, |i| {
            Container::new().padding(4.0).child(
                Column::new()
                    .spacing(4.0)
                    .child(CircleAvatar::initials(format!("User {}", i + 1)))
                    .child(Text::new(format!("#{}", i + 1)).size(12.0)),
            )
        })
        .axis(Axis::Horizontal)
        .height(80.0)
        .width(320.0);

        // `reverse()` starts at the end — the newest message at the bottom of a chat.
        let chat = ListView::new(30, 40.0, |i| {
            Container::new()
                .padding_each(4.0, 12.0, 4.0, 12.0)
                .child(Text::new(format!("Message {}", 30 - i)))
        })
        .reverse()
        .height(160.0)
        .width(320.0);

        sections(vec![
            Box::new(section("10 000 rows", framed(long_list))),
            Box::new(Text::new(match tapped.get() {
                Some(i) => format!("Tapped invoice #{}", i + 1),
                None => "Tap a row".to_string(),
            })),
            Box::new(section("Horizontal", framed(shelf))),
            Box::new(section("Reversed (starts at the end)", framed(chat))),
        ])
    }))
}

/// A thin outline, so the list's bounds show.
fn framed(list: ListView) -> Container {
    Container::new()
        .border(1.0, Color::hex("#A1A1AA"))
        .child(list)
}

//! `GridView` — cells in equal columns, placed row by row: a fixed number of columns,
//! as many as fit a maximum width, or a virtualised grid that only builds the visible
//! rows.

use frus::{Center, Color, Colors, Container, GridView, Text, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // A fixed number of columns. `aspect` makes every tile the same shape
        // (width / height); without it a row is as tall as its tallest cell.
        Box::new(section(
            "Three columns, square tiles",
            Container::new().width(320.0).child((0..9).fold(
                GridView::new(3).width(320.0).gap(8.0).aspect(1.0),
                |grid, i| grid.cell(tile(i)),
            )),
        )),
        // `extent` takes a maximum tile width and works out how many columns fit — more
        // on a wide window, fewer on a phone, with no breakpoints. Its cells are built
        // from their index once the width is known.
        Box::new(section(
            "As many columns as fit (tiles ≤ 72 px)",
            GridView::extent(72.0, 12, tile).gap(6.0).aspect(1.0),
        )),
        // `builder` virtualises: a thousand tiles, only the visible rows built. It
        // scrolls by itself, so it needs a height here.
        Box::new(section(
            "1 000 tiles, virtualised",
            GridView::builder(4, 1000, tile)
                .gap(4.0)
                .tile_height(56.0)
                .width(320.0)
                .height(240.0),
        )),
    ])
}

/// A numbered, coloured tile. A plain function of the index, which is what the grids
/// that build their cells late (`extent`, `builder`) need.
fn tile(i: usize) -> Container {
    const HUES: [&str; 5] = ["#6366F1", "#0EA5E9", "#10B981", "#F59E0B", "#EF4444"];
    Container::new()
        .radius(6.0)
        .color(Color::hex(HUES[i % HUES.len()]))
        .child(Center::new(
            Text::new(format!("{}", i + 1)).color(Colors::WHITE),
        ))
}

//! `PageView` — a scrollable that always comes to rest on a page: onboarding screens, a
//! photo gallery, swipeable panels. Pages are built on demand from their index.

use frus::{Align, Axis, Center, Color, Colors, Column, Container, PageView, Text, Widget};

use crate::common::shared::{section, sections};

const HUES: [&str; 5] = ["#6366F1", "#0EA5E9", "#10B981", "#F59E0B", "#EF4444"];

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let page = cx.use_state(|| 0usize);

        // `on_page_changed` reports the page a reader would name as the finger moves,
        // so a caption follows the picture rather than trailing it.
        let follow = page.clone();
        let full = PageView::new(HUES.len(), |i| card(i, "Swipe sideways"))
            .height(180.0)
            .width(320.0)
            .on_page_changed(move |i: usize| follow.set(i));

        // `viewport_fraction` below 1 shows a sliver of the neighbours — a hint that
        // there is more to swipe to.
        let peek = PageView::new(HUES.len(), |i| {
            Container::new().padding(6.0).child(card(i, "Peek"))
        })
        .viewport_fraction(0.8)
        .height(160.0)
        .width(320.0);

        // Pages can run down instead of across.
        let vertical = PageView::new(HUES.len(), |i| card(i, "Swipe up"))
            .axis(Axis::Vertical)
            .height(160.0)
            .width(320.0);

        sections(vec![
            Box::new(section(
                "Full pages",
                Column::new()
                    .spacing(8.0)
                    .cross_axis_alignment(Align::Start)
                    .child(full)
                    .child(
                        Text::new(format!("Page {} of {}", page.get() + 1, HUES.len()))
                            .color(cx.theme().muted),
                    ),
            )),
            Box::new(section("Neighbours peeking in", peek)),
            Box::new(section("Vertical", vertical)),
        ])
    }))
}

/// One page: a plain widget made from its index.
fn card(i: usize, hint: &str) -> Container {
    Container::new()
        .radius(12.0)
        .color(Color::hex(HUES[i % HUES.len()]))
        .child(Center::new(
