//! `ReorderableList` — a list whose rows can be dragged into a new order: a playlist, a
//! set of favourites, a to-do list. The order is the app's; the list reports each move.

use frus::{
    Align, Column, Container, Icon, Icons, ListTile, ReorderGrab, ReorderableList, Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let songs = cx.use_state(|| {
            vec![
                "Blue in Green",
                "So What",
                "Naima",
                "Take Five",
                "Round Midnight",
            ]
        });
        let tasks = cx.use_state(|| vec!["Write the brief", "Review", "Ship it"]);

        // `on_reorder(from, to)`: `to` is where the row ends up, already accounting for
        // the row having left its old place — remove, then insert.
        let reorder = songs.clone();
        let playlist = songs.get().into_iter().enumerate().fold(
            ReorderableList::new(move |from: usize, to: usize| {
                reorder.update(|list| move_item(list, from, to))
            })
            // A grip at the trailing edge lifts the row on press; the rest of the row
            // keeps its taps and the list keeps scrolling.
            .grab(ReorderGrab::Handle)
            .gap(4.0),
            // A key per row lets the list keep track of a row as it moves.
            |list, (i, title)| {
                list.keyed_row(
                    key_of(title),
                    ListTile::new()
                        .leading(Icon::new(Icons::MUSIC_NOTE))
                        .title(title)
                        .subtitle(format!("Track {}", i + 1)),
                )
            },
        );

        // `LongPress`: hold anywhere on the row to lift it — the touch-screen default.
        let reorder_tasks = tasks.clone();
        let todo = tasks.get().into_iter().fold(
            ReorderableList::new(move |from: usize, to: usize| {
                reorder_tasks.update(|list| move_item(list, from, to))
            })
            .grab(ReorderGrab::LongPress),
            |list, task| list.keyed_row(key_of(task), ListTile::new().title(task)),
        );

        sections(vec![
            Box::new(section(
                "Drag by the handle",
                Container::new().width(320.0).child(playlist),
            )),
            Box::new(section(
                "Hold, then drag",
                Column::new()
                    .spacing(8.0)
                    .cross_axis_alignment(Align::Start)
                    .child(Container::new().width(320.0).child(todo))
                    .child(Text::new(format!("Order: {}", tasks.get().join(" → "))).wrap()),
            )),
        ])
    }))
}

/// Moves the item at `from` so that it ends up at `to`.
pub fn move_item<T>(list: &mut Vec<T>, from: usize, to: usize) {
    if from < list.len() {
        let item = list.remove(from);
        list.insert(to.min(list.len()), item);
    }
}

/// A stable key for a row: here the text itself, which is unique in these lists. A real
/// app uses its own id.
pub fn key_of(text: &str) -> u64 {
    use std::hash::{Hash, Hasher};
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    text.hash(&mut hasher);
    hasher.finish()
}

//! `Dismissible` — swipe a row aside to remove it (or archive it). The row slides out,
//! its gap closes, then the app is told and drops the item from its list.

use frus::{
    keyed, Align, Button, Color, Colors, Column, Container, Icon, Icons, Justify, ListTile, Row,
    Text, Variant, Widget,
};

use crate::common::shared::{section, sections};

const INBOX: [&str; 5] = [
    "Lunch on Friday?",
    "Your invoice is ready",
    "Weekly report",
    "New comment on your post",
    "Password changed",
];

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        // Indices into `INBOX` still shown, and what happened last.
        let mail = cx.use_state(|| (0..INBOX.len()).collect::<Vec<usize>>());
        let last = cx.use_state(|| "Swipe a message left or right".to_string());

        let rows = mail.get().into_iter().fold(
            Column::new().cross_axis_alignment(Align::Stretch),
            |column, id| {
                let (archive, delete) = (mail.clone(), mail.clone());
                let (said_archive, said_delete) = (last.clone(), last.clone());
                // One message per direction. Swiping towards the end (rightwards here)
                // shows `background`; the other way shows `secondary_background`.
                let row = frus::Dismissible::new(
                    Container::new().color(Colors::WHITE).child(
                        ListTile::new()
                            .leading(Icon::new(Icons::MAIL))
                            .title(INBOX[id]),
                    ),
                )
                .width(320.0)
                .height(56.0)
                .background(strip(Icons::ARCHIVE, "Archive", "#16A34A", Justify::Start))
                .secondary_background(strip(Icons::DELETE, "Delete", "#DC2626", Justify::End))
                .on_dismiss_to_end(move || {
                    archive.update(|m| m.retain(|&i| i != id));
                    said_archive.set(format!("Archived “{}”", INBOX[id]));
                })
                .on_dismiss_to_start(move || {
                    delete.update(|m| m.retain(|&i| i != id));
                    said_delete.set(format!("Deleted “{}”", INBOX[id]));
                });
                // A key per item: when a row goes, the ones after it move up, and the key
                // keeps each row's swipe state with its own message.
                column.child(keyed(id, row))
            },
        );

        let restore = mail.clone();
        sections(vec![
            Box::new(section("Inbox", Container::new().width(320.0).child(rows))),
            Box::new(Text::new(last.get()).color(cx.theme().muted)),
            Box::new(
                Button::new("Restore all")
                    .variant(Variant::Outlined)
                    .on_press(move || restore.set((0..INBOX.len()).collect())),
            ),
        ])
    }))
}

/// What shows behind a row as it slides: a colour, an icon and a word.
fn strip(icon: frus::IconData, label: &str, hex: &str, side: Justify) -> Container {
    Container::new()
        .color(Color::hex(hex))
        .padding_each(0.0, 16.0, 0.0, 16.0)
        .child(
            Row::new()
                .main_axis_alignment(side)
                .spacing(8.0)
                .child(Icon::new(icon).color(Colors::WHITE))
                .child(Text::new(label).color(Colors::WHITE)),
        )
}

//! `ExpansionTile` — a list row that opens to show more underneath. It is controlled:
//! it shows the open state it is given and sends a message asking to change it, which
//! is what lets a column of them act as an accordion.

use frus::{Align, Callback, Color, Column, Container, ControlAffinity, Icon, Icons, Text, Widget};

use crate::common::shared::{section, sections};

const FAQ: [(&str, &str); 3] = [
    (
        "How long is delivery?",
        "Two to four working days in most of Europe.",
    ),
    (
        "Can I return an item?",
        "Yes, within thirty days, in its original packaging.",
    ),
    (
        "Do you ship abroad?",
        "We ship to forty countries; the fee is shown at checkout.",
    ),
];

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let open = cx.use_state(|| [true, false, false]);
        let accordion = cx.use_state(|| None::<usize>);

        // Independent tiles: each keeps its own open flag.
        let independent = FAQ.iter().enumerate().fold(
            Column::new().cross_axis_alignment(Align::Stretch),
            |column, (i, (question, answer))| {
                let toggle = open.clone();
                column.child(
                    frus::ExpansionTile::new(
                        *question,
                        open.get()[i],
                        Callback::new(move || toggle.update(|o| o[i] = !o[i])),
                    )
                    .content(Text::new(*answer).wrap()),
                )
            },
        );

        // An accordion: the app keeps one index, so opening one closes the others.
        let exclusive = FAQ.iter().enumerate().fold(
            Column::new().cross_axis_alignment(Align::Stretch),
            |column, (i, (question, answer))| {
                let pick = accordion.clone();
                let is_open = accordion.get() == Some(i);
                column.child(
                    frus::ExpansionTile::new(
                        *question,
                        is_open,
                        Callback::new(move || pick.set(if is_open { None } else { Some(i) })),
                    )
                    .leading(Icon::new(Icons::HELP_OUTLINE))
                    .content(Text::new(*answer).wrap()),
                )
            },
        );

        // The chevron in front, a subtitle, and colours for the open state.
        let toggle = open.clone();
        let styled = frus::ExpansionTile::new(
            "Advanced settings",
            open.get()[1],
            Callback::new(move || toggle.update(|o| o[1] = !o[1])),
        )
        .subtitle("Proxy, cache, logs")
        .control_affinity(ControlAffinity::Leading)
        .background_color(Color::hex("#EEF2FF"))
        .radius(12.0)
        .content(Text::new(
            "Shares its open flag with the second question above.",
        ));

        sections(vec![
            Box::new(section(
                "Independent",
                Container::new().width(320.0).child(independent),
            )),
            Box::new(section(
                "Accordion (one open at a time)",
                Container::new().width(320.0).child(exclusive),
            )),
            Box::new(section(
                "Leading chevron, subtitle, colours",
                Container::new().width(320.0).child(styled),
            )),
        ])
    }))
}

//! `ExpansionPanelList` — a column of panels drawn as one surface that splits apart as a
//! panel opens: a settings screen, an FAQ, the steps of a checkout.

use frus::{Callback, Container, ExpansionPanel, ExpansionPanelList, Text, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let open = cx.use_state(|| vec![0usize]);
        let radio = cx.use_state(|| Some(1usize));

        // `new`: any number open. The message says which panel and whether it is now
        // open; the app keeps the set.
        let toggle = open.clone();
        let free = ExpansionPanelList::new(&open.get(), move |index: usize, now_open: bool| {
            let toggle = toggle.clone();
            Callback::new(move || {
                toggle.update(|set| {
                    set.retain(|&i| i != index);
                    if now_open {
                        set.push(index);
                    }
                })
            })
        })
        .panel(ExpansionPanel::new(
            "Delivery",
            Text::new("Two parcels, one signature."),
        ))
        .panel(
            ExpansionPanel::new("Payment", Text::new("Visa ending 4242.")).subtitle("Card on file"),
        )
        .panel(ExpansionPanel::new(
            "Gift options",
            Text::new("Wrapping and a note."),
        ));

        // `radio`: at most one open. Its message carries the resulting state — `Some(i)`
        // or `None` — so the app just stores it.
        let set = radio.clone();
        let exclusive = ExpansionPanelList::radio(radio.get(), move |state: Option<usize>| {
            let set = set.clone();
            Callback::new(move || set.set(state))
        })
        .panel(ExpansionPanel::new(
            "Account",
            Text::new("Name, e-mail, password."),
        ))
        .panel(ExpansionPanel::new(
            "Notifications",
            Text::new("Push, e-mail, digest."),
        ))
        .panel(ExpansionPanel::new(
            "Privacy",
            Text::new("Who can see your activity."),
        ));

        sections(vec![
            Box::new(section(
                "Several open",
                Container::new().width(320.0).child(free),
            )),
            Box::new(section(
                "One at a time",
                Container::new().width(320.0).child(exclusive),
            )),
        ])
    }))
}

//! `StickyHeader` — a section header that stays at the top of a scroll view while its
//! section is in view, and is pushed off by the next section's header.

use frus::{
    Align, Color, Column, Container, ListTile, SingleChildScrollView, StickyHeader, Text, Widget,
};

use crate::common::shared::{section, sections};

const CONTACTS: [(&str, &[&str]); 5] = [
    ("A", &["Ada", "Alan", "Alonzo", "Anita"]),
    ("B", &["Barbara", "Bjarne", "Brian"]),
    ("D", &["Dennis", "Donald", "Dorothy"]),
    ("G", &["Grace", "Guido"]),
    ("K", &["Ken", "Katherine", "Kristen"]),
