//! `ListWheel` — the spinning cylinder of values you turn to pick one: the control
//! behind time and duration pickers, and the one to reach for a picker of your own.

use frus::{Center, Color, Container, ListWheel, Row, Text, Widget};

use crate::common::shared::{section, sections};

const UNITS: [&str; 5] = ["mm", "cm", "m", "km", "in"];

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let hours = cx.use_state(|| 7usize);
        let minutes = cx.use_state(|| 30usize);
        let unit = cx.use_state(|| 2usize);

        // `selected` is the app's value (applied on the first frame and on every change);
        // `on_selected` reports the row the wheel came to rest on. Rows are built from
        // their index, and `label` says what each is to a screen reader.
        let set_hours = hours.clone();
        let hour_wheel = ListWheel::new(24, 36.0, |i| {
            Center::new(Text::new(format!("{i:02}")).size(20.0))
        })
        .selected(hours.get())
        .on_selected(move |i: usize| set_hours.set(i))
        .label(|i| format!("{i} hours"))
        .width(72.0)
        .height(180.0);

        let set_minutes = minutes.clone();
        let minute_wheel = ListWheel::new(60, 36.0, |i| {
            Center::new(Text::new(format!("{i:02}")).size(20.0))
        })
        .selected(minutes.get())
        .on_selected(move |i: usize| set_minutes.set(i))
        .label(|i| format!("{i} minutes"))
        .width(72.0)
        .height(180.0);

        // A flatter cylinder: a larger `diameter_ratio` curves the rows less.
        let set_unit = unit.clone();
        let unit_wheel = ListWheel::new(UNITS.len(), 36.0, |i| {
            Center::new(Text::new(UNITS[i]).size(18.0))
        })
        .selected(unit.get())
        .on_selected(move |i: usize| set_unit.set(i))
        .label(|i| UNITS[i].to_string())
        .diameter_ratio(3.0)
        .width(96.0)
        .height(180.0);

        sections(vec![
            Box::new(section(
                "Time",
                Container::new()
                    .border(1.0, Color::hex("#A1A1AA"))
                    .radius(12.0)
                    .child(
                        Row::new()
                            .main_axis_size(frus::MainAxisSize::Min)
                            .child(hour_wheel)
                            .child(Text::new(":").size(20.0))
                            .child(minute_wheel),
                    ),
            )),
            Box::new(Text::new(format!(
                "Alarm at {:02}:{:02}",
                hours.get(),
                minutes.get()
            ))),
            Box::new(section("A flatter wheel", unit_wheel)),
            Box::new(Text::new(format!("Unit: {}", UNITS[unit.get()]))),
        ])
    }))
}

//! `Kanban` — a board of columns and cards, with drag and drop between columns. The
//! board is controlled: the app holds the cards and moves one when a drop is reported.

use frus::{Align, Axis, Column, Container, Kanban, SingleChildScrollView, Text, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let board = cx.use_state(|| {
            vec![
                (
                    "To do",
                    vec!["Design the icon", "Write the docs", "Plan the release"],
                ),
                ("Doing", vec!["Fix the scroll bug"]),
                ("Done", vec!["Set up CI"]),
            ]
            .into_iter()
            .map(|(title, cards)| {
                (
                    title.to_string(),
                    cards.into_iter().map(String::from).collect(),
                )
            })
            .collect::<Vec<(String, Vec<String>)>>()
        });

        // `on_move(from_col, from_pos, to_col, to_pos)` fires on a drop; `on_add(col)`
        // when a column's "+ Add card" is pressed. Both just change the app's lists.
        let (moved, added) = (board.clone(), board.clone());
        let kanban = board.get().into_iter().fold(
            Kanban::new(
                move |from_col: usize, from_pos: usize, to_col: usize, to_pos: usize| {
                    moved.update(|columns| {
                        move_card(columns, (from_col, from_pos), (to_col, to_pos))
                    })
                },
            )
            .on_add(move |col: usize| {
                added.update(|columns| {
                    let n = columns[col].1.len() + 1;
                    columns[col].1.push(format!("New card {n}"));
                })
            }),
            |kanban, (title, cards)| kanban.column(title, cards),
        );

        let counts: Vec<String> = board
            .get()
            .iter()
            .map(|(title, cards)| format!("{title}: {}", cards.len()))
            .collect();

        // A board is wider than a phone: let it scroll sideways.
        sections(vec![Box::new(section(
            "Drag cards between columns",
            Column::new()
                .spacing(8.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    SingleChildScrollView::new()
                        .axis(Axis::Horizontal)
                        .width(320.0)
                        .child(Container::new().width(700.0).child(kanban)),
                )
                .child(Text::new(counts.join(" · ")).color(cx.theme().muted)),
        ))])
    }))
}

/// Takes the card at `from` and inserts it at `to` (positions within columns).
pub fn move_card(columns: &mut [(String, Vec<String>)], from: (usize, usize), to: (usize, usize)) {
    let Some(card) = columns
        .get_mut(from.0)
        .filter(|(_, cards)| from.1 < cards.len())
        .map(|(_, cards)| cards.remove(from.1))
    else {
        return;
    };
    if let Some((_, cards)) = columns.get_mut(to.0) {
        // Within one column the removal shifted everything after it up by one.
        let at = if from.0 == to.0 && to.1 > from.1 {
            to.1 - 1
        } else {
            to.1
        };
        cards.insert(at.min(cards.len()), card);
    }
}

//! `RefreshIndicator` — pull a list down past its top to ask for fresh data. The app
//! decides when the answer has arrived: the spinner turns for as long as it says
//! `refreshing(true)`.

use std::time::Duration;

use frus::{Color, Container, ListTile, ListView, RefreshIndicator, Text, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let loading = cx.use_state(|| false);
        let version = cx.use_state(|| 1u32);

        // `on_refresh` is sent when the finger lets go past the threshold. Here a timer
        // stands in for a network call; a real app would start a request, then clear
        // `loading` when it answers.
        let (start, done, bump) = (loading.clone(), loading.clone(), version.clone());
        let on_refresh = move || {
            start.set(true);
            let (done, bump) = (done.clone(), bump.clone());
            frus::host::after(Duration::from_millis(1500), move || {
                bump.update(|v| *v += 1);
                done.set(false);
            });
        };

        let shown = version.get();
        let list = ListView::new(20, 48.0, move |i| {
            ListTile::new().title(format!("Headline {} (fetch #{shown})", i + 1))
        })
        .width(320.0)
        .height(280.0);

        sections(vec![
            Box::new(section(
                "Pull down to refresh",
                Container::new().border(1.0, Color::hex("#A1A1AA")).child(
                    RefreshIndicator::new(list)
                        .on_refresh(on_refresh)
                        .refreshing(loading.get()),
                ),
            )),
            Box::new(
                Text::new(if loading.get() {
                    "Refreshing…"
                } else {
                    "Up to date"
                })
                .color(cx.theme().muted),
            ),
        ])
    }))
}

//! Programmatic scrolling — reading where a scroll area is (`on_scroll` and
//! `ScrollPosition`) and moving it (`keyed` + `frus::host::scroll_to`): a "back to top"
//! button, jumping to an item, a chat that opens at its newest message.

use frus::{
    keyed, Align, Button, Color, Column, Container, ListTile, ListView, Row, ScrollPosition,
    ScrollTo, Text, Variant, Widget, Wrap,
};

use crate::common::shared::{section, sections};

/// The key that names the list, for requests to find it.
const LIST: &str = "scroll-to-demo-list";
const ROW: f32 = 48.0;
const COUNT: usize = 200;

pub fn example() -> Box<dyn Widget> {
    Box::new(frus::component(|cx| {
        let position = cx.use_state(|| None::<ScrollPosition>);

        // Reading: the list reports its position as it moves. `notify_every` limits the
        // messages to one per 24 px (plus where it comes to rest).
        let report = position.clone();
        let list = ListView::new(COUNT, ROW, |i| {
            ListTile::new().title(format!("Row {}", i + 1))
        })
        .height(240.0)
        .width(320.0)
        .on_scroll(move |p: ScrollPosition| report.set(Some(p)))
        .notify_every(24.0);

        // Moving: wrap the area in `keyed(key, …)` and send a request to that key. The
        // request is resolved on the next frame; `instant()` skips the animation.
        let controls = Wrap::new()
            .gap(8.0)
            .run_gap(8.0)
            .child(button("Top", || {
                frus::host::scroll_to(LIST, ScrollTo::start())
            }))
            .child(button("Row 100", || {
                frus::host::scroll_to(LIST, ScrollTo::y(99.0 * ROW))
            }))
            .child(button("Bottom", || {
                frus::host::scroll_to(LIST, ScrollTo::end())
            }))
            .child(button("Row 150, instantly", || {
                frus::host::scroll_to(LIST, ScrollTo::y(149.0 * ROW).instant())
            }));

        let status = match position.get() {
            Some(p) => format!(
                "{:.0}% down · {:.0} px left below",
                p.fraction_y() * 100.0,
                p.remaining_y()
            ),
            None => "Scroll the list".to_string(),
        };

        sections(vec![
            Box::new(section(
                "Move it",
                Column::new()
                    .spacing(12.0)
                    .cross_axis_alignment(Align::Start)
                    .child(controls)
                    .child(
                        Container::new()
                            .border(1.0, Color::hex("#A1A1AA"))
                            .child(keyed(LIST, list)),
                    ),
            )),
            Box::new(section(
                "Read it",
                Row::new()
                    .main_axis_size(frus::MainAxisSize::Min)
                    .child(Text::new(status).color(cx.theme().muted)),
            )),
        ])
    }))
}

fn button(label: &str, on_press: impl Fn() + 'static) -> Button {
    Button::new(label)
        .variant(Variant::Tonal)
        .on_press(on_press)
}

//! `ScrollOverlay` — something drawn over a scroll region and rebuilt from its offset in
//! the same frame: a shadow under a header once content slides beneath it, a rule that
//! fills as you read. (For state that must change — loading more — use `on_scroll`.)

use frus::{Color, Column, Container, ListTile, ListView, ScrollOverlay, Text, Widget};

use crate::common::shared::{section, sections};

const HEADER: f32 = 40.0;

pub fn example() -> Box<dyn Widget> {
    // The list leaves room at its top for the header drawn over it.
    let list = ListView::new(40, 48.0, |i| {
        ListTile::new().title(format!("Chapter {}", i + 1))
    })
    .padding_each(HEADER, 0.0, 0.0, 0.0)
    .width(320.0)
    .height(300.0);

    // The builder gets the offset `(x, y)` and the overlay's box. It runs every frame the
    // list moves, so keep it cheap and give it no state of its own.
    let overlay = ScrollOverlay::new(list, |(_, y), area| {
        let shadow = (y / 24.0).clamp(0.0, 1.0) * 0.25;
        let header = Container::new()
            .width(area.width)
            .height(HEADER)
            .color(Color::hex("#F4F4F5"))
            .padding_each(10.0, 16.0, 0.0, 16.0)
            .shadows([frus::BoxShadow::new(
                0.0,
                2.0,
                6.0,
                Color::rgba(0.0, 0.0, 0.0, shadow),
            )])
            .child(Text::new(format!("Contents — {y:.0} px down")));
        Column::new().child(header)
    });

    sections(vec![Box::new(section(
        "A header whose shadow appears as the list scrolls",
        Container::new()
            .border(1.0, Color::hex("#A1A1AA"))
            .child(overlay),
    ))])
}

//! Scroll behaviour — how scrollables feel at their edges and whether they show
//! scrollbars. The app's default follows the platform; `ScrollConfiguration` changes it
//! for a subtree, and each scrollable can override its own physics and scrollbar.

use frus::{
    Color, Column, Container, ListTile, ListView, Row, ScrollConfiguration, ScrollPhysics,
    Scrollbars, Text, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // Per scrollable: the physics at the edges. Bouncing goes past the edge and
        // springs back; clamping stops dead; `NEVER` does not let the user scroll at all
        // (programmatic scrolling still works).
        Box::new(section(
            "Physics",
            Wrap::new()
                .gap(12.0)
                .run_gap(12.0)
                .child(labelled(
                    "Bouncing",
                    list().physics(ScrollPhysics::BOUNCING),
                ))
                .child(labelled(
                    "Clamping",
                    list().physics(ScrollPhysics::CLAMPING),
                ))
                .child(labelled("Never", list().physics(ScrollPhysics::NEVER))),
        )),
        // For a whole subtree: take the behaviour in force and change one thing. Here,
        // no scrollbars and no overscroll indicator for everything inside.
        Box::new(section(
            "ScrollConfiguration for a subtree",
            ScrollConfiguration::new(
                ScrollConfiguration::of()
                    .with_scrollbars(false)
                    .with_overscroll(false),
                Row::new()
                    .spacing(12.0)
                    .main_axis_size(frus::MainAxisSize::Min)
                    .child(labelled("No scrollbar", list()))
                    .child(labelled("Nor this one", list())),
            ),
        )),
        // A single scroll view can insist on a scrollbar where the platform shows none
        // (on a touch screen, say) and keep it visible.
        Box::new(section(
            "Scrollbar always on",
            frus::SingleChildScrollView::new()
                .scrollbars(Scrollbars::Always)
                .thumb_visibility(true)
                .width(150.0)
                .height(160.0)
                .child((1..=20).fold(Column::new(), |column, i| {
                    column.child(Text::new(format!("Line {i}")))
                })),
        )),
    ])
}

/// A short list to try the behaviours on.
fn list() -> ListView {
    ListView::new(30, 40.0, |i| {
        ListTile::new().dense().title(format!("Item {}", i + 1))
    })
    .width(150.0)
    .height(160.0)
}

fn labelled(label: &str, list: impl Widget + 'static) -> Column {
    Column::new()
        .spacing(4.0)
        .main_axis_size(frus::MainAxisSize::Min)
        .child(Text::new(label).size(12.0))
        .child(
            Container::new()
                .border(1.0, Color::hex("#A1A1AA"))
                .child(list),
        )
}

//! `AnimatedContainer` — a box whose colour, size, corners and opacity glide to each new
//! value instead of jumping there.
//!
//! This is an **implicit** animation: you never start or stop anything. Build the box with
//! new targets and it travels to them over its duration, on its curve.

use frus::{
    component, Align, AnimatedContainer, Button, Column, Component, Curve, Row, Text, Variant,
    Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // The everyday use: one flag in state, two looks for the box. Press the button and
        // the colour, the size and the corners all move together.
        Box::new(section("Toggle between two looks", two_looks())),
        // The same change on three curves: the duration is identical, only the *shape* of
        // the motion differs.
        Box::new(section("Same change, three curves", three_curves())),
    ])
}

fn two_looks() -> Component {
    component(|cx| {
        let expanded = cx.use_state(|| false);
        let on = expanded.get();
        let scheme = &cx.theme().scheme;

        // Every property set on an `AnimatedContainer` shares its duration (seconds) and its
        // curve.
        let card = AnimatedContainer::new(0.4, Curve::ease_in_out())
            .color(if on { scheme.primary } else { scheme.tertiary })
            .size(
                if on { 260.0 } else { 140.0 },
                if on { 120.0 } else { 72.0 },
            )
            .radius(if on { 32.0 } else { 8.0 })
            .padding(16.0)
            .child(
                Text::new(if on { "Expanded" } else { "Compact" }).color(if on {
                    scheme.on_primary
                } else {
                    scheme.on_tertiary
                }),
            );

        let toggle = expanded.clone();
        Box::new(
            Column::new()
                .spacing(16.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    Button::new(if on { "Shrink" } else { "Grow" })
                        .variant(Variant::Tonal)
                        .on_press(move || toggle.update(|on| *on = !*on)),
                )
                .child(card),
        )
    })
}

fn three_curves() -> Component {
    component(|cx| {
        let moved = cx.use_state(|| false);
        let on = moved.get();
        let scheme = &cx.theme().scheme;

        let bar = |curve: Curve, name: &str| {
            Column::new()
                .spacing(6.0)
                .cross_axis_alignment(Align::Start)
                .child(Text::new(name).size(12.0).color(scheme.on_surface_variant))
                .child(
                    AnimatedContainer::new(0.8, curve)
                        .color(scheme.secondary)
                        .size(if on { 96.0 } else { 24.0 }, 24.0)
                        .radius(12.0)
                        // `opacity` animates too, on the same clock as the rest.
                        .opacity(if on { 1.0 } else { 0.5 }),
                )
        };

        let toggle = moved.clone();
        Box::new(
            Column::new()
                .spacing(16.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    Row::new().child(
                        Button::new("Play")
                            .variant(Variant::Outlined)
                            .on_press(move || toggle.update(|on| *on = !*on)),
                    ),
                )
                .child(
                    Wrap::new()
                        .gap(24.0)
                        .run_gap(12.0)
                        .child(bar(Curve::Linear, "Linear"))
                        .child(bar(Curve::ease_out(), "ease_out"))
                        .child(bar(Curve::critical_spring(), "critical_spring")),
                ),
        )
    })
}

//! `Opacity` and `AnimatedOpacity` — see-through by a fixed amount, or fading to each new
//! amount.
//!
//! Both composite the child **as one group**: overlapping parts do not darken where they
//! overlap, which is the difference between fading a picture and fading each of its parts.

use frus::{
    component, Align, Alignment, AnimatedOpacity, Button, Column, Component, Container, Curve,
    Icon, Icons, Opacity, Row, Text, Variant, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // A fixed opacity: a watermark, a placeholder, something deliberately quiet.
        Box::new(section("Opacity", fixed())),
        // A fade: a hint that comes and goes. The child keeps its room while invisible —
        // nothing around it moves.
        Box::new(section("AnimatedOpacity", fading())),
    ])
}

fn fixed() -> Component {
    component(|cx| {
        let scheme = &cx.theme().scheme;
        let swatch = |opacity: f32| {
            Column::new()
                .spacing(6.0)
                .cross_axis_alignment(Align::Center)
                .child(Opacity::new(
                    opacity,
                    Container::new()
                        .width(64.0)
                        .height(64.0)
                        .radius(12.0)
                        .color(scheme.primary)
                        .alignment(Alignment::CENTER)
                        .child(Icon::new(Icons::STAR).color(scheme.on_primary)),
                ))
                .child(Text::new(format!("{opacity}")).size(12.0))
        };
        Box::new(
            Wrap::new()
                .gap(16.0)
                .run_gap(12.0)
                .child(swatch(1.0))
                .child(swatch(0.6))
                .child(swatch(0.3))
                .child(swatch(0.1)),
        )
    })
}

fn fading() -> Component {
    component(|cx| {
        let shown = cx.use_state(|| true);
        let visible = shown.get();
        let scheme = &cx.theme().scheme;

        let toggle = shown.clone();
        Box::new(
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    Row::new().child(
                        Button::new(if visible {
                            "Hide the hint"
                        } else {
                            "Show the hint"
                        })
                        .variant(Variant::Tonal)
                        .on_press(move || toggle.update(|shown| *shown = !*shown)),
                    ),
                )
                // Opacity goes from 1 to 0 over 0.3 s; the box stays where it was.
                .child(AnimatedOpacity::new(
                    if visible { 1.0 } else { 0.0 },
                    0.3,
                    Curve::ease_in_out(),
                    Container::new()
                        .padding(12.0)
                        .radius(8.0)
                        .color(scheme.secondary_container)
                        .child(
                            Text::new("Tip: double-tap a photo to like it.")
                                .color(scheme.on_secondary_container),
                        ),
                ))
                .child(Text::new("…and this line does not move.").size(13.0)),
        )
    })
}

//! `AnimatedAlign` — moves a child to a new anchor inside its box instead of letting it
//! jump: a badge changing corner, a thumb crossing a track.

use frus::{
    component, Align, Alignment, AnimatedAlign, Button, Column, Component, Container, Curve, Row,
    Switch, Text, Variant, Widget,
};

use crate::common::shared::{section, sections};

/// The four corners the dot visits, in order.
const CORNERS: [(Alignment, &str); 4] = [
    (Alignment::TOP_LEFT, "top left"),
    (Alignment::TOP_RIGHT, "top right"),
    (Alignment::BOTTOM_RIGHT, "bottom right"),
    (Alignment::BOTTOM_LEFT, "bottom left"),
];

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // The anchor is the animated quantity: change it and the child slides there.
        Box::new(section("Corner to corner", corners())),
        // The same idea, small: a home-made toggle whose knob glides across.
        Box::new(section("A sliding knob", knob())),
    ])
}

fn corners() -> Component {
    component(|cx| {
        let corner = cx.use_state(|| 0_usize);
        let (alignment, name) = CORNERS[corner.get()];
        let scheme = &cx.theme().scheme;

        let next = corner.clone();
        Box::new(
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    Button::new("Next corner")
                        .variant(Variant::Tonal)
                        .on_press(move || next.update(|i| *i = (*i + 1) % CORNERS.len())),
                )
                .child(
                    Container::new()
                        .width(280.0)
                        .height(140.0)
                        .padding(8.0)
                        .radius(12.0)
                        .color(scheme.surface_container_high)
                        .child(AnimatedAlign::new(
                            alignment,
                            0.5,
                            Curve::ease_in_out(),
                            Container::new()
                                .width(36.0)
                                .height(36.0)
                                .radius(18.0)
                                .color(scheme.primary),
                        )),
                )
                .child(Text::new(format!("Anchored {name}")).size(13.0)),
        )
    })
}

fn knob() -> Component {
    component(|cx| {
        let on = cx.use_state(|| false);
        let is_on = on.get();
        let scheme = &cx.theme().scheme;

        // A framework `Switch` alongside, driven by the same state, for comparison.
        let flip = on.clone();
        let track = Container::new()
            .width(64.0)
            .height(32.0)
            .padding(4.0)
            .radius(16.0)
            .color(if is_on {
                scheme.primary
            } else {
                scheme.outline_variant
            })
            .on_click(move || flip.update(|on| *on = !*on))
            .child(AnimatedAlign::new(
                if is_on {
                    Alignment::CENTER_RIGHT
                } else {
                    Alignment::CENTER_LEFT
                },
                0.15,
                Curve::ease_out(),
                Container::new()
                    .width(24.0)
                    .height(24.0)
                    .radius(12.0)
                    .color(scheme.surface),
            ));

        let set = on.clone();
        Box::new(
            Row::new()
                .spacing(24.0)
                .cross_axis_alignment(Align::Center)
                .child(track)
                .child(Switch::new(is_on).on_toggle(move |value| set.set(value)))
                .child(Text::new(if is_on { "On" } else { "Off" })),
        )
    })
}

//! `AnimatedPadding` — insets its child by an amount that moves to each new value, so a
//! selected row can step in rather than jump.

use frus::{
    component, Align, AnimatedPadding, Column, Component, Container, Curve, Icon, Icons, Row, Text,
    Widget,
};

use crate::common::shared::{section, sections};

const FOLDERS: [&str; 4] = ["Inbox", "Starred", "Sent", "Drafts"];

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // Tap a row: the chosen one is indented further, and the change is animated.
        Box::new(section("Tap a folder", folders())),
    ])
}

fn folders() -> Component {
    component(|cx| {
        let selected = cx.use_state(|| 0_usize);
        let current = selected.get();
        let scheme = &cx.theme().scheme;

        let rows = FOLDERS.iter().enumerate().fold(
            Column::new()
                .spacing(4.0)
                .cross_axis_alignment(Align::Start),
            |column, (index, name)| {
                let chosen = index == current;
                let pick = selected.clone();
                column.child(
                    Container::new()
                        .width(260.0)
                        .radius(8.0)
                        .color(if chosen {
                            scheme.secondary_container
                        } else {
                            scheme.surface_container
                        })
                        .on_click(move || pick.set(index))
                        // Only the padding animates; the row's colour changes at once.
                        .child(AnimatedPadding::new(
                            if chosen { 28.0 } else { 12.0 },
                            0.25,
                            Curve::ease_out(),
                            Row::new()
                                .spacing(12.0)
                                .cross_axis_alignment(Align::Center)
                                .child(Icon::new(Icons::INBOX).size(20.0))
                                .child(Text::new(*name)),
                        )),
                )
            },
        );
        Box::new(rows)
    })
}

//! `AnimatedPositioned` — a `Stack` layer whose pins (left, top, right, bottom, width,
//! height) move to each new value: a panel that slides in, a card that travels.
//!
//! Only a pin set on **both** sides of a change travels: an edge that appears or disappears
//! is a different arrangement, and takes effect at once. So say where the layer is in both
//! states.

use frus::{
    component, Align, Alignment, AnimatedPositioned, Button, Column, Component, Container, Curve,
    Row, Stack, StackFit, Text, Variant, Widget,
};

use crate::common::shared::{section, sections};

const STAGE_HEIGHT: f32 = 180.0;
const PANEL_HEIGHT: f32 = 110.0;

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // A bottom panel: pinned left, right and bottom at a fixed height; its bottom pin
        // is what moves, from below the stage's edge to just inside it.
        Box::new(section("A panel that slides up", panel())),
        // A card: its left and top pins change, so it travels diagonally.
        Box::new(section("A card that travels", travelling_card())),
    ])
}

fn panel() -> Component {
    component(|cx| {
        let open = cx.use_state(|| false);
        let is_open = open.get();
        let scheme = &cx.theme().scheme;

        let sheet = Container::new()
            .radius(12.0)
            .padding(12.0)
            .color(scheme.primary_container)
            .child(Text::new("Details panel").color(scheme.on_primary_container));

        let stage = Stack::new()
            .width(300.0)
            .height(STAGE_HEIGHT)
            // `Expand`: the layers that are not positioned fill the stack — the page behind.
            .fit(StackFit::Expand)
            .layer(
                Container::new()
                    .radius(12.0)
                    .color(scheme.surface_container_high)
                    .padding(12.0)
                    .child(Text::new("Page content")),
            )
            .layer(
                // Closed, the panel waits just below the stage: a stack clips its layers
                // to its own edges, so it is out of sight there. Animating a height to zero instead would squeeze its padding and text
                // into nothing, and they would spill out of the shrinking box.
                AnimatedPositioned::new(0.3, Curve::ease_out(), sheet)
                    .left(8.0)
                    .right(8.0)
                    .bottom(if is_open { 8.0 } else { -PANEL_HEIGHT })
                    .height(PANEL_HEIGHT),
            );

        let toggle = open.clone();
        Box::new(
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    Button::new(if is_open { "Close panel" } else { "Open panel" })
                        .variant(Variant::Tonal)
                        .on_press(move || toggle.update(|open| *open = !*open)),
                )
                .child(stage),
        )
    })
}

fn travelling_card() -> Component {
    component(|cx| {
        let moved = cx.use_state(|| false);
        let far = moved.get();
        let scheme = &cx.theme().scheme;

        let card = Container::new()
            .radius(10.0)
            .color(scheme.tertiary)
            .alignment(Alignment::CENTER)
            .child(Text::new("Card").color(scheme.on_tertiary));

        let stage = Stack::new()
            .width(300.0)
            .height(160.0)
            .fit(StackFit::Expand)
            .layer(
                Container::new()
                    .radius(12.0)
                    .color(scheme.surface_container_high),
            )
            .layer(
                AnimatedPositioned::new(0.6, Curve::ease_in_out(), card)
                    .left(if far { 200.0 } else { 12.0 })
                    .top(if far { 96.0 } else { 12.0 })
                    .width(88.0)
                    .height(52.0),
            );

        let toggle = moved.clone();
        Box::new(
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    Row::new().child(
                        Button::new("Move")
                            .variant(Variant::Outlined)
                            .on_press(move || toggle.update(|far| *far = !*far)),
                    ),
                )
                .child(stage),
        )
    })
}

//! `AnimatedScale`, `AnimatedRotation` and `AnimatedSlide` — grow, turn or shift a child to
//! each new value.
//!
//! All three only change how the child is **painted**: its box stays where the layout put
//! it, so the neighbours never move.

use std::f32::consts::PI;

use frus::{
    component, Align, Alignment, AnimatedRotation, AnimatedScale, AnimatedSlide, Button, Column,
    Component, Container, Curve, Icon, Icons, Row, Text, Variant, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![Box::new(section(
        "Scale, rotation and slide on one flag",
        transforms(),
    ))])
}

fn transforms() -> Component {
    component(|cx| {
        let active = cx.use_state(|| false);
        let on = active.get();
        let scheme = &cx.theme().scheme;

        let tile = |icon| {
            Container::new()
                .width(64.0)
                .height(64.0)
                .radius(12.0)
                .color(scheme.primary_container)
                .alignment(Alignment::CENTER)
                .child(Icon::new(icon).color(scheme.on_primary_container))
        };
        let labelled = |label: &str, child: Box<dyn Widget>| {
            Column::new()
                .spacing(8.0)
                .cross_axis_alignment(Align::Center)
                .child_boxed(child)
                .child(Text::new(label).size(12.0))
        };

        let toggle = active.clone();
        Box::new(
            Column::new()
                .spacing(20.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    Button::new(if on { "Reset" } else { "Animate" })
                        .variant(Variant::Tonal)
                        .on_press(move || toggle.update(|on| *on = !*on)),
                )
                .child(
                    Row::new()
                        .spacing(32.0)
                        // A press feedback, a favourite that pops: scale about the centre.
                        .child(labelled(
                            "AnimatedScale",
                            Box::new(AnimatedScale::new(
                                if on { 1.3 } else { 1.0 },
                                0.25,
                                Curve::ease_out(),
                                tile(Icons::FAVORITE),
                            )),
                        ))
                        // A refresh arrow, an expand chevron: the angle is in radians.
                        .child(labelled(
                            "AnimatedRotation",
                            Box::new(AnimatedRotation::new(
                                if on { PI } else { 0.0 },
                                0.4,
                                Curve::ease_in_out(),
                                tile(Icons::REFRESH),
                            )),
                        ))
                        // The offset is a fraction of the child's own size: 0.5 is half
                        // its width.
                        .child(labelled(
                            "AnimatedSlide",
                            Box::new(AnimatedSlide::new(
                                if on { 0.5 } else { 0.0 },
                                0.0,
                                0.3,
                                Curve::ease_out(),
                                tile(Icons::SEND),
                            )),
                        )),
                ),
        )
    })
}

//! `AnimatedDefaultTextStyle` — the text style handed down to a subtree, moving to each new
