//! `AnimatedFractionallySizedBox` — a box sized as a fraction of the room it is given,
//! moving to each new fraction: a progress bar, a panel that widens.

use frus::{
    component, Align, Alignment, AnimatedFractionallySizedBox, Button, Column, Component,
    Container, Curve, Text, Variant, Widget, Wrap,
};

use crate::common::shared::{section, sections};

const STEPS: [f32; 4] = [0.1, 0.4, 0.75, 1.0];

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // The track is 280 px wide; the fill is a fraction of it, whatever the track's size.
        Box::new(section("Upload progress", progress())),
    ])
}

fn progress() -> Component {
    component(|cx| {
        let step = cx.use_state(|| 0_usize);
        let fraction = STEPS[step.get()];
        let scheme = &cx.theme().scheme;

        let buttons = STEPS.iter().enumerate().fold(
            Wrap::new().gap(8.0).run_gap(8.0),
            |row, (index, value)| {
                let pick = step.clone();
                row.child(
                    Button::new(format!("{:.0} %", value * 100.0))
                        .variant(if index == step.get() {
                            Variant::Filled
                        } else {
                            Variant::Outlined
                        })
                        .on_press(move || pick.set(index)),
                )
            },
        );

        Box::new(
            Column::new()
                .spacing(16.0)
                .cross_axis_alignment(Align::Start)
                .child(buttons)
                .child(
                    Container::new()
                        .width(280.0)
                        .height(16.0)
                        .radius(8.0)
                        .color(scheme.surface_container_highest)
                        .alignment(Alignment::CENTER_LEFT)
                        .child(
                            AnimatedFractionallySizedBox::new(
                                0.5,
                                Curve::ease_out(),
                                Container::new().radius(8.0).color(scheme.primary),
                            )
                            .width_factor(fraction)
                            .height_factor(1.0),
                        ),
                )
                .child(Text::new(format!("{:.0} % uploaded", fraction * 100.0)).size(13.0)),
        )
    })
}

//! `AnimatedSize` — a box that follows its child's size over time: when the content grows
//! or shrinks, the box moves to the new size instead of jumping, and clips the child on
//! the way.

use frus::{
    component, Align, AnimatedSize, Button, Column, Component, Container, Curve, Text, Variant,
    Widget,
};

use crate::common::shared::{section, sections};

const SUMMARY: &str = "frus draws every pixel itself, on the GPU.";
const MORE: &str = "That is why a widget looks the same on the desktop, on Android and in a \
                    browser: no native control is borrowed, so nothing changes from one \
                    platform to the next except what the platform should change — scrolling \
                    physics, page transitions, the text selection handles.";

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // "Read more": the paragraph's box opens and closes smoothly; what is below it
        // follows the box.
        Box::new(section("Read more", read_more())),
    ])
}

fn read_more() -> Component {
    component(|cx| {
        let expanded = cx.use_state(|| false);
        let open = expanded.get();
        let scheme = &cx.theme().scheme;

        // The child changes; `AnimatedSize` notices on the next layout and animates its
        // own box from the old size to the new one.
        let mut body = Column::new()
            .spacing(8.0)
            .cross_axis_alignment(Align::Start)
            .child(Text::new(SUMMARY));
        if open {
            body = body.child(Text::new(MORE).color(scheme.on_surface_variant));
        }

        let toggle = expanded.clone();
        Box::new(
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    Container::new()
                        .width(300.0)
                        .padding(12.0)
                        .radius(12.0)
                        .color(scheme.surface_container)
                        .child(AnimatedSize::new(0.3, body).curve(Curve::ease_in_out())),
                )
                .child(
                    Button::new(if open { "Read less" } else { "Read more" })
                        .variant(Variant::Text)
                        .on_press(move || toggle.update(|open| *open = !*open)),
                ),
        )
    })
}

//! `AnimatedSwitcher` — when the value it shows changes, the old child leaves as the new
//! one arrives: a fade by default, or any transition you hand it.
//!
//! It is given the **value** a child is made from, not the child: values that compare
//! equal are the same child and nothing moves; a different value is a switch.

use frus::{
    component, Align, AnimatedSwitcher, Button, Column, Curve, FadeTransition, FontWeight,
    IconButton, Icons, Row, ScaleTransition, SlideTransition, Text, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let count = cx.use_state(|| 0_i32);
        let n = count.get();
        let primary = cx.theme().primary;

        // One number, three ways to change it on screen.
        let number = move |value: &i32| {
            Text::new(value.to_string())
                .size(40.0)
                .weight(FontWeight::Bold)
                .color(primary)
        };

        let (down, up) = (count.clone(), count.clone());
        let controls = Row::new()
            .spacing(8.0)
            .cross_axis_alignment(Align::Center)
            .child(
                IconButton::new(Icons::REMOVE)
                    .label("Decrement")
                    .on_press(move || down.update(|n| *n -= 1)),
            )
            .child(
                IconButton::new(Icons::ADD)
                    .label("Increment")
                    .on_press(move || up.update(|n| *n += 1)),
            );

        let shown = |title: &str, switcher: AnimatedSwitcher| {
            Column::new()
                .spacing(8.0)
                .cross_axis_alignment(Align::Center)
                .child(Text::new(title).size(12.0))
                .child(switcher)
        };

        sections(vec![
            Box::new(section("Change the value", controls)),
            Box::new(section(
                "Three transitions",
                Wrap::new()
                    .gap(40.0)
                    .run_gap(16.0)
                    // The default: the old child fades out as the new one fades in.
                    .child(shown("Fade", AnimatedSwitcher::new(0.3, n, number)))
                    // `transition` is handed the child and its progress (1 = in place,
                    // 0 = gone), for the arriving child and the leaving one alike.
                    .child(shown(
                        "Scale + fade",
                        AnimatedSwitcher::new(0.3, n, number)
                            .switch_in_curve(Curve::ease_out())
                            .transition(|child, t| {
                                ScaleTransition::new(0.5 + 0.5 * t, FadeTransition::new(t, child))
                            }),
                    ))
                    // Any explicit transition fits: here the digits slide up into place.
                    .child(shown(
                        "Slide",
                        AnimatedSwitcher::new(0.3, n, number).transition(|child, t| {
                            SlideTransition::new(0.0, 1.0 - t, FadeTransition::new(t, child))
                        }),
                    )),
            )),
            Box::new(section(
                "Reset",
                Button::new("Back to zero").on_press(move || count.set(0)),
            )),
        ])
    }))
}

//! `AnimatedCrossFade` — shows one of two children and cross-fades to the other when told
//! to, the box moving between their two sizes as they fade.
//!
//! Reach for it when the two states are known in advance (collapsed / expanded, a
//! summary / its details); `AnimatedSwitcher` is for a value that can be anything.

use frus::{
    component, Align, AnimatedCrossFade, Button, Column, Container, Curve, Icon, Icons, Row, Text,
    Variant, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let expanded = cx.use_state(|| false);
        let open = expanded.get();
        let scheme = &cx.theme().scheme;

        // The first child: one line.
        let summary = Row::new()
            .spacing(8.0)
            .cross_axis_alignment(Align::Center)
            .child(Icon::new(Icons::INBOX).size(20.0))
            .child(Text::new("3 new messages"));

        // The second: taller, with more in it. The box grows from one height to the other
        // while the two fade.
        let details = Column::new()
            .spacing(6.0)
            .cross_axis_alignment(Align::Start)
            .child(Text::new("Ada — Lunch on Friday?"))
            .child(Text::new("Grace — The build is green"))
            .child(Text::new("Alan — Notes from the meeting"));

        let card = Container::new()
            .width(300.0)
            .padding(16.0)
            .radius(12.0)
            .color(scheme.surface_container)
            .child(
                AnimatedCrossFade::new(summary, details, !open, 0.3)
                    // Each child fades on its own curve, and the size on a third.
                    .first_curve(Curve::ease_out())
                    .second_curve(Curve::ease_in())
                    .size_curve(Curve::ease_in_out()),
            );

        let toggle = expanded.clone();
        sections(vec![Box::new(section(
            "Summary and details",
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(card)
                .child(
                    Button::new(if open { "Collapse" } else { "Expand" })
                        .variant(Variant::Tonal)
                        .on_press(move || toggle.update(|open| *open = !*open)),
                ),
        ))])
    }))
}

//! The explicit transitions — `FadeTransition`, `SlideTransition`, `ScaleTransition`,
//! `SizeTransition` (and a turn with `Transform::rotate`) — driven by a number **the
//! application owns**, here an `AnimationController`.
//!
//! The implicit `Animated*` widgets run on the framework's clock. These take the progress
//! itself, so several of them handed the same number move together, and a gesture or a
//! slider can drive them as well as a timer.

use std::f32::consts::TAU;
use std::time::Duration;

use frus::{
    component, eased, Align, Alignment, AnimationController, Button, Color, Column, Container,
    Curve, FadeTransition, Icon, IconData, Icons, Row, ScaleTransition, SizeTransition, SlideFrom,
    SlideTransition, Slider, Text, Transform, Variant, Widget, Wrap,
};

use crate::common::shared::{section, sections};

/// How often the controller is advanced while it runs: about sixty times a second.
const FRAME: Duration = Duration::from_millis(16);

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        // The driver lives as long as the component: `use_ref`, because changing it is not
        // by itself a reason to rebuild. The value the widgets read is a `use_state`, so
        // that each step of the animation does rebuild.
        // It starts at 1: everything in place. Press Reverse to send it all away.
        let controller = cx.use_ref(|| {
            let mut controller = AnimationController::unit();
            controller.set_value(1.0);
            controller
        });
        let progress = cx.use_state(|| 1.0_f32);

        // While the controller is running, a timer advances it once a frame. When it comes
        // to rest, the next build stops asking for the timer, and the timer stops.
        if controller.with(AnimationController::is_animating) {
            let (driver, shown) = (controller.clone(), progress.clone());
            cx.use_interval(FRAME, move || {
                driver.update(|c| {
                    c.tick(FRAME.as_secs_f32());
                });
                shown.set(driver.with(AnimationController::value));
            });
        }

        // Each control changes the controller, then the state, so a build follows and
        // sees that the controller is now running.
        let run = |change: fn(&mut AnimationController)| {
            let (driver, shown) = (controller.clone(), progress.clone());
            move || {
                driver.update(change);
                shown.set(driver.with(AnimationController::value));
            }
        };
        let controls = Wrap::new()
            .gap(8.0)
            .run_gap(8.0)
            .child(Button::new("Forward").on_press(run(|c| c.forward(0.6, Curve::Linear))))
            .child(
                Button::new("Reverse")
                    .variant(Variant::Tonal)
                    .on_press(run(|c| c.reverse(0.6, Curve::Linear))),
            )
            .child(
                // There and back, forever, until stopped.
                Button::new("Repeat")
                    .variant(Variant::Outlined)
                    .on_press(run(|c| c.repeat(1.2, true, Curve::Linear))),
            )
            .child(
                Button::new("Stop")
                    .variant(Variant::Text)
                    .on_press(run(AnimationController::stop)),
            );

        // The same number can come from a finger: dragging the slider stops the controller
        // and sets its value.
        let (driver, shown) = (controller.clone(), progress.clone());
        let t = progress.get();
        let scrub = Row::new()
            .spacing(12.0)
            .cross_axis_alignment(Align::Center)
            .child(Slider::new(t).width(220.0).on_change(move |value| {
                driver.update(|c| {
                    c.stop();
                    c.set_value(value);
                });
                shown.set(value);
            }))
            .child(Text::new(format!("{t:.2}")).size(13.0));

        // The progress is linear; each transition shapes it with a curve of its own.
        let e = eased(t, &Curve::ease_out());
        let scheme = &cx.theme().scheme;
        let square = |icon| tile(icon, scheme.primary, scheme.on_primary);
        let outline = scheme.outline_variant;

        sections(vec![
            Box::new(section(
                "Drive the controller",
                Column::new()
                    .spacing(12.0)
                    .cross_axis_alignment(Align::Start)
                    .child(controls)
                    .child(scrub),
            )),
            Box::new(section(
                "Five transitions, one number",
                Wrap::new()
                    .gap(16.0)
                    .run_gap(16.0)
                    .child(stage(
                        outline,
                        "Fade",
                        FadeTransition::new(e, square(Icons::STAR)),
                    ))
                    // `from_edge`: 0 is beyond the edge, 1 is in place.
                    .child(stage(
                        outline,
                        "Slide",
                        SlideTransition::from_edge(SlideFrom::Left, e, square(Icons::SEND)),
                    ))
                    .child(stage(
                        outline,
                        "Scale",
                        ScaleTransition::new(e, square(Icons::FAVORITE)),
                    ))
                    // Reveals the child down to a fraction of its height.
                    .child(stage(
                        outline,
                        "Size",
                        SizeTransition::new(e, square(Icons::INBOX)),
                    ))
                    .child(stage(
                        outline,
                        "Rotation",
                        Transform::rotate(e * TAU).child(square(Icons::REFRESH)),
                    )),
            )),
        ])
    }))
}

/// A square to animate.
fn tile(icon: IconData, background: Color, foreground: Color) -> Container {
    Container::new()
        .width(56.0)
        .height(56.0)
        .radius(12.0)
        .color(background)
        .alignment(Alignment::CENTER)
        .child(Icon::new(icon).color(foreground))
}

/// A fixed box for one transition, clipped so a slide stays inside it, and its name.
fn stage(outline: Color, name: &str, child: impl Widget + 'static) -> Column {
    Column::new()
        .spacing(6.0)
        .cross_axis_alignment(Align::Center)
        .child(
            Container::new()
                .width(96.0)
                .height(96.0)
                .radius(12.0)
                .clip()
                .border(1.0, outline)
                .alignment(Alignment::CENTER)
                .child(child),
        )
        .child(Text::new(name).size(12.0))
}

//! `DecoratedBoxTransition` and `DefaultTextStyleTransition` — a whole decoration, or a
//! whole text style, a given fraction of the way from one to another.
//!
//! Every part moves by its own rule: colours blend, corners round, shadows grow, sizes and
//! weights step through. Here a slider owns the progress; a controller or a gesture would
//! do as well.

use frus::{
    component, Align, Alignment, BorderRadius, BoxDecoration, BoxShadow, Color, Container,
    DecoratedBoxTransition, DefaultTextStyleTransition, FontWeight, Row, Slider, Text, TextStyle,
    Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let progress = cx.use_state(|| 0.0_f32);
        let t = progress.get();
        let scheme = &cx.theme().scheme;

        // Two complete decorations: a flat square and a raised, rounded card.
        let flat =
            BoxDecoration::filled(scheme.surface_container_high).radius(BorderRadius::uniform(0.0));
        let raised = BoxDecoration::filled(scheme.primary_container)
            .radius(BorderRadius::uniform(28.0))
            .shadow(BoxShadow::new(
                0.0,
                8.0,
                24.0,
                Color::rgba(0.0, 0.0, 0.0, 0.25),
            ));

        // Two text styles; the text below names none of these properties itself, so it
        // wears whatever is handed down.
        let quiet = TextStyle::NONE
            .size(14.0)
            .weight(FontWeight::Regular)
            .color(scheme.on_surface_variant);
        let loud = TextStyle::NONE
            .size(24.0)
            .weight(FontWeight::Bold)
            .color(scheme.on_primary_container);

        let set = progress.clone();
        let slider = Row::new()
            .spacing(12.0)
            .cross_axis_alignment(Align::Center)
            .child(
                Slider::new(t)
                    .width(220.0)
                    .on_change(move |value| set.set(value)),
            )
            .child(Text::new(format!("{t:.2}")).size(13.0));

        sections(vec![
            Box::new(section("Progress", slider)),
            Box::new(section(
                "Decoration and text style, together",
                Container::new()
                    .padding(12.0)
                    .child(DecoratedBoxTransition::between(
                        flat,
                        raised,
                        t,
                        Container::new()
                            .width(240.0)
                            .height(120.0)
                            .alignment(Alignment::CENTER)
                            .child(DefaultTextStyleTransition::between(
                                quiet,
                                loud,
                                t,
                                Text::new("Featured"),
                            )),
                    )),
            )),
        ])
    }))
}

//! `Curve` — the shape of a motion, separate from its duration. Every animated widget
//! takes one; `eased(progress, &curve)` applies one to a progress of your own.
//!
//! Below, one `AnimationController` loops from 0 to 1 and every dot reads the same linear
//! progress through a different curve.

use std::time::Duration;

use frus::{
    component, eased, Align, AnimationController, Column, Container, Curve, Positioned, Row, Stack,
    StackFit, Text, Widget,
};

use crate::common::shared::{section, sections};

/// How often the controller is advanced: about sixty times a second.
const FRAME: Duration = Duration::from_millis(16);
/// The track the dots run along, in logical pixels.
const TRACK: f32 = 200.0;
const DOT: f32 = 16.0;

/// The curves worth knowing, by the name a developer types.
fn curves() -> Vec<(&'static str, Curve)> {
    vec![
        ("Curve::Linear", Curve::Linear),
        ("Curve::ease()", Curve::ease()),
        ("Curve::ease_in()", Curve::ease_in()),
        ("Curve::ease_out()", Curve::ease_out()),
        ("Curve::ease_in_out()", Curve::ease_in_out()),
        ("Curve::Decelerate", Curve::Decelerate),
        ("Curve::critical_spring()", Curve::critical_spring()),
        (
            "ease_in_out_cubic_emphasized()",
            Curve::ease_in_out_cubic_emphasized(),
        ),
        // `Interval` runs a curve over part of the timeline only: staggered motion.
        (
            "Interval 0.5..1.0",
            Curve::Interval {
                begin: 0.5,
                end: 1.0,
                inner: Box::new(Curve::ease_out()),
            },
        ),
        // Your own: a cubic Bézier, as in CSS's `cubic-bezier()`. This one overshoots.
        (
            "Cubic (overshoot)",
            Curve::Cubic {
                x1: 0.34,
                y1: 1.56,
                x2: 0.64,
                y2: 1.0,
            },
        ),
    ]
}

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        // Started when it is made: a sawtooth from 0 to 1 every 1.6 s, for as long as the
        // demo is on screen.
        let controller = cx.use_ref(|| {
            let mut controller = AnimationController::unit();
            controller.repeat(1.6, false, Curve::Linear);
            controller
        });
        let progress = cx.use_state(|| 0.0_f32);
        if controller.with(AnimationController::is_animating) {
            let (driver, shown) = (controller.clone(), progress.clone());
            cx.use_interval(FRAME, move || {
                driver.update(|c| {
                    c.tick(FRAME.as_secs_f32());
                });
                shown.set(driver.with(AnimationController::value));
            });
        }

        let t = progress.get();
        let scheme = &cx.theme().scheme;
        let rows = curves().into_iter().fold(
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start),
            |column, (name, curve)| {
                let x = eased(t, &curve) * (TRACK - DOT);
                column.child(
                    Column::new()
                        .spacing(4.0)
                        .cross_axis_alignment(Align::Start)
                        .child(Text::new(name).size(12.0).color(scheme.on_surface_variant))
                        .child(
                            Stack::new()
                                .width(TRACK)
                                .height(DOT)
                                .fit(StackFit::Expand)
                                .layer(
                                    Container::new()
                                        .radius(DOT / 2.0)
                                        .color(scheme.surface_container_highest),
                                )
                                .layer(
                                    Positioned::new(
                                        Container::new()
                                            .width(DOT)
                                            .height(DOT)
                                            .radius(DOT / 2.0)
                                            .color(scheme.primary),
                                    )
                                    .left(x)
                                    .top(0.0),
                                ),
                        ),
                )
            },
        );

        sections(vec![
            Box::new(section(
                "One progress, many curves",
                Row::new().child(Text::new(format!("progress {t:.2}")).size(13.0)),
            )),
            Box::new(rows),
        ])
    }))
}

//! `Icon::animated` with `AnimatedIcons` — an icon that morphs between two marks: a menu
//! into a cross, play into pause.
//!
//! You say which end you want (`on`); the framework drives the morph there with the same
//! timing as the switches and drawers it usually sits beside.

use frus::{
    component, Align, AnimatedIcons, Column, Container, Icon, IconButton, InkWell, Text, Widget,
    Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        // One flag per bundled pair, kept together.
        let states = cx.use_state(|| [false; 4]);
        let flags = states.get();
        let scheme = &cx.theme().scheme;

        // `AnimatedIcons::all()` lists every bundled pair with its name.
        let tiles = AnimatedIcons::all().enumerate().fold(
            Wrap::new().gap(16.0).run_gap(16.0),
            |row, (index, (name, icon))| {
                let flip = states.clone();
                row.child(
                    Column::new()
                        .spacing(6.0)
                        .cross_axis_alignment(Align::Center)
                        .child(
                            InkWell::new()
                                .radius(16.0)
                                .on_click(move || flip.update(|flags| flags[index] = !flags[index]))
                                .child(
                                    Container::new()
                                        .padding(16.0)
                                        .radius(16.0)
                                        .color(scheme.secondary_container)
                                        .child(
                                            Icon::animated(icon, flags[index])
                                                .size(36.0)
                                                .color(scheme.on_secondary_container),
                                        ),
                                ),
                        )
                        .child(Text::new(name).size(12.0)),
                )
            },
        );

        // The usual home of one: a button whose mark follows what it controls.
        let playing = flags[1];
        let toggle = states.clone();
        let player = IconButton::new(AnimatedIcons::PLAY_PAUSE.at(if playing { 1.0 } else { 0.0 }))
            .label(if playing { "Pause" } else { "Play" })
            .on_press(move || toggle.update(|flags| flags[1] = !flags[1]));

        sections(vec![
            Box::new(section("Tap to morph", tiles)),
            Box::new(section(
                "A still frame of a pair: `AnimatedIconData::at(t)`",
                player,
            )),
        ])
    }))
}

//! `Hero` — a shared element between two pages: during the transition it flies from where
//! it was to where it is going, instead of one copy fading out while another fades in.
//!
//! Two heroes with the **same tag**, one on each side of a page transition, are one thing
//! in two places. In an app, the transition is a route push (`cx.router().push(..)`); here
//! a small `Navigator` inside the demo plays the same part, so you can also try the
//! three page transitions a theme can choose between (`PageTransitionsTheme`).

use std::time::Duration;

use frus::{
    component, Align, Alignment, AnimationController, Button, Callback, CircleAvatar, Column,
    Container, Curve, FontWeight, Hero, InkWell, Navigator, PageTransitionsBuilder,
    PageTransitionsTheme, Text, Themed, UseRef, UseState, Variant, Widget, Wrap,
};

use crate::common::shared::{section, sections};

const PEOPLE: [&str; 3] = ["Ada Lovelace", "Grace Hopper", "Alan Turing"];
const TRANSITIONS: [(&str, PageTransitionsBuilder); 3] = [
    ("Zoom", PageTransitionsBuilder::Zoom),
    ("Slide (iOS)", PageTransitionsBuilder::Cupertino),
    ("Fade forwards", PageTransitionsBuilder::FadeForwards),
];
const FRAME: Duration = Duration::from_millis(16);
const PAGE_WIDTH: f32 = 300.0;
const PAGE_HEIGHT: f32 = 280.0;

/// Which page of the little stack is showing: the list, or one person.
type Route = Option<usize>;

/// A page's key: its depth in the stack, and what it shows.
fn key(route: Route) -> (usize, usize) {
    match route {
        None => (0, usize::MAX),
        Some(person) => (1, person),
    }
}

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let route = cx.use_state(|| None::<usize>);
        // The page being left and the direction (push or pop), while a transition runs.
        let leaving = cx.use_state(|| None::<(Route, bool)>);
        let controller = cx.use_ref(AnimationController::unit);
        let progress = cx.use_state(|| 1.0_f32);
        let style = cx.use_state(|| 0_usize);
        let (style_name, builder) = TRANSITIONS[style.get()];

        // Advance the transition once a frame while it runs; when it ends, forget the page
        // that was left.
        if leaving.get().is_some() {
            let (driver, shown, left) = (controller.clone(), progress.clone(), leaving.clone());
            cx.use_interval(FRAME, move || {
                let mut running = false;
                driver.update(|c| running = c.tick(FRAME.as_secs_f32()));
                shown.set(driver.with(AnimationController::value));
                if !running {
                    left.set(None);
                }
            });
        }

        let go = Go {
            route: route.clone(),
            leaving: leaving.clone(),
            controller: controller.clone(),
            progress: progress.clone(),
            duration: builder.transition_duration(),
        };
        let scheme = &cx.theme().scheme;
        let surface = scheme.surface_container_low;

        let mut navigator = Navigator::new(key(route.get()), page(route.get(), &go, surface))
            .size(PAGE_WIDTH, PAGE_HEIGHT);
        if let Some((left, forward)) = leaving.get() {
            navigator =
                navigator.from(key(left), page(left, &go, surface), progress.get(), forward);
        }

        // The page transition is a theme decision, per platform; here it is overridden for
        // this subtree only.
        let stage = Themed::tweak(
            move |theme| {
                theme.page_transitions =
                    PageTransitionsTheme::default().with(theme.platform, builder);
            },
            Container::new()
                .radius(16.0)
                .clip()
                .border(1.0, scheme.outline_variant)
                .child(navigator),
        );

        let picker = TRANSITIONS.iter().enumerate().fold(
            Wrap::new().gap(8.0).run_gap(8.0),
            |row, (index, (name, _))| {
                let pick = style.clone();
                row.child(
                    Button::new(*name)
                        .variant(if index == style.get() {
                            Variant::Filled
                        } else {
                            Variant::Outlined
                        })
                        .on_press(move || pick.set(index)),
                )
            },
        );

        sections(vec![
            Box::new(section("Tap a person", stage)),
            Box::new(section(
                format!("Page transition: {style_name}").as_str(),
                picker,
            )),
        ])
    }))
}

/// What moving between the pages needs: the state it changes, and how long it takes.
#[derive(Clone)]
struct Go {
    route: UseState<Route>,
    leaving: UseState<Option<(Route, bool)>>,
    controller: UseRef<AnimationController>,
    progress: UseState<f32>,
    duration: f32,
}

impl Go {
    /// A handler that moves to `to`: forwards for a push, backwards for a pop.
    fn to(&self, to: Route) -> Callback {
        let go = self.clone();
        Callback::new(move || {
            let forward = to.is_some();
            go.leaving.set(Some((go.route.get(), forward)));
            go.route.set(to);
            go.controller.update(|c| {
                c.set_value(0.0);
                c.forward(go.duration, Curve::Linear);
            });
            go.progress.set(0.0);
        })
    }
}

/// The two kinds of page: the list of people, and one person.
fn page(route: Route, go: &Go, surface: frus::Color) -> Box<dyn Widget> {
    let content: Box<dyn Widget> = match route {
        None => {
            let people = PEOPLE.iter().enumerate().fold(
                Wrap::new().gap(16.0).run_gap(16.0),
                |row, (index, name)| {
                    row.child(
                        InkWell::new()
                            .radius(12.0)
                            .on_click(go.to(Some(index)))
                            .child(
                                Container::new().padding(8.0).child(
                                    Column::new()
                                        .spacing(6.0)
                                        .cross_axis_alignment(Align::Center)
                                        // The small end of the flight.
                                        .child(Hero::new(
                                            index,
                                            CircleAvatar::initials(*name).size(56.0),
                                        ))
                                        .child(
                                            Text::new(name.split(' ').next().unwrap_or(name))
                                                .size(12.0),
                                        ),
                                ),
                            ),
                    )
                },
            );
            Box::new(
                Column::new()
                    .spacing(16.0)
                    .cross_axis_alignment(Align::Start)
                    .child(Text::new("People").size(18.0).weight(FontWeight::SemiBold))
                    .child(people),
            )
        }
        Some(index) => Box::new(
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Center)
                // The large end: the same tag, so the avatar flies here from the list.
                .child(Hero::new(
                    index,
                    CircleAvatar::initials(PEOPLE[index]).size(120.0),
                ))
                .child(
                    Text::new(PEOPLE[index])
                        .size(18.0)
                        .weight(FontWeight::SemiBold),
                )
                .child(
                    Button::new("Back")
                        .variant(Variant::Tonal)
                        .on_press(go.to(None)),
                ),
        ),
    };
    Box::new(
        Container::new()
            .width(PAGE_WIDTH)
            .height(PAGE_HEIGHT)
            .padding(16.0)
            .color(surface)
            .alignment(Alignment::TOP_CENTER)
            .child(content),
    )
}

//! `DecoratedBox`, `ColoredBox` and `BoxDecoration` — paint a box behind (or in front
//! of) a child: a fill, rounded corners, a border, shadows, a circle.
//!
//! `Container` does all of this too, along with sizing and padding. These widgets say
//! one thing each, and `BoxDecoration` is the value they share — the thing a theme or
//! a design system hands you.

use frus::{
    Border, BorderRadius, BorderSide, BoxDecoration, BoxShadow, BoxShape, Color, ColoredBox,
    DecoratedBox, Padding, SizedBox, Text, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // The plainest box: one colour behind the child, nothing else.
        Box::new(section(
            "ColoredBox",
            ColoredBox::new(
                Color::hex("#FDE68A"),
                Padding::new(
                    12.0,
                    Text::new("A yellow background").color(Color::hex("#78350F")),
                ),
            ),
        )),
        // A fill and a radius, uniform or per corner.
        Box::new(section(
            "Fill and radius",
            Wrap::new()
                .gap(12.0)
                .run_gap(12.0)
                .child(tile(
                    BoxDecoration::filled(Color::hex("#6366F1")).radius(12.0),
                ))
                .child(tile(
                    BoxDecoration::filled(Color::hex("#6366F1")).radius(BorderRadius::top(24.0)),
                ))
                .child(tile(BoxDecoration::filled(Color::hex("#6366F1")).radius(
                    BorderRadius {
                        top_left: 32.0,
                        bottom_right: 32.0,
                        ..BorderRadius::ZERO
                    },
                )))
                .child(tile(
                    BoxDecoration::filled(Color::hex("#6366F1")).shape(BoxShape::Circle),
                )),
        )),
        // Borders: the same on every side, or each side its own width and colour.
        Box::new(section(
            "Borders",
            Wrap::new()
                .gap(12.0)
                .run_gap(12.0)
                .child(tile(
                    BoxDecoration::filled(Color::hex("#EEF2FF"))
                        .radius(8.0)
                        .border(Border::new(2.0, Color::hex("#4F46E5"))),
                ))
                .child(tile(BoxDecoration::filled(Color::hex("#EEF2FF")).border(
                    Border {
                        left: BorderSide::new(Color::hex("#4F46E5"), 6.0),
                        bottom: BorderSide::new(Color::hex("#A5B4FC"), 2.0),
                        ..Border::NONE
                    },
                )))
                .child(tile(
                    BoxDecoration::filled(Color::hex("#EEF2FF"))
                        .shape(BoxShape::Circle)
                        .border(Border::new(3.0, Color::hex("#10B981"))),
                )),
        )),
        // Shadows are a list: a soft wide one and a tight one together read as depth.
        // `BoxShadow::new(dx, dy, blur, colour)`, and `spread` grows it.
        Box::new(section(
            "Shadows",
            Padding::new(
                8.0,
                Wrap::new()
                    .gap(24.0)
                    .run_gap(24.0)
                    .child(tile(
                        BoxDecoration::filled(Color::hex("#FFFFFF"))
                            .radius(12.0)
                            .shadow(BoxShadow::new(
                                0.0,
                                4.0,
                                12.0,
                                Color::rgba(0.0, 0.0, 0.0, 0.2),
                            )),
                    ))
                    .child(tile(
                        BoxDecoration::filled(Color::hex("#FFFFFF"))
                            .radius(12.0)
                            .shadows([
                                BoxShadow::new(0.0, 1.0, 2.0, Color::rgba(0.0, 0.0, 0.0, 0.3)),
                                BoxShadow::new(0.0, 12.0, 24.0, Color::rgba(0.0, 0.0, 0.0, 0.15)),
                            ]),
                    ))
                    .child(tile(
                        BoxDecoration::filled(Color::hex("#FFFFFF"))
                            .radius(12.0)
                            .shadow(
                                BoxShadow::new(0.0, 0.0, 16.0, Color::hex("#6366F1")).spread(2.0),
                            ),
                    )),
            ),
        )),
        // `DecoratedBox::foreground` paints over the child instead of behind it: a frame
        // or a tint over a picture, which a background would be hidden by.
        Box::new(section(
            "In front of the child",
            DecoratedBox::foreground(
                BoxDecoration::filled(Color::rgba(0.31, 0.27, 0.9, 0.25))
                    .radius(8.0)
                    .border(Border::new(2.0, Color::hex("#4F46E5"))),
                ColoredBox::new(
                    Color::hex("#F59E0B"),
                    SizedBox::new(Padding::new(
                        12.0,
                        Text::new("Tinted from the front").color(Color::hex("#FFFFFF")),
                    ))
                    .width(220.0),
                ),
            ),
        )),
    ])
}

/// An 80 × 80 box wearing `decoration`.
fn tile(decoration: BoxDecoration) -> DecoratedBox {
    // The decoration is as big as its child: here an empty 80 × 80 box.
    DecoratedBox::new(decoration, SizedBox::empty().width(80.0).height(80.0))
}

//! Gradients — `LinearGradient`, `RadialGradient` and `SweepGradient`, painted by a
//! `BoxDecoration` (on a `Container` or a `DecoratedBox`).
//!
//! The three are plain structs: start from `new(colors)` and change the public fields
//! you need — stops, tile mode, centre, angles — with struct update syntax.

use frus::{
    Alignment, BoxDecoration, BoxShape, Color, Column, Container, Gradient, LinearGradient,
    RadialGradient, SweepGradient, Text, TileMode, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    let sunset = || {
        vec![
            Color::hex("#F59E0B"),
            Color::hex("#EF4444"),
            Color::hex("#7C3AED"),
        ]
    };

    sections(vec![
        // Left to right by default; `between` sets where the first and last colours are.
        Box::new(section(
            "Linear",
            Wrap::new()
                .gap(12.0)
                .run_gap(12.0)
                .child(swatch("left → right", LinearGradient::new(sunset())))
                .child(swatch(
                    "top-left ↘",
                    LinearGradient::new(sunset())
                        .between(Alignment::TOP_LEFT, Alignment::BOTTOM_RIGHT),
                ))
                // Stops place each colour: here a hard edge halfway, as a flag would have.
                .child(swatch(
                    "hard stops",
                    LinearGradient {
                        stops: Some(vec![0.0, 0.5, 0.5, 1.0]),
                        ..LinearGradient::new(vec![
                            Color::hex("#0EA5E9"),
                            Color::hex("#0EA5E9"),
                            Color::hex("#FACC15"),
                            Color::hex("#FACC15"),
                        ])
                        .between(Alignment::TOP_CENTER, Alignment::BOTTOM_CENTER)
                    },
                ))
                // The tile mode decides what lies past the ends: repeated stripes here.
                .child(swatch(
                    "repeated",
                    LinearGradient {
                        tile_mode: TileMode::Repeated,
                        ..LinearGradient::new(vec![Color::hex("#6366F1"), Color::hex("#C7D2FE")])
                            .between(Alignment::new(-1.0, 0.0), Alignment::new(-0.6, 0.0))
                    },
                )),
        )),
        // From a centre outwards; `radius` is a fraction of the box's shorter side.
        Box::new(section(
            "Radial",
            Wrap::new()
                .gap(12.0)
                .run_gap(12.0)
                .child(swatch("centred", RadialGradient::new(sunset())))
                .child(swatch(
                    "a highlight",
                    RadialGradient {
                        center: Alignment::new(-0.4, -0.4).into(),
                        radius: 0.9,
                        ..RadialGradient::new(vec![Color::hex("#FFFFFF"), Color::hex("#2563EB")])
                    },
                )),
        )),
        // Round a centre, by angle: colour wheels, progress rings, dials.
        Box::new(section(
            "Sweep",
            Wrap::new()
                .gap(12.0)
                .run_gap(12.0)
                .child(round_swatch(
                    "colour wheel",
                    SweepGradient::new(vec![
                        Color::hex("#EF4444"),
                        Color::hex("#EAB308"),
                        Color::hex("#22C55E"),
                        Color::hex("#06B6D4"),
                        Color::hex("#6366F1"),
                        Color::hex("#EC4899"),
                        Color::hex("#EF4444"),
                    ]),
                ))
                .child(round_swatch(
                    "a quarter",
                    SweepGradient {
                        end_angle: std::f32::consts::FRAC_PI_2,
                        ..SweepGradient::new(vec![Color::hex("#C7D2FE"), Color::hex("#4338CA")])
                    },
                )),
        )),
        // `Container::gradient` is the shortcut for a two-colour linear one: from the
        // container's colour to `end`, along a direction.
        Box::new(section(
            "Container shortcut",
            Container::new()
                .width(240.0)
                .height(56.0)
                .radius(28.0)
                .color(Color::hex("#06B6D4"))
                .gradient(Color::hex("#3B82F6"), [1.0, 0.0]),
        )),
    ])
}

fn swatch(label: &str, gradient: impl Into<Gradient>) -> Column {
    labelled(
        label,
        BoxDecoration::default().radius(8.0).gradient(gradient),
    )
}

fn round_swatch(label: &str, gradient: impl Into<Gradient>) -> Column {
    labelled(
        label,
        BoxDecoration::default()
            .shape(BoxShape::Circle)
            .gradient(gradient),
    )
}

fn labelled(label: &str, decoration: BoxDecoration) -> Column {
    Column::new()
        .spacing(4.0)
        .child(
            Container::new()
                .width(120.0)
                .height(80.0)
                .decoration(decoration),
        )
        .child(Text::new(label).size(12.0))
}

//! Elevation — the shadows a surface casts at a given height above the page, from the
//! standard table: `BoxShadow::for_elevation(height, colour)`.
//!
//! Cards, menus, dialogs and buttons use these heights. Use the same function for your
//! own surfaces so they sit in the same light as the built-in ones.

use frus::{
    component, Align, Alignment, BlurStyle, BoxShadow, Color, Column, Container, Padding, Slider,
    Text, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // Three shadows per height — a sharp one close under the surface, a softer one
        // further down, a wide faint one all round — in the colour given at full strength.
        Box::new(section(
            "Standard heights",
            // The gaps leave room for the shadows, which paint outside each surface.
            Wrap::new()
                .gap(24.0)
                .run_gap(24.0)
                .child(surface(0.0))
                .child(surface(1.0))
                .child(surface(3.0))
                .child(surface(6.0))
                .child(surface(12.0))
                .child(surface(24.0)),
        )),
        // Heights between the table's rows are interpolated, so an elevation can animate
        // or follow a value smoothly.
        Box::new(section("Any height", live())),
        // A shadow's blur style: `Normal` blurs both ways; `Outer` keeps only what lies
        // outside the shape; `Inner` only what lies inside it; `Solid` keeps the shape
        // solid and blurs outwards.
        Box::new(section(
            "Blur styles",
            Wrap::new()
                .gap(24.0)
                .run_gap(24.0)
                .child(styled("Normal", BlurStyle::Normal))
                .child(styled("Outer", BlurStyle::Outer))
                .child(styled("Inner", BlurStyle::Inner))
                .child(styled("Solid", BlurStyle::Solid)),
        )),
    ])
}

fn live() -> impl Widget {
    component(|cx| {
        let height = cx.use_state(|| 4.0_f32);
        let value = height.get();
        Box::new(
            Column::new()
                .spacing(16.0)
                .cross_axis_alignment(Align::Start)
                .child(Padding::new(12.0, surface(value)))
                .child(
                    Slider::new(value)
                        .range(0.0, 24.0)
                        .width(240.0)
                        .on_change(move |v| height.set(v)),
                ),
        )
    })
}

fn surface(elevation: f32) -> Container {
    Container::new()
        .width(96.0)
        .height(64.0)
        .radius(12.0)
        .color(Color::hex("#FFFFFF"))
        .shadows(BoxShadow::for_elevation(elevation, Color::hex("#000000")))
        .alignment(Alignment::CENTER)
        .child(Text::new(format!("{elevation:.0} dp")).color(Color::hex("#0F172A")))
}

fn styled(label: &str, style: BlurStyle) -> Container {
    Container::new()
        .width(96.0)
        .height(64.0)
        .radius(12.0)
        .color(Color::hex("#E0E7FF").fade(0.6))
        .shadows([BoxShadow::new(0.0, 0.0, 12.0, Color::hex("#4F46E5")).blur_style(style)])
        .alignment(Alignment::CENTER)
        .child(Text::new(label).color(Color::hex("#312E81")))
}

//! `ClipRect`, `ClipRRect`, `ClipOval` and `ClipPath` — cut a child's painting to a
//! shape: rounded corners on a picture, a round avatar, a star.
//!
//! A clip changes what is painted, never the layout: the box keeps its size, only the
//! pixels outside the shape are dropped.

use frus::{
    Alignment, BorderRadius, BoxDecoration, ClipOval, ClipPath, ClipRRect, ClipRect, Color, Column,
    Container, LinearGradient, Padding, Path, Point, Text, Transform, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        Box::new(section(
            "Shapes",
            Wrap::new()
                .gap(16.0)
                .run_gap(16.0)
                // Rounded corners — the same radius everywhere, or per corner.
                .child(labelled("ClipRRect", ClipRRect::new(16.0).child(picture())))
                .child(labelled(
                    "ClipRRect, top only",
                    ClipRRect::rounded(BorderRadius::top(32.0)).child(picture()),
                ))
                // The ellipse inscribed in the box: a circle when the box is square.
                .child(labelled("ClipOval", ClipOval::new().child(picture())))
                // Any path, in the box's own coordinates (origin at its top-left).
                .child(labelled(
                    "ClipPath",
                    ClipPath::new(star(100.0, 100.0)).child(picture()),
                )),
        )),
        // `ClipRect` cuts at the box's edges. A child that paints past them — here one
        // scaled up 1.3× by a transform — stays inside instead of covering its
        // neighbours.
        Box::new(section(
            "ClipRect",
            Padding::new(
                16.0,
                Wrap::new()
                    .gap(48.0)
                    .run_gap(16.0)
                    .child(labelled(
                        "unclipped",
                        Transform::scale(1.3).child(picture()),
                    ))
                    .child(labelled(
                        "clipped",
                        ClipRect::new().child(Transform::scale(1.3).child(picture())),
                    )),
            ),
        )),
    ])
}

/// A 100 × 100 stand-in for a photo: a gradient with a caption.
fn picture() -> Container {
    Container::new()
        .width(100.0)
        .height(100.0)
        .decoration(
            BoxDecoration::default().gradient(
                LinearGradient::new(vec![Color::hex("#22D3EE"), Color::hex("#6366F1")])
                    .between(Alignment::TOP_LEFT, Alignment::BOTTOM_RIGHT),
            ),
        )
        .alignment(Alignment::CENTER)
        .child(Text::new("photo").color(Color::hex("#FFFFFF")))
}

/// A five-pointed star filling a `width` × `height` box.
fn star(width: f32, height: f32) -> Path {
    let (cx, cy) = (width / 2.0, height / 2.0);
    let outer = width.min(height) / 2.0;
    let inner = outer * 0.45;
    (0..10)
        .fold(Path::new(), |path, i| {
            let radius = if i % 2 == 0 { outer } else { inner };
            // Start at the top and go round clockwise, a tenth of a turn per point.
            let angle = -std::f32::consts::FRAC_PI_2 + i as f32 * std::f32::consts::PI / 5.0;
            let point = Point::new(cx + radius * angle.cos(), cy + radius * angle.sin());
            if i == 0 {
                path.move_to(point)
            } else {
                path.line_to(point)
            }
        })
        .close()
}

fn labelled(label: &str, child: impl Widget + 'static) -> Column {
    Column::new()
        .spacing(6.0)
        .child(child)
        .child(Text::new(label).size(12.0))
}

//! `Transform` and `FractionalTranslation` — move, scale or rotate a child's painting
//! without changing the layout around it.
//!
//! The neighbours still see the untransformed box; use `RotatedBox` when the layout
//! should turn too. Taps follow the transformed child.

use frus::{
    component, Alignment, Clip, Color, Column, Container, Curve, FractionalTranslation, Slider,
    Stack, StackFit, Text, Transform, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        Box::new(section(
            "Translate, scale, rotate",
            Wrap::new()
                .gap(40.0)
                .run_gap(24.0)
                .child(slot(Transform::translate(16.0, 8.0).child(card("moved"))))
                .child(slot(Transform::scale(0.7).child(card("scaled"))))
                .child(slot(Transform::rotate(0.3).child(card("rotated"))))
                // Combined, and turned about a corner instead of the centre.
                .child(slot(
                    Transform::rotate_from(-0.25, Alignment::BOTTOM_LEFT)
                        .and_scale(0.9)
                        .child(card("both")),
                )),
        )),
        // Live: the slider sets the angle; `animated` eases to each new value — the way a
        // pressed button shrinks a little, or a chevron turns when a panel opens.
        Box::new(section("Driven by state, animated", spinner())),
        // `FractionalTranslation` moves by a fraction of the child's own size: (0.5, 0)
        // shifts it right by half its width, whatever that width is.
        Box::new(section(
            "FractionalTranslation",
            Container::new()
                .padding_each(8.0, 120.0, 8.0, 8.0)
                .color(Color::hex("#EEF2FF"))
                .child(FractionalTranslation::new(0.5, 0.0).child(card("half my width →"))),
        )),
    ])
}

fn spinner() -> impl Widget {
    component(|cx| {
        let degrees = cx.use_state(|| 0.0_f32);
        let angle = degrees.get();
        Box::new(
            Column::new()
                .spacing(16.0)
                .child(slot(
                    Transform::rotate(angle.to_radians())
                        .animated(0.2, Curve::ease_out())
                        .child(card(&format!("{angle:.0}°"))),
                ))
                .child(
                    Slider::new(angle)
                        .range(0.0, 360.0)
                        .width(260.0)
                        .on_change(move |value| degrees.set(value)),
                ),
        )
    })
}

/// A fixed slot with a faint outline: the box the layout sees. The outline is a layer of
/// its own, under the child, so its border does not take room from the card; and the
/// stack does not clip, so the transformed card can paint past the slot.
fn slot(child: impl Widget + 'static) -> Stack {
    Stack::new()
        .width(100.0)
        .height(64.0)
        .fit(StackFit::Expand)
        .clip_behavior(Clip::None)
        .layer(Container::new().border(1.0, Color::hex("#CBD5E1")))
        .layer(child)
}

fn card(label: &str) -> Container {
    Container::new()
        .width(100.0)
        .height(64.0)
        .radius(8.0)
        .color(Color::hex("#6366F1").fade(0.85))
        .alignment(Alignment::CENTER)
        .child(Text::new(label).color(Color::hex("#FFFFFF")))
}

//! `Opacity` — paints a child partly transparent, the whole subtree as one layer.
//!
//! To fade something in or out over time, use `AnimatedOpacity` (Animation category);
//! `Opacity` is for a fixed or state-driven amount.

use frus::{
    component, Alignment, Color, Column, Container, Opacity, Positioned, Slider, Stack, Text,
    Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // The usual fixed levels: a disabled-looking 38 %, a secondary 60 %, full.
        Box::new(section(
            "Fixed levels",
            Wrap::new()
                .gap(12.0)
                .run_gap(12.0)
                .child(Opacity::new(0.38, tile("38 %")))
                .child(Opacity::new(0.6, tile("60 %")))
                .child(Opacity::new(1.0, tile("100 %"))),
        )),
        // Live: the slider's value is the opacity. The overlapping squares fade as one
        // picture — you never see the lower one through the upper.
        Box::new(section("Driven by state", live())),
    ])
}

fn live() -> impl Widget {
    component(|cx| {
        let opacity = cx.use_state(|| 0.5_f32);
        let value = opacity.get();
        Box::new(
            Column::new()
                .spacing(12.0)
                .child(Opacity::new(
                    value,
                    Stack::new()
                        .width(140.0)
                        .height(100.0)
                        .layer(
                            Container::new()
                                .width(90.0)
                                .height(90.0)
                                .color(Color::hex("#EF4444")),
                        )
                        .layer(
                            Positioned::new(
                                Container::new()
                                    .width(90.0)
                                    .height(90.0)
                                    .color(Color::hex("#3B82F6")),
                            )
                            .left(40.0)
                            .top(10.0),
                        ),
                ))
                .child(Text::new(format!("opacity {value:.2}")))
                .child(
                    Slider::new(value)
                        .width(260.0)
                        .on_change(move |v| opacity.set(v)),
                ),
        )
    })
}

fn tile(label: &str) -> Container {
    Container::new()
        .width(90.0)
        .height(64.0)
        .radius(8.0)
        .color(Color::hex("#6366F1"))
        .alignment(Alignment::CENTER)
        .child(Text::new(label).color(Color::hex("#FFFFFF")))
}

//! `CustomPaint` — a fixed-size canvas you draw yourself: charts, gauges, signatures,
//! anything no widget draws for you.
//!
//! The closure gets the `Scene` to draw into, its box on screen (`Rect`, in window
//! coordinates — offset everything by `bounds.x` / `bounds.y`) and the theme, so the
//! drawing follows light and dark mode like every widget does.

use frus::{
    component, Color, Column, CustomPaint, Path, Point, Rect, Slider, Stroke, StrokeCap, Widget,
    Wrap,
};

use crate::common::shared::{section, sections};

const SALES: [f32; 7] = [0.35, 0.6, 0.45, 0.8, 0.7, 0.95, 0.55];

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // Rectangles and a polyline: a small chart in the theme's colours.
        Box::new(section(
            "A bar chart with a trend line",
            CustomPaint::new(280.0, 140.0, |scene, bounds, theme| {
                // The axis along the bottom.
                scene.fill_rect(
                    Rect::new(bounds.x, bounds.y + bounds.height - 1.0, bounds.width, 1.0),
                    theme.border,
                );
                let slot = bounds.width / SALES.len() as f32;
                let mut trend = Path::new();
                for (i, value) in SALES.iter().enumerate() {
                    let height = (bounds.height - 12.0) * value;
                    let x = bounds.x + i as f32 * slot;
                    let top = bounds.y + bounds.height - 1.0 - height;
                    scene.fill_rect(
                        Rect::new(x + slot * 0.2, top, slot * 0.6, height),
                        theme.primary.fade(0.35),
                    );
                    let peak = Point::new(x + slot / 2.0, top);
                    trend = if i == 0 {
                        trend.move_to(peak)
                    } else {
                        trend.line_to(peak)
                    };
                }
                scene.paint_path(
                    &trend,
                    None,
                    Some(Stroke::new(theme.primary, 2.5).with_cap(StrokeCap::Round)),
                );
            }),
        )),
        Box::new(section(
            "Shapes: circles, arcs and curves",
            Wrap::new()
                .gap(16.0)
                .run_gap(16.0)
                .child(smiley())
                .child(CustomPaint::new(140.0, 100.0, |scene, b, theme| {
                    // A wave: one cubic Bézier curve.
                    let wave = Path::new()
                        .move_to(Point::new(b.x, b.y + b.height / 2.0))
                        .cubic_to(
                            Point::new(b.x + b.width * 0.35, b.y - 20.0),
                            Point::new(b.x + b.width * 0.65, b.y + b.height + 20.0),
                            Point::new(b.x + b.width, b.y + b.height / 2.0),
                        );
                    scene.stroke_path(&wave, theme.primary, 3.0);
                })),
        )),
        // A gauge redrawn from state: the canvas is rebuilt with the new value every time
        // the slider moves.
        Box::new(section("A gauge driven by state", gauge())),
    ])
}

fn smiley() -> CustomPaint {
    CustomPaint::new(100.0, 100.0, |scene, b, _theme| {
        let center = Point::new(b.x + b.width / 2.0, b.y + b.height / 2.0);
        scene.fill_path(&Path::circle(center, 46.0), Color::hex("#FACC15"));
        scene.fill_path(
            &Path::circle(Point::new(center.x - 16.0, center.y - 12.0), 6.0),
            Color::hex("#422006"),
        );
        scene.fill_path(
            &Path::circle(Point::new(center.x + 16.0, center.y - 12.0), 6.0),
            Color::hex("#422006"),
        );
        // An arc from 20° to 160°, below the centre (y grows downwards).
        let (start, end) = (20_f32.to_radians(), 160_f32.to_radians());
        let mouth = Path::new()
            .move_to(Point::new(
                center.x + 26.0 * start.cos(),
                center.y + 26.0 * start.sin(),
            ))
            .arc_to(center, 26.0, start, end);
        scene.paint_path(
            &mouth,
            None,
            Some(Stroke::new(Color::hex("#422006"), 4.0).with_cap(StrokeCap::Round)),
        );
    })
}

fn gauge() -> impl Widget {
    component(|cx| {
        let level = cx.use_state(|| 0.65_f32);
        let value = level.get();
        let canvas = CustomPaint::new(160.0, 100.0, move |scene, b, theme| {
            let center = Point::new(b.x + b.width / 2.0, b.y + b.height - 10.0);
            let radius = 64.0;
            let start = std::f32::consts::PI;
            let arc = |to: f32| {
                Path::new()
                    .move_to(Point::new(center.x - radius, center.y))
                    .arc_to(center, radius, start, start + std::f32::consts::PI * to)
            };
            let track = Stroke::new(theme.border, 12.0).with_cap(StrokeCap::Round);
            let fill = Stroke::new(theme.primary, 12.0).with_cap(StrokeCap::Round);
            scene.paint_path(&arc(1.0), None, Some(track));
            if value > 0.0 {
                scene.paint_path(&arc(value), None, Some(fill));
            }
        });
        Box::new(
            Column::new().spacing(8.0).child(canvas).child(
                Slider::new(value)
                    .width(220.0)
                    .on_change(move |v| level.set(v)),
            ),
        )
    })
}

//! `ShaderMask` — lays a gradient over a child's own pixels: a headline painted in a
//! gradient, a list that fades out at its edge, a spotlight.
//!
//! By default the mask's alpha multiplies the child (a fade). With `BlendMode::SrcIn`
//! the mask's colours replace the child's wherever the child is drawn — a gradient
//! fill for text or icons.

use frus::{Align, Alignment, BlendMode, Color, Column, Container, ShaderMask, Text, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // `linear(from, to, from_colour, to_colour)`, points as fractions of the box.
        Box::new(section(
            "Gradient text",
            ShaderMask::linear(
                (0.0, 0.0),
                (1.0, 0.0),
                Color::hex("#F59E0B"),
                Color::hex("#DB2777"),
            )
            .blend(BlendMode::SrcIn)
            .child(Text::new("Gradient headline").size(36.0)),
        )),
        // The default blend multiplies alpha in: opaque at the top, gone at the bottom —
        // the edge of a list that continues past view.
        Box::new(section(
            "Fade out at the bottom",
            ShaderMask::fade_out_bottom().child(
                (1..=6).fold(
                    Column::new()
                        .spacing(4.0)
                        .cross_axis_alignment(Align::Start),
                    |column, i| {
                        column.child(
                            Container::new()
                                .width(240.0)
                                .padding(8.0)
                                .color(Color::hex("#E0E7FF"))
                                .child(Text::new(format!("Row {i}")).color(Color::hex("#312E81"))),
                        )
                    },
                ),
            ),
        )),
        // A radial mask: visible in the middle, fading towards the edges — a spotlight
        // or a vignette. The default blend multiplies colour as well as alpha, so a pure
        // fade is drawn in white, from opaque to transparent.
        Box::new(section(
            "Radial spotlight",
            ShaderMask::radial(
                (0.5, 0.5),
                0.6,
                Color::rgba(1.0, 1.0, 1.0, 1.0),
                Color::rgba(1.0, 1.0, 1.0, 0.0),
            )
            .child(
                Container::new()
                    .width(240.0)
                    .height(120.0)
                    .color(Color::hex("#0EA5E9"))
                    .alignment(Alignment::CENTER)
                    .child(Text::new("In the spotlight").color(Color::hex("#FFFFFF"))),
            ),
        )),
    ])
}

//! `ColorFiltered` — changes the colours of everything a child paints: greyscale,
//! sepia, inverted, tinted.
//!
//! A filter is a `ColorFilter` value: a 5 × 4 colour matrix, with ready-made ones for
//! the usual effects, or a colour blended in with a `BlendMode`.

use frus::{
    component, Align, Alignment, BlendMode, BoxDecoration, Color, ColorFilter, ColorFiltered,
    Column, Container, LinearGradient, Switch, Text, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        Box::new(section(
            "Matrices",
            Wrap::new()
                .gap(12.0)
                .run_gap(12.0)
                .child(labelled("original", picture()))
                .child(labelled(
                    "grayscale",
                    ColorFiltered::grayscale().child(picture()),
                ))
                .child(labelled(
                    "sepia",
                    ColorFiltered::new(ColorFilter::sepia()).child(picture()),
                ))
                .child(labelled(
                    "invert",
                    ColorFiltered::new(ColorFilter::invert()).child(picture()),
                ))
                .child(labelled(
                    "saturate 2×",
                    ColorFiltered::new(ColorFilter::saturate(2.0)).child(picture()),
                ))
                .child(labelled(
                    "brightness",
                    ColorFiltered::new(ColorFilter::brightness(0.25)).child(picture()),
                )),
        )),
        // `mode(colour, blend)` blends a colour into every pixel: a multiply tint here.
        Box::new(section(
            "Blend a colour in",
            Wrap::new()
                .gap(12.0)
                .run_gap(12.0)
                .child(labelled(
                    "multiply teal",
                    ColorFiltered::mode(Color::hex("#14B8A6"), BlendMode::Multiply)
                        .child(picture()),
                ))
                .child(labelled(
                    "screen amber",
                    ColorFiltered::mode(Color::hex("#F59E0B"), BlendMode::Screen).child(picture()),
                )),
        )),
        // `enabled(false)` removes the filter entirely (no layer at all) — the way to
        // switch an effect off, here a "greyed out" state.
        Box::new(section("Switched by state", toggled())),
    ])
}

fn toggled() -> impl Widget {
    component(|cx| {
        let grey = cx.use_state(|| true);
        let on = grey.get();
        Box::new(
            Column::new()
                .spacing(8.0)
                .cross_axis_alignment(Align::Start)
                .child(ColorFiltered::grayscale().enabled(on).child(picture()))
                .child(Switch::new(on).on_toggle(move |value| grey.set(value))),
        )
    })
}

/// A colourful 100 × 70 stand-in for a photo.
fn picture() -> Container {
    Container::new()
        .width(100.0)
        .height(70.0)
        .decoration(
            BoxDecoration::default().radius(8.0).gradient(
                LinearGradient::new(vec![
                    Color::hex("#EF4444"),
                    Color::hex("#EAB308"),
                    Color::hex("#22C55E"),
                    Color::hex("#3B82F6"),
                ])
                .between(Alignment::TOP_LEFT, Alignment::BOTTOM_RIGHT),
            ),
        )
        .alignment(Alignment::CENTER)
        .child(Text::new("photo").color(Color::hex("#FFFFFF")))
}

fn labelled(label: &str, child: impl Widget + 'static) -> Column {
    Column::new()
        .spacing(4.0)
        .child(child)
        .child(Text::new(label).size(12.0))
}

//! `ImageFiltered` — treats a child as an image and filters it: a blur, or shapes
//! grown (dilate) or shrunk (erode).
//!
//! It filters the widget itself; to blur what lies *behind* a widget, use
//! `BackdropFilter`.

use frus::{
    component, Align, Alignment, Color, Column, Container, ImageFilter, ImageFiltered, Slider,
    Text, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // Live: the slider sets the blur's sigma, in logical pixels. At zero the filter is
        // switched off with `enabled(false)` — a zero blur would still cost a layer.
        Box::new(section("Blur, driven by state", live_blur())),
        // Separate sigmas per axis make a directional smear; dilate and erode grow or
        // shrink the light shapes — the bases of a glow or a thinner outline.
        Box::new(section(
            "Other filters",
            Wrap::new()
                .gap(16.0)
                .run_gap(16.0)
                .child(labelled(
                    "motion blur",
                    ImageFiltered::new(ImageFilter::Blur {
                        sigma_x: 6.0,
                        sigma_y: 0.0,
                    })
                    .child(badge()),
                ))
                .child(labelled(
                    "dilate",
                    ImageFiltered::new(ImageFilter::Dilate {
                        radius_x: 3.0,
                        radius_y: 3.0,
                    })
                    .child(outlined()),
                ))
                .child(labelled("original", outlined()))
                .child(labelled(
                    "erode",
                    ImageFiltered::new(ImageFilter::Erode {
                        radius_x: 1.0,
                        radius_y: 1.0,
                    })
                    .child(outlined()),
                )),
        )),
    ])
}

fn live_blur() -> impl Widget {
    component(|cx| {
        let sigma = cx.use_state(|| 4.0_f32);
        let value = sigma.get();
        Box::new(
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    ImageFiltered::blur(value)
                        .enabled(value > 0.0)
                        .child(badge()),
                )
                .child(Text::new(format!("sigma {value:.1} px")))
                .child(
                    Slider::new(value)
                        .range(0.0, 12.0)
                        .width(240.0)
                        .on_change(move |v| sigma.set(v)),
                ),
        )
    })
}

fn badge() -> Container {
    Container::new()
        .width(160.0)
        .height(64.0)
        .radius(12.0)
        .color(Color::hex("#6366F1"))
        .alignment(Alignment::CENTER)
        .child(Text::new("frus").size(28.0).color(Color::hex("#FFFFFF")))
}

/// Light text on a dark box: dilate fattens the letters, erode thins them.
fn outlined() -> Container {
    Container::new()
        .width(100.0)
        .height(64.0)
        .color(Color::hex("#0F172A"))
        .alignment(Alignment::CENTER)
        .child(Text::new("Glow").size(24.0).color(Color::hex("#FDE68A")))
}

fn labelled(label: &str, child: impl Widget + 'static) -> Column {
    Column::new()
        .spacing(4.0)
        .child(child)
        .child(Text::new(label).size(12.0))
}

//! `BackdropFilter` and `BackdropGroup` — blur what is already painted *underneath* a
//! widget: the frosted glass a bar, a sheet or a dialog sits on.
//!
//! The blurred region is whatever clips the filter, not its own box — unclipped, the
//! whole window would blur. So a backdrop almost always sits inside a `ClipRRect` or a
//! `ClipRect`. It is the most expensive filter: when you mean "blur this widget", use
//! `ImageFiltered` instead.

use frus::{
    Alignment, BackdropFilter, BackdropGroup, ClipRRect, Color, Column, Container, Positioned,
    Stack, Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // A translucent card over a busy background: the blur makes its text readable.
        Box::new(section(
            "Frosted glass",
            Stack::new()
                .width(300.0)
                .height(180.0)
                .layer(background())
                .layer(
                    Positioned::new(
                        ClipRRect::new(16.0).child(
                            BackdropFilter::blur(10.0).child(
                                Container::new()
                                    .padding(16.0)
                                    .color(Color::rgba(1.0, 1.0, 1.0, 0.35))
                                    .alignment(Alignment::CENTER)
                                    .child(
                                        Text::new("Frosted")
                                            .size(22.0)
                                            .color(Color::hex("#0F172A")),
                                    ),
                            ),
                        ),
                    )
                    .left(40.0)
                    .right(40.0)
                    .top(40.0)
                    .bottom(40.0),
                ),
        )),
        // Many backdrops in a list would each copy and blur the frame. Inside a
        // `BackdropGroup`, `grouped()` filters share one blur of what lies behind them.
        Box::new(section(
            "Grouped backdrops",
            Stack::new()
                .width(300.0)
                .height(180.0)
                .layer(background())
                .layer(Positioned::fill(BackdropGroup::new().child((1..=3).fold(
                    Column::new().spacing(8.0),
                    |column, i| {
                        column.child(
                            ClipRRect::new(8.0).child(
                                BackdropFilter::blur(8.0).grouped().child(
                                    Container::new()
                                        .width(220.0)
                                        .padding(10.0)
                                        .color(Color::rgba(1.0, 1.0, 1.0, 0.3))
                                        .child(
                                            Text::new(format!("Row {i}"))
                                                .color(Color::hex("#0F172A")),
                                        ),
                                ),
                            ),
                        )
                    },
                )))),
        )),
    ])
}

/// Something busy to blur: coloured circles and stripes.
fn background() -> Stack {
    Stack::new()
        .width(300.0)
        .height(180.0)
        .layer(
            Container::new()
                .width(300.0)
                .height(180.0)
                .color(Color::hex("#F8FAFC")),
        )
        .layer(
            Positioned::new(circle(110.0, "#F43F5E"))
                .left(10.0)
                .top(10.0),
        )
        .layer(
            Positioned::new(circle(90.0, "#22C55E"))
                .left(150.0)
                .top(70.0),
        )
        .layer(
            Positioned::new(circle(70.0, "#3B82F6"))
                .left(220.0)
                .top(5.0),
        )
        .layer(
            Positioned::new(
                Container::new()
                    .width(300.0)
                    .height(14.0)
                    .color(Color::hex("#EAB308")),
            )
            .left(0.0)
            .top(120.0),
        )
}

fn circle(size: f32, color: &str) -> Container {
    Container::new()
        .width(size)
        .height(size)
        .radius(size / 2.0)
        .color(Color::hex(color))
}

//! `GestureDetector` — taps, double taps, long presses, secondary clicks and drags on any
//! widget, answered with your own handlers.
//!
//! It adds no look of its own (no ink, no hover): it is the widget it wraps. For a
//! pressable surface with feedback, use `InkWell` or a button.

use frus::{
    Align, Alignment, Column, Container, GestureDetector, PanAxis, Point, Positioned, Stack,
    StackFit, State, StateContext, StatefulWidget, Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(GestureDemo.into_widget())
}

/// The demo is a small `StatefulWidget`: the state remembers the last gesture and where
/// the dragged chip is, and `cx.handler` turns a reported value into a state change.
struct GestureDemo;

struct GestureDemoState {
    last: String,
    taps: u32,
    /// Where the free chip sits in its box.
    chip: Point,
    /// Where the horizontal-only handle sits along its track.
    handle: f32,
}

impl StatefulWidget for GestureDemo {
    type State = GestureDemoState;

    fn create_state(&self) -> GestureDemoState {
        GestureDemoState {
            last: "Nothing yet".to_string(),
            taps: 0,
            chip: Point::new(16.0, 16.0),
            handle: 0.0,
        }
    }
}

/// The free chip's box and the chip itself, in logical pixels.
const AREA: (f32, f32) = (300.0, 160.0);
const CHIP: (f32, f32) = (72.0, 36.0);
const TRACK: f32 = 260.0;
const HANDLE: f32 = 32.0;

impl State for GestureDemoState {
    type Widget = GestureDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let scheme = &cx.theme().scheme;

        // Four discrete gestures on one pad. With a double tap set, a single tap waits
        // 300 ms to be sure it is not the first half of one.
        let pad = GestureDetector::new(
            Container::new()
                .width(AREA.0)
                .height(110.0)
                .padding(16.0)
                .radius(12.0)
                .color(scheme.secondary_container)
                .alignment(Alignment::CENTER)
                .child(
                    Text::new("Tap, double-tap, long-press or right-click")
                        .color(scheme.on_secondary_container),
                ),
        )
        .on_tap(cx.callback(|s| {
            s.taps += 1;
            s.last = format!("Tap (#{})", s.taps);
        }))
        .on_double_tap(cx.callback(|s| s.last = "Double tap".to_string()))
        .on_long_press(cx.callback(|s| s.last = "Long press".to_string()))
        .on_secondary_tap(cx.callback(|s| s.last = "Secondary tap (right click)".to_string()));

        // A drag: `on_pan_update` reports where the pointer is and how far it moved.
        let moved = cx.handler(|s: &mut Self, delta: Point| {
            s.chip.x = (s.chip.x + delta.x).clamp(0.0, AREA.0 - CHIP.0);
            s.chip.y = (s.chip.y + delta.y).clamp(0.0, AREA.1 - CHIP.1);
            s.last = format!("Pan to ({:.0}, {:.0})", s.chip.x, s.chip.y);
        });
        let ended = cx.handler(|s: &mut Self, velocity: Point| {
            s.last = format!("Pan end, {:.0} px/s across", velocity.x);
        });
        let chip = GestureDetector::new(
            Container::new()
                .width(CHIP.0)
                .height(CHIP.1)
                .radius(18.0)
                .color(scheme.primary)
                .alignment(Alignment::CENTER)
                .child(Text::new("Drag").color(scheme.on_primary)),
        )
        .on_pan_update(move |_local, delta| moved(delta))
        .on_pan_end(ended);
        let free_area = Stack::new()
            .width(AREA.0)
            .height(AREA.1)
            .fit(StackFit::Expand)
            .layer(
                Container::new()
                    .radius(12.0)
                    .color(scheme.surface_container_high),
            )
            .layer(Positioned::new(chip).left(self.chip.x).top(self.chip.y));

        // `pan_axis` keeps only one direction — and inside a vertical scroll, leaves the
        // vertical drags to the scroll.
        let slide = cx.handler(|s: &mut Self, delta: Point| {
            s.handle = (s.handle + delta.x).clamp(0.0, TRACK - HANDLE);
        });
        let handle = GestureDetector::new(
            Container::new()
                .width(HANDLE)
                .height(HANDLE)
                .radius(HANDLE / 2.0)
                .color(scheme.tertiary),
        )
        .pan_axis(PanAxis::Horizontal)
        .on_pan_update(move |_local, delta| slide(delta));
        let track = Stack::new()
            .width(TRACK)
            .height(HANDLE)
            .fit(StackFit::Expand)
            .layer(
                Container::new()
                    .radius(HANDLE / 2.0)
                    .color(scheme.surface_container_highest),
            )
            .layer(Positioned::new(handle).left(self.handle).top(0.0));

        sections(vec![
            Box::new(section(
                "Last gesture",
                Text::new(self.last.clone()).color(scheme.primary),
            )),
            Box::new(section("Taps and presses", pad)),
            Box::new(section("Drag in any direction", free_area)),
            Box::new(section(
                "Drag along one axis",
                Column::new()
                    .spacing(6.0)
                    .cross_axis_alignment(Align::Start)
                    .child(track)
                    .child(Text::new(format!("{:.0} px", self.handle)).size(13.0)),
            )),
        ])
    }
}

//! `InkWell` — makes any content pressable, with the ink ripple that spreads from the
//! point of contact, a hover tint and a focus highlight.
//!
//! Use it for custom tiles and rows that should feel like buttons. It answers a click and
//! a long press; for more gestures, put a `GestureDetector` around it.

use frus::{
    component, Align, Color, Column, Container, Icon, Icons, InkWell, Row, Text, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let presses = cx.use_state(|| 0_u32);
        let holds = cx.use_state(|| 0_u32);
        let scheme = &cx.theme().scheme;

        // A tile: the ink is clipped to `radius`, which should match the content's corners.
        let (press, hold) = (presses.clone(), holds.clone());
        let tile = InkWell::new()
            .radius(16.0)
            .on_click(move || press.update(|n| *n += 1))
            .on_long_press(move || hold.update(|n| *n += 1))
            .child(
                Container::new()
                    .width(160.0)
                    .padding(16.0)
                    .radius(16.0)
                    .border(1.0, scheme.outline_variant)
                    .child(
                        Column::new()
                            .spacing(8.0)
                            .cross_axis_alignment(Align::Start)
                            .child(Icon::new(Icons::TOUCH_APP).color(scheme.primary))
                            .child(Text::new("Press or hold me")),
                    ),
            );

        // The splash colour is yours to choose; the theme's is used otherwise.
        let press_row = presses.clone();
        let row = InkWell::new()
            .radius(8.0)
            .color(Color::rgba(0.9, 0.2, 0.4, 0.25))
            .on_click(move || press_row.update(|n| *n += 1))
            .child(
                Container::new().padding(12.0).child(
                    Row::new()
                        .spacing(12.0)
                        .cross_axis_alignment(Align::Center)
                        .child(Icon::new(Icons::FAVORITE).color(Color::hex("#E11D48")))
                        .child(Text::new("A row with a custom splash")),
                ),
            );

        sections(vec![
            Box::new(section(
                "Counts",
                Text::new(format!(
                    "{} presses, {} long presses",
                    presses.get(),
                    holds.get()
                ))
                .color(scheme.primary),
            )),
            Box::new(section(
                "Tiles and rows",
                Wrap::new().gap(16.0).run_gap(16.0).child(tile).child(row),
            )),
        ])
    }))
}

//! `MouseRegion` — hears the mouse entering, moving over and leaving a widget, and sets
//! the cursor shown there.
//!
//! On a touch screen a finger is "over" a region only while it touches: an enter when it
//! goes down, an exit when it lifts, and no moves.

use frus::{
    Alignment, Container, Cursor, MouseRegion, Point, State, StateContext, StatefulWidget, Text,
    Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(HoverDemo.into_widget())
}

struct HoverDemo;

struct HoverDemoState {
    inside: bool,
    position: Option<Point>,
}

impl StatefulWidget for HoverDemo {
    type State = HoverDemoState;

    fn create_state(&self) -> HoverDemoState {
        HoverDemoState {
            inside: false,
            position: None,
        }
    }
}

/// The cursors worth knowing, with the place each belongs.
const CURSORS: [(Cursor, &str); 8] = [
    (Cursor::Pointer, "Pointer: a link"),
    (Cursor::Text, "Text: an editable line"),
    (Cursor::Move, "Move"),
    (Cursor::Grab, "Grab: a handle"),
    (Cursor::Forbidden, "Forbidden"),
    (Cursor::Wait, "Wait"),
    (Cursor::Help, "Help"),
    (Cursor::ZoomIn, "Zoom in"),
];

impl State for HoverDemoState {
    type Widget = HoverDemo;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let scheme = &cx.theme().scheme;

        // Each callback receives the pointer's position in the region's own coordinates.
        let card = MouseRegion::new(
            Container::new()
                .width(280.0)
                .height(120.0)
                .radius(12.0)
                .color(if self.inside {
                    scheme.primary_container
                } else {
                    scheme.surface_container_high
                })
                .alignment(Alignment::CENTER)
                .child(Text::new(match self.position {
                    Some(p) if self.inside => format!("Pointer at ({:.0}, {:.0})", p.x, p.y),
                    _ => "Move the mouse over me".to_string(),
                })),
        )
        .on_enter(cx.handler(|s: &mut Self, at: Point| {
            s.inside = true;
            s.position = Some(at);
        }))
        .on_hover(cx.handler(|s: &mut Self, at: Point| s.position = Some(at)))
        .on_exit(cx.handler(|s: &mut Self, _at: Point| s.inside = false))
        .cursor(Cursor::Precise);

        let cursors =
            CURSORS
                .iter()
                .fold(Wrap::new().gap(8.0).run_gap(8.0), |row, (cursor, name)| {
                    row.child(
                        MouseRegion::new(
                            Container::new()
                                .padding(10.0)
                                .radius(8.0)
                                .border(1.0, scheme.outline_variant)
                                .child(Text::new(*name).size(13.0)),
                        )
                        .cursor(*cursor),
                    )
                });

        sections(vec![
            Box::new(section("Enter, hover and exit", card)),
            Box::new(section("Cursors (hover each)", cursors)),
        ])
    }
}

//! `Listener` — the pointer's raw events on a widget: down, move, up, cancel, and a mouse's
//! hover, with positions in the widget's own coordinates.
//!
//! Unlike `GestureDetector` it recognises nothing and competes with nothing: a button
//! inside still takes its tap, a scroll still scrolls, and the listener hears every event
//! anyway. A pointer that went down inside is followed wherever it goes until it lifts —
//! what a drawing surface or a custom control is built on.

use std::collections::VecDeque;

use frus::{
    Align, Column, Container, Listener, ListenerEvent, ListenerEventKind, Point, Positioned, Stack,
    StackFit, State, StateContext, StatefulWidget, Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(RawPointer.into_widget())
}

struct RawPointer;

struct RawPointerState {
    /// The latest events, newest first.
    log: VecDeque<String>,
    /// Where the pointer is, while it is over the pad or pressed.
    dot: Option<Point>,
    pressed: bool,
}

/// How many events the log keeps.
const LOG: usize = 6;
const PAD: (f32, f32) = (300.0, 180.0);
const DOT: f32 = 20.0;

impl StatefulWidget for RawPointer {
    type State = RawPointerState;

    fn create_state(&self) -> RawPointerState {
        RawPointerState {
            log: VecDeque::new(),
            dot: None,
            pressed: false,
        }
    }
}

impl RawPointerState {
    fn record(&mut self, event: ListenerEvent) {
        match event.kind {
            ListenerEventKind::Down => self.pressed = true,
            ListenerEventKind::Up | ListenerEventKind::Cancel => self.pressed = false,
            ListenerEventKind::Move | ListenerEventKind::Hover => {}
        }
        self.dot = Some(event.local);
        // Hover moves come many per second: log only the events that change something.
        if event.kind != ListenerEventKind::Hover && event.kind != ListenerEventKind::Move {
            let device = if event.touch { "finger" } else { "mouse" };
            self.log.push_front(format!(
                "{:?} at ({:.0}, {:.0}) — {device}",
                event.kind, event.local.x, event.local.y
            ));
            self.log.truncate(LOG);
        }
    }
}

impl State for RawPointerState {
    type Widget = RawPointer;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let scheme = &cx.theme().scheme;

        let mut pad = Stack::new()
            .width(PAD.0)
            .height(PAD.1)
            .fit(StackFit::Expand)
            .layer(
                Container::new()
                    .radius(12.0)
                    .color(scheme.surface_container_high)
                    .padding(12.0)
                    .child(Text::new("Press, drag and release here").size(13.0)),
            );
        if let Some(at) = self.dot {
            let size = if self.pressed { DOT * 1.6 } else { DOT };
            pad = pad.layer(
                Positioned::new(
                    Container::new()
                        .width(size)
                        .height(size)
                        .radius(size / 2.0)
                        .color(if self.pressed {
                            scheme.primary
                        } else {
                            scheme.outline
                        }),
                )
                .left(at.x - size / 2.0)
                .top(at.y - size / 2.0),
            );
        }

        // The closure answers every event with a message, or with `None` to ignore it.
        let record = cx.handler(|s: &mut Self, event: ListenerEvent| s.record(event));
        let listener = Listener::new(pad, move |event| Some(record(event)));

        let log = self.log.iter().fold(
            Column::new()
                .spacing(4.0)
                .cross_axis_alignment(Align::Start),
            |column, line| column.child(Text::new(line.clone()).size(13.0)),
        );

        sections(vec![
            Box::new(section("A pad that hears everything", listener)),
            Box::new(section("Down / up / cancel, newest first", log)),
        ])
    }
}

//! `Draggable` and `DragTarget` — pick a thing up and drop it somewhere else.
//!
//! What travels between the two is a **payload**: a `u64` you choose (an id, an index) and
//! get back in the target's `on_drop`. The two ends need not know of each other.
//! Inside a scrollable list, lift with `.long_press()` so the list can still scroll.

use frus::{
    Align, Button, Column, Container, DragTarget, Draggable, State, StateContext, StatefulWidget,
    Text, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(Sorting.into_widget())
}

const FRUITS: [&str; 5] = ["Apple", "Banana", "Cherry", "Grape", "Lemon"];

/// Where each fruit is: unsorted, or in one of the baskets.
#[derive(Clone, Copy, PartialEq)]
enum Place {
    Table,
    Basket(usize),
}

const BASKETS: [&str; 2] = ["Red", "Yellow"];

struct Sorting;

struct SortingState {
    places: [Place; FRUITS.len()],
    message: String,
}

impl StatefulWidget for Sorting {
    type State = SortingState;

    fn create_state(&self) -> SortingState {
        SortingState {
            places: [Place::Table; FRUITS.len()],
            message: "Drag a fruit into a basket".to_string(),
        }
    }
}

impl SortingState {
    fn drop_into(&mut self, fruit: u64, basket: usize) {
        if let Some(place) = self.places.get_mut(fruit as usize) {
            *place = Place::Basket(basket);
            self.message = format!("{} → {} basket", FRUITS[fruit as usize], BASKETS[basket]);
        }
    }
}

impl State for SortingState {
    type Widget = Sorting;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let scheme = &cx.theme().scheme;

        // A fruit chip, draggable, carrying its index as the payload.
        let chip = |index: usize| {
            Draggable::new(
                Container::new()
                    .padding(10.0)
                    .radius(18.0)
                    .color(scheme.secondary_container)
                    .child(Text::new(FRUITS[index]).color(scheme.on_secondary_container)),
            )
            .payload(index as u64)
            // Told whether a target took it: the moment to explain a refusal.
            .on_dropped(cx.handler(|s: &mut Self, accepted: bool| {
                if !accepted {
                    s.message = "Dropped outside a basket: nothing moved".to_string();
                }
            }))
        };
        let in_place = |place: Place| {
            (0..FRUITS.len())
                .filter(|&i| self.places[i] == place)
                .fold(Wrap::new().gap(8.0).run_gap(8.0), |row, i| {
                    row.child(chip(i))
                })
        };

        // A basket: a target that accepts some payloads and says what to do with them.
        let basket = |index: usize| {
            DragTarget::new(
                Container::new()
                    .width(140.0)
                    .height(140.0)
                    .padding(10.0)
                    .radius(12.0)
                    .border(2.0, scheme.outline_variant)
                    .child(
                        Column::new()
                            .spacing(8.0)
                            .cross_axis_alignment(Align::Start)
                            .child(Text::new(format!("{} basket", BASKETS[index])).size(13.0))
                            .child(in_place(Place::Basket(index))),
                    ),
            )
            // The yellow basket refuses cherries and grapes: the highlight only shows
            // over a target that would accept what is being dragged.
            .accepts(move |fruit| index == 0 || !matches!(fruit, 2 | 3))
            .on_drop(cx.handler(move |s: &mut Self, fruit: u64| s.drop_into(fruit, index)))
        };

        let reset = cx.callback(|s| {
            s.places = [Place::Table; FRUITS.len()];
            s.message = "Back on the table".to_string();
        });

        sections(vec![
            Box::new(section(
                "Status",
                Text::new(self.message.clone()).color(scheme.primary),
            )),
            Box::new(section("On the table", in_place(Place::Table))),
            Box::new(section(
                "Baskets",
                Wrap::new()
                    .gap(16.0)
                    .run_gap(16.0)
                    .child(basket(0))
                    .child(basket(1)),
            )),
            Box::new(section("Start again", Button::new("Reset").on_press(reset))),
        ])
    }
}

//! `InteractiveViewer` — a viewport whose content can be panned (drag) and zoomed (mouse
//! wheel, trackpad or pinch): a map, a diagram, a photo.
//!
//! The pan and the zoom are kept by the framework between frames; you only say how big
//! the viewport is and how far the zoom may go.

use frus::{
    component, Alignment, Column, Container, InteractiveViewer, LayoutBuilder, Row, Text, Widget,
};

use crate::common::shared::{section, sections};

/// The content is a 6 × 6 board of tiles.
const CELLS: usize = 6;
/// The viewport is square, as wide as the page allows up to this.
const MAX_SIDE: f32 = 360.0;

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let scheme = cx.theme().scheme;
        let muted = scheme.on_surface_variant;

        // At scale 1 the content **fills the viewport exactly**: the viewer lays its
        // child out at the viewport's size. So the board is sized from the room the
        // `LayoutBuilder` reports, and zooming in is what reveals detail and makes room
        // to pan.
        let viewer = LayoutBuilder::new(move |size| {
            // Less the 1 px border drawn round it on each side.
            let side = (size.width - 2.0).min(MAX_SIDE);
            let cell = side / CELLS as f32;
            let board = (0..CELLS).fold(Column::new(), |column, row| {
                column.child((0..CELLS).fold(Row::new(), |line, col| {
                    // A checkerboard of two tones, each tile named by its coordinates.
                    let dark = (row + col) % 2 == 0;
                    line.child(
                        Container::new()
                            .width(cell)
                            .height(cell)
                            .color(if dark {
                                scheme.primary_container
                            } else {
                                scheme.surface_container_highest
                            })
                            .alignment(Alignment::CENTER)
                            .child(
                                Text::new(format!("{}{}", (b'A' + row as u8) as char, col + 1))
                                    .size(13.0)
                                    .color(if dark {
                                        scheme.on_primary_container
                                    } else {
                                        scheme.on_surface
                                    }),
                            ),
                    )
                }))
            });

            // Sized, or the frame would stretch to the whole width the builder was given.
            Container::new()
                .width(side + 2.0)
                .height(side + 2.0)
                .radius(12.0)
                .clip()
                .border(1.0, scheme.outline_variant)
                .child(
                    InteractiveViewer::new()
                        .width(side)
                        .height(side)
                        // From half size to four times the natural size.
                        .min_scale(0.5)
                        .max_scale(4.0)
                        .child(board),
                )
        });

        sections(vec![
            Box::new(section("Wheel or pinch to zoom, then drag to pan", viewer)),
            Box::new(
                Text::new(
                    "At scale 1 the board fills the viewport and cannot move; zoomed in, \
                     it can be dragged until an edge meets the viewport's.",
                )
                .wrap()
                .size(13.0)
                .color(muted),
            ),
        ])
    }))
}

//! Focus — which widgets the keyboard can reach and in what order: `Focus`,
//! `FocusTraversalGroup`, `FocusTraversalOrder`, `ExcludeFocus`, `ExcludeFocusTraversal`,
//! and moving the focus from code with `host::focus`.
//!
//! Text fields and buttons are focus stops already; Tab walks them in tree order. These
//! wrappers change that from outside, without touching the widgets themselves.

use frus::{
    component, host, keyed, Align, Alignment, Button, Column, Container, ExcludeFocus,
    ExcludeFocusTraversal, Focus, FocusTraversalGroup, FocusTraversalOrder, Text, TextField,
    Variant, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let name = cx.use_state(String::new);
        let email = cx.use_state(String::new);
        let help = cx.use_state(|| false);
        let scheme = &cx.theme().scheme;

        let (set_name, set_email, toggle_help) = (name.clone(), email.clone(), help.clone());
        // A field wrapped in `keyed(key, ..)` can be focused from code with
        // `host::focus(key)` — after a validation error, or when a dialog opens.
        let name_field = keyed(
            "focus-demo-name",
            TextField::new(name.get())
                .label("Name (second)")
                .on_input(move |text| set_name.set(text)),
        );
        let email_field = keyed(
            "focus-demo-email",
            TextField::new(email.get())
                .label("Email (first)")
                .on_input(move |text| set_email.set(text)),
        );

        // Tab order by number, resolved inside the group only: the email field comes
        // first although it is built second. The help button is clickable, but Tab
        // passes it by.
        let form = FocusTraversalGroup::new(
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(FocusTraversalOrder::new(2.0, name_field))
                .child(FocusTraversalOrder::new(1.0, email_field))
                .child(ExcludeFocusTraversal::new(
                    Button::new(if help.get() { "Hide help" } else { "Help" })
                        .variant(Variant::Text)
                        .on_press(move || toggle_help.update(|shown| *shown = !*shown)),
                ))
                .child(if help.get() {
                    Text::new("Fields marked (first) and (second) show the Tab order.").size(13.0)
                } else {
                    Text::new("")
                }),
        );

        let jump = Wrap::new()
            .gap(8.0)
            .run_gap(8.0)
            .child(
                Button::new("Focus name")
                    .variant(Variant::Tonal)
                    .on_press(|| host::focus("focus-demo-name")),
            )
            .child(
                Button::new("Focus email")
                    .variant(Variant::Tonal)
                    .on_press(|| host::focus("focus-demo-email")),
            );

        // `Focus` makes anything a stop — a custom control that wants the keyboard.
        // `ExcludeFocus` takes a whole subtree out of reach: here, a field behind a panel
        // the user should not get to.
        let stops = Wrap::new()
            .gap(16.0)
            .run_gap(16.0)
            .child(Focus::new(
                Container::new()
                    .width(140.0)
                    .height(56.0)
                    .radius(8.0)
                    .color(scheme.secondary_container)
                    .alignment(Alignment::CENTER)
                    .child(Text::new("A focus stop").color(scheme.on_secondary_container)),
            ))
            .child(ExcludeFocus::new(
                TextField::new("Unreachable").label("Excluded"),
            ));

        sections(vec![
            Box::new(section("Press Tab: email, then name, then on", form)),
            Box::new(section("Focus from code", jump)),
            Box::new(section("Focus and ExcludeFocus", stops)),
        ])
    }))
}

//! `Shortcuts`, `Actions`, `ActionListener` and `CallbackShortcuts` — keyboard shortcuts.
//!
//! The work is split in two on purpose. `Shortcuts` maps a **keystroke to an intent**
//! (Ctrl+S means "save") and knows nothing of saving. `Actions` maps an **intent to a
//! handler** and knows nothing of keys. Either side can be replaced on its own: a subtree
//! can rebind the keys, or answer "save" differently — the innermost answer wins.

use frus::{
    component, ActionListener, Actions, Align, Callback, CallbackShortcuts, Column, Container,
    Intent, Kbd, KeyStroke, Row, ShortcutKey, Shortcuts, Text, TextField, Widget,
};

use crate::common::shared::{section, sections};

/// The intents this screen understands, named once.
const SAVE: Intent = Intent("save");
const CLEAR: Intent = Intent("clear");

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let draft = cx.use_state(|| "Some text to save".to_string());
        let saved = cx.use_state(|| None::<String>);
        let invoked = cx.use_state(|| 0_u32);
        let scheme = &cx.theme().scheme;

        let edit = draft.clone();
        let editor = TextField::new(draft.get())
            .label("Draft")
            .width(280.0)
            .on_input(move |text| edit.set(text));

        // Intent → handler.
        let (from, to) = (draft.clone(), saved.clone());
        let save = Callback::new(move || to.set(Some(from.get())));
        let wipe = draft.clone();
        let clear = Callback::new(move || wipe.set(String::new()));

        // Keystroke → intent, for while the focus is inside (or nothing is focused).
        // A bare letter would go to the text field first; a Ctrl combination does not.
        let bindings = Shortcuts::new(editor)
            .bind(KeyStroke::new(ShortcutKey::Char('s')).ctrl(), SAVE)
            .bind(KeyStroke::new(ShortcutKey::Char('k')).ctrl(), CLEAR);

        // `ActionListener` hears every "save" as well, without being the one that saves:
        // an undo stack, a status line, analytics.
        let count = invoked.clone();
        let heard = ActionListener::new(bindings)
            .on(SAVE, Callback::new(move || count.update(|n| *n += 1)));

        let scope = Actions::new(heard).action(SAVE, save).action(CLEAR, clear);

        // When there is no reason to name an intent, bind the key straight to a handler.
        let reset = saved.clone();
        let escape = CallbackShortcuts::new(scope).bind(
            KeyStroke::new(ShortcutKey::Escape),
            Callback::new(move || reset.set(None)),
        );

        let keys = |label: &str, stroke: &str| {
            Row::new()
                .spacing(8.0)
                .cross_axis_alignment(Align::Center)
                .child(Kbd::new(stroke))
                .child(Text::new(label).size(13.0))
        };

        sections(vec![
            Box::new(section("Type, then use the keys below", escape)),
            Box::new(section(
                "Keys",
                Column::new()
                    .spacing(8.0)
                    .cross_axis_alignment(Align::Start)
                    .child(keys("save (an intent)", "Ctrl+S"))
                    .child(keys("clear the draft (an intent)", "Ctrl+K"))
                    .child(keys("forget the saved copy (a callback)", "Esc")),
            )),
            Box::new(section(
                "Saved",
                Container::new()
                    .width(280.0)
                    .padding(12.0)
                    .radius(8.0)
                    .color(scheme.surface_container)
                    .child(
                        Column::new()
                            .spacing(4.0)
                            .cross_axis_alignment(Align::Start)
                            .child(Text::new(
                                saved.get().unwrap_or_else(|| "Nothing saved".to_string()),
                            ))
                            .child(
                                Text::new(format!("\"save\" invoked {} times", invoked.get()))
                                    .size(12.0)
                                    .color(scheme.on_surface_variant),
                            ),
                    ),
            )),
        ])
    }))
}

//! `FocusableActionDetector` and `KeyboardListener` — a custom control that answers the
//! keyboard for itself.
//!
//! `FocusableActionDetector` is a focus stop with its own key table: click it (or Tab to
//! it) and its keys work while it has the focus. `KeyboardListener` hands every keystroke
//! inside it to a closure — the escape hatch when a table cannot say what you need.

use frus::{
    Align, Alignment, Callback, Column, Container, Focus, FocusableActionDetector, Intent,
    KeyStroke, KeyboardListener, Positioned, ShortcutKey, Stack, StackFit, State, StateContext,
    StatefulWidget, Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(Board.into_widget())
}

const GRID: i32 = 5;
const CELL: f32 = 48.0;
const HOME: Intent = Intent("move-home");

struct Board;

struct BoardState {
    /// The marker's cell, column then row.
    at: (i32, i32),
    last_key: String,
}

impl StatefulWidget for Board {
    type State = BoardState;

    fn create_state(&self) -> BoardState {
        BoardState {
            at: (2, 2),
            last_key: "none yet".to_string(),
        }
    }
}

impl BoardState {
    fn step(&mut self, dx: i32, dy: i32) {
        self.at.0 = (self.at.0 + dx).clamp(0, GRID - 1);
        self.at.1 = (self.at.1 + dy).clamp(0, GRID - 1);
    }
}

impl State for BoardState {
    type Widget = Board;

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let scheme = &cx.theme().scheme;
        let side = CELL * GRID as f32;

        let board = Stack::new()
            .width(side)
            .height(side)
            .fit(StackFit::Expand)
            .layer(
                Container::new()
                    .radius(8.0)
                    .color(scheme.surface_container_high)
                    .alignment(Alignment::TOP_LEFT)
                    .padding(6.0)
                    .child(Text::new("Click, then use the arrows").size(12.0)),
            )
            .layer(
                Positioned::new(
                    Container::new()
                        .width(CELL - 8.0)
                        .height(CELL - 8.0)
                        .radius(CELL / 2.0)
                        .color(scheme.primary),
                )
                .left(self.at.0 as f32 * CELL + 4.0)
                .top(self.at.1 as f32 * CELL + 4.0),
            );

        let arrow = |key, dx, dy| (KeyStroke::new(key), cx.callback(move |s| s.step(dx, dy)));
        let detector = [
            arrow(ShortcutKey::Left, -1, 0),
            arrow(ShortcutKey::Right, 1, 0),
            arrow(ShortcutKey::Up, 0, -1),
            arrow(ShortcutKey::Down, 0, 1),
        ]
        .into_iter()
        // `on_key`: a keystroke straight to a handler, while this control has the focus.
        .fold(
            FocusableActionDetector::new(board),
            |detector, (stroke, run)| detector.on_key(stroke, run),
        )
        // Or through an intent, as `Shortcuts` and `Actions` do, in one widget.
        .bind(KeyStroke::new(ShortcutKey::Home), HOME)
        .action(HOME, cx.callback(|s| s.at = (0, 0)));

        // Every keystroke inside goes to the closure first. Answering `Some` takes the key;
        // `None` lets it carry on to the shortcuts around it.
        let heard = cx.handler(|s: &mut Self, stroke: KeyStroke| {
            let mut name = format!("{:?}", stroke.key);
            if stroke.shift {
                name = format!("Shift+{name}");
            }
            if stroke.ctrl {
                name = format!("Ctrl+{name}");
            }
            s.last_key = name;
        });
        let listener = KeyboardListener::new(
            // A listener hears the keys only while the focus is inside it, so it wraps a
            // focus stop.
            Focus::new(
                Container::new()
                    .width(side)
                    .height(56.0)
                    .radius(8.0)
                    .border(1.0, scheme.outline_variant)
                    .alignment(Alignment::CENTER)
                    .child(Text::new("Click here, then press any key")),
            ),
            move |stroke| -> Option<Callback> { Some(heard(stroke)) },
        );

        sections(vec![
            Box::new(section("Arrows move, Home goes to the corner", detector)),
            Box::new(section(
                "KeyboardListener",
                Column::new()
                    .spacing(8.0)
                    .cross_axis_alignment(Align::Start)
                    .child(listener)
                    .child(Text::new(format!("Last key: {}", self.last_key)).color(scheme.primary)),
            )),
        ])
    }
}

//! `IgnorePointer` and `AbsorbPointer` — switch off the pointer for a subtree without
//! touching the widgets in it.
//!
//! Both leave the subtree drawn exactly as it is. The difference is what happens to a tap:
//! `IgnorePointer` lets it **through** to whatever is behind; `AbsorbPointer` **stops** it,
//! so nothing behind gets it either.

use frus::{
    component, AbsorbPointer, Align, Alignment, Button, Column, Container, IgnorePointer, Row,
    Stack, StackFit, Switch, Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let blocked = cx.use_state(|| true);
        let front = cx.use_state(|| 0_u32);
        let behind = cx.use_state(|| 0_u32);
        let on = blocked.get();
        let scheme = &cx.theme().scheme;

        // A card behind, counting the taps that reach it, with a button in front of it.
        let scene = |front_button: Box<dyn Widget>| {
            let hit = behind.clone();
            Stack::new()
                .width(260.0)
                .height(110.0)
                .fit(StackFit::Expand)
                .layer(
                    Container::new()
                        .radius(12.0)
                        .color(scheme.surface_container_high)
                        .alignment(Alignment::BOTTOM_LEFT)
                        .padding(10.0)
                        .on_click(move || hit.update(|n| *n += 1))
                        .child(Text::new("Behind: tap anywhere").size(12.0)),
                )
                .layer(
                    Container::new()
                        .alignment(Alignment::TOP_CENTER)
                        .padding(12.0)
                        .child(front_button),
                )
        };
        let button = |label: &str| {
            let tap = front.clone();
            Button::new(label).on_press(move || tap.update(|n| *n += 1))
        };

        // While on, the button cannot be pressed — and a tap on it reaches the card behind.
        let ignoring = scene(Box::new(IgnorePointer::new(button("Ignored")).ignoring(on)));
        // While on, the button cannot be pressed — and the tap stops there.
        let absorbing = scene(Box::new(
            AbsorbPointer::new(button("Absorbed")).absorbing(on),
        ));

        let flip = blocked.clone();
        sections(vec![
            Box::new(section(
                "Blocking",
                Row::new()
                    .spacing(12.0)
                    .cross_axis_alignment(Align::Center)
                    .child(Switch::new(on).on_toggle(move |value| flip.set(value)))
                    .child(Text::new(if on { "On" } else { "Off" })),
            )),
            Box::new(section(
                "Counts",
                Column::new()
                    .spacing(4.0)
                    .cross_axis_alignment(Align::Start)
                    .child(Text::new(format!("Button pressed: {}", front.get())))
                    .child(Text::new(format!("Card behind tapped: {}", behind.get()))),
            )),
            Box::new(section("IgnorePointer: the tap goes through", ignoring)),
            Box::new(section("AbsorbPointer: the tap stops here", absorbing)),
        ])
    }))
}

//! `Visibility` and `Offstage` — hide a child, and choose how much of it survives being
//! hidden: its box, its input, or nothing at all.

use frus::{component, Align, Column, Container, Offstage, Row, Switch, Text, Visibility, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let shown = cx.use_state(|| true);
        let on = shown.get();
        let scheme = &cx.theme().scheme;

        // The same three boxes in each row; only the middle one is hidden.
        let block = |label: &str, highlighted: bool| {
            Container::new()
                .padding(10.0)
                .radius(8.0)
                .color(if highlighted {
                    scheme.primary_container
                } else {
                    scheme.surface_container_high
                })
                .child(Text::new(label).size(13.0))
        };
        let row = |middle: Box<dyn Widget>| {
            Row::new()
                .spacing(8.0)
                .cross_axis_alignment(Align::Center)
                .child(block("Left", false))
                .child_boxed(middle)
                .child(block("Right", false))
        };

        let flip = shown.clone();
        sections(vec![
            Box::new(section(
                "Middle box visible",
                Row::new()
                    .spacing(12.0)
                    .cross_axis_alignment(Align::Center)
                    .child(Switch::new(on).on_toggle(move |value| flip.set(value)))
                    .child(Text::new(if on { "Shown" } else { "Hidden" })),
            )),
            Box::new(section(
                "Visibility: hidden collapses the space",
                Column::new().child(row(Box::new(
                    Visibility::new(block("Middle", true)).visible(on),
                ))),
            )),
            // A spinner that comes and goes beside a label: keep its box so nothing moves.
            Box::new(section(
                "Visibility::maintain_size: hidden keeps the space",
                row(Box::new(
                    Visibility::new(block("Middle", true))
                        .visible(on)
                        .maintain_size(),
                )),
            )),
            Box::new(section(
                "Visibility::replacement: something else in its place",
                row(Box::new(
                    Visibility::new(block("Middle", true))
                        .visible(on)
                        .replacement(Text::new("…").size(13.0)),
                )),
            )),
            // Out of the layout entirely; its state is not kept while it is gone.
            Box::new(section(
                "Offstage: gone from layout, paint and input",
                row(Box::new(Offstage::new(block("Middle", true)).offstage(!on))),
            )),
        ])
    }))
}

//! The disabled state — one contract every control shares: `enabled(false)` greys it out
//! **and** makes it inert (no press, no ink, out of the Tab order, announced as disabled),
//! while it keeps showing its value.
//!
//! For a control of your own, `disabled_container(theme)` and `disabled_content(theme)`
//! give the same two colours the built-in ones use.

use frus::{
    component, disabled_container, disabled_content, Align, Button, Checkbox, Chip, Column,
    Container, Row, Slider, Switch, Text, TextField, Variant, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let enabled = cx.use_state(|| false);
        let checked = cx.use_state(|| true);
        let switched = cx.use_state(|| true);
        let level = cx.use_state(|| 0.6_f32);
        let on = enabled.get();
        let theme = cx.theme();
        let scheme = &theme.scheme;

        let flip = enabled.clone();
        let master = Row::new()
            .spacing(12.0)
            .cross_axis_alignment(Align::Center)
            .child(Switch::new(on).on_toggle(move |value| flip.set(value)))
            .child(Text::new(if on {
                "Controls enabled"
            } else {
                "Controls disabled"
            }));

        // The same `enabled` flag on every kind of control. A disabled control still
        // shows its value: the checkbox stays ticked, the slider stays where it was.
        let (tick, flick, slide) = (checked.clone(), switched.clone(), level.clone());
        let controls = Wrap::new()
            .gap(16.0)
            .run_gap(16.0)
            .child(Button::new("Filled").enabled(on).on_press(|| {}))
            .child(
                Button::new("Outlined")
                    .variant(Variant::Outlined)
                    .enabled(on)
                    .on_press(|| {}),
            )
            .child(
                Checkbox::new(checked.get())
                    .label("Checked")
                    .enabled(on)
                    .on_toggle(move |value| tick.set(value)),
            )
            .child(
                Switch::new(switched.get())
                    .enabled(on)
                    .on_toggle(move |value| flick.set(value)),
            )
            .child(Chip::new("A chip").enabled(on))
            .child(
                Slider::new(level.get())
                    .width(160.0)
                    .enabled(on)
                    .on_change(move |value| slide.set(value)),
            )
            .child(TextField::new("Read me").label("Field").enabled(on));

        // A home-made control in the same two colours: the fill and the content.
        let custom = Container::new()
            .padding(14.0)
            .radius(8.0)
            .color(if on {
                scheme.primary
            } else {
                disabled_container(theme)
            })
            .child(Text::new("Custom control").color(if on {
                scheme.on_primary
            } else {
                disabled_content(theme)
            }));

        sections(vec![
            Box::new(section("Toggle", master)),
            Box::new(section("Built-in controls", controls)),
            Box::new(section(
                "Your own control",
                Column::new()
                    .cross_axis_alignment(Align::Start)
                    .child(custom),
            )),
        ])
    }))
}

//! `Semantics`, `ExcludeSemantics` — what a screen reader is told about a widget, said
//! from outside it.
//!
//! Built-in widgets describe themselves (a button says it is a button, with its label).
//! These wrappers are for what only you know: an icon-only control's name, a row that is
//! really one thing, a heading made of a widget, a decoration that should stay silent.
//! Nothing changes on screen — turn on a screen reader (Narrator, TalkBack) to hear it.

use frus::{
    component, Align, Alignment, Column, Container, ExcludeSemantics, Icon, Icons, Role, Row,
    Semantics, SemanticsProperties, Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let liked = cx.use_state(|| false);
        let on = liked.get();
        let scheme = &cx.theme().scheme;

        // A home-made toggle drawn with a bare icon: without help a reader finds nothing
        // to announce. Give it a role, a name, its state, and say it can be activated.
        let flip = liked.clone();
        let heart = Semantics::new(
            SemanticsProperties::new(Role::Switch),
            Container::new()
                .padding(10.0)
                .radius(24.0)
                .color(scheme.surface_container_high)
                .on_click(move || flip.update(|on| *on = !*on))
                .child(Icon::new(Icons::FAVORITE).color(if on {
                    scheme.error
                } else {
                    scheme.outline
                })),
        )
        .label("Favourite")
        .toggled(on)
        .clickable(true);

        // A heading made of several widgets: announced once, as a landmark.
        let heading = Semantics::heading(
            Row::new()
                .spacing(8.0)
                .cross_axis_alignment(Align::Center)
                .child(Icon::new(Icons::INBOX).color(scheme.primary))
                .child(Text::new("Inbox").size(20.0)),
        );

        // A row of separate texts that is really one statement: merged, it is read as
        // one item rather than three.
        let merged = Semantics::merge(
            Column::new()
                .spacing(2.0)
                .cross_axis_alignment(Align::Start)
                .child(Text::new("Ada Lovelace"))
                .child(Text::new("Lunch on Friday?").size(13.0))
                .child(
                    Text::new("10:42")
                        .size(12.0)
                        .color(scheme.on_surface_variant),
                ),
        );

        // A purely decorative picture: nothing to say, so say nothing.
        let decoration = ExcludeSemantics::new(
            Container::new()
                .width(120.0)
                .height(24.0)
                .radius(12.0)
                .color(scheme.tertiary_container)
                .alignment(Alignment::CENTER)
                .child(Text::new("~ ~ ~").color(scheme.on_tertiary_container)),
        );

        sections(vec![
            Box::new(section(
                "An icon-only toggle, named",
                Row::new()
                    .spacing(12.0)
                    .cross_axis_alignment(Align::Center)
                    .child(heart)
                    .child(
                        Text::new(format!(
                            "Read as: \"Favourite, switch, {}\"",
                            if on { "on" } else { "off" }
                        ))
                        .size(13.0),
                    ),
            )),
            Box::new(section("A heading made of widgets", heading)),
            Box::new(section("Three texts read as one", merged)),
            Box::new(section("Decoration left out", decoration)),
        ])
    }))
}

//! `Permission` — asking the person for the camera, the microphone, the location and
//! notifications, and knowing what they said. `status()` looks without asking; `request()` asks
//! when there is something to ask. Both are `async`, so they run from an async handler.

use frus::{
    component, open_permission_settings, Align, Button, Column, Permission, PermissionStatus,
    Row, Text, Variant, Widget,
};

use crate::common::shared::{section, sections};

const ALL: [Permission; 4] = [
    Permission::Camera,
    Permission::Microphone,
    Permission::Location,
    Permission::Notifications,
];

fn name(permission: Permission) -> &'static str {
    match permission {
        Permission::Camera => "Camera",
        Permission::Microphone => "Microphone",
        Permission::Location => "Location",
        Permission::Notifications => "Notifications",
    }
}

fn said(status: Option<PermissionStatus>) -> &'static str {
    match status {
        None => "not looked at yet",
        Some(PermissionStatus::Granted) => "granted",
        Some(PermissionStatus::Ask) => "not decided: asking shows the question",
        Some(PermissionStatus::Denied) => "refused: asking shows the question again",
        Some(PermissionStatus::Blocked) => "blocked: only the settings can change it",
        Some(PermissionStatus::Unavailable) => "unavailable here",
    }
}

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let statuses = cx.use_state(|| [None::<PermissionStatus>; 4]);

        let mut rows = Column::new()
            .spacing(12.0)
            .cross_axis_alignment(Align::Start);
        for (index, permission) in ALL.into_iter().enumerate() {
            let (looked, answered) = (statuses.clone(), statuses.clone());
            // Looking does not ask; asking waits for the person's answer.
            let look = cx.async_callback(move || {
                let looked = looked.clone();
                async move {
                    let status = permission.status().await;
                    looked.update(|all| all[index] = Some(status));
                }
            });
            let ask = cx.async_callback(move || {
                let answered = answered.clone();
                async move {
                    let status = permission.request().await;
                    answered.update(|all| all[index] = Some(status));
                }
            });
            rows = rows.child(
                Column::new()
                    .spacing(4.0)
                    .cross_axis_alignment(Align::Start)
                    .child(Text::new(format!(
                        "{}: {}",
                        name(permission),
                        said(statuses.get()[index])
                    )))
                    .child(
                        Row::new()
                            .spacing(8.0)
                            .child(
                                Button::new("Look")
                                    .variant(Variant::Outlined)
                                    .on_press(look),
                            )
                            .child(Button::new("Ask").on_press(ask)),
                    ),
            );
        }

        sections(vec![
            Box::new(section("Each permission, looked at or asked for", rows)),
            Box::new(section(
                "After a refusal for good",
                Button::new("Open the settings")
                    .variant(Variant::Tonal)
                    .on_press(open_permission_settings),
            )),
        ])
    }))
}

//! `StatelessWidget`, `component` and `Builder` — a piece of interface pulled out into a
//! widget of its own, built from its configuration and nothing else.
//!
//! A struct with `build`, made again (cheaply) on every rebuild of its parent; or, for a
//! one-off, a closure: `frus::component(|cx| ..)` — which can also keep state with hooks.

use frus::{
    component, Align, BuildContext, Builder, Column, Container, Row, StatelessWidget, Text, Widget,
};

use crate::common::shared::{section, sections};

/// A reusable badge: what it shows is its configuration.
struct StatusBadge {
    label: &'static str,
    ok: bool,
}

impl StatelessWidget for StatusBadge {
    fn build(&self, cx: &BuildContext) -> Box<dyn Widget> {
        // The context gives the theme it is built under.
        let scheme = &cx.theme().scheme;
        let (background, foreground) = if self.ok {
            (scheme.primary_container, scheme.on_primary_container)
        } else {
            (scheme.error_container, scheme.on_error_container)
        };
        Box::new(
            Container::new()
                .padding(8.0)
                .radius(16.0)
                .color(background)
                .child(Text::new(self.label).size(13.0).color(foreground)),
        )
    }
}

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        // `.into_widget()` turns the struct into a widget for any child slot.
        Box::new(section(
            "A StatelessWidget struct, configured three times",
            Row::new()
                .spacing(8.0)
                .child(
                    StatusBadge {
                        label: "Build passing",
                        ok: true,
                    }
                    .into_widget(),
                )
                .child(
                    StatusBadge {
                        label: "Tests passing",
                        ok: true,
                    }
                    .into_widget(),
                )
                .child(
                    StatusBadge {
                        label: "Lint failing",
                        ok: false,
                    }
                    .into_widget(),
                ),
        )),
        // A closure is a component too. `Builder::new` is the same thing under another
        // name: a place in the tree with a context of its own.
        Box::new(section(
            "A closure: component(|cx| ..) / Builder::new(|cx| ..)",
            Column::new()
                .spacing(8.0)
                .cross_axis_alignment(Align::Start)
                .child(component(|cx| {
                    Box::new(Text::new("Built by a closure").color(cx.theme().primary))
                }))
                .child(Builder::new(|cx| {
                    Box::new(
                        Text::new(format!("Theme brightness: {:?}", cx.theme().brightness()))
                            .size(13.0),
                    )
                })),
        )),
    ])
}

//! `StatefulWidget` and its `State` — the lifecycle: `create_state` and `init_state` once,
//! `did_update_widget` whenever the parent hands down a new configuration, `build` on
//! every rebuild, and `dispose` when the widget leaves the screen.
//!
//! The widget is the **configuration**, made again on every rebuild; the state is what
//! the framework keeps between them.

use frus::{
    component, Align, Button, Column, Container, Row, State, StateContext, StatefulWidget, Text,
    UseState, Variant, Widget, Wrap,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let log = cx.use_state(Vec::<String>::new);
        let colour = cx.use_state(|| 0_usize);
        let shown = cx.use_state(|| true);
        let scheme = &cx.theme().scheme;

        let (next, flip, clear) = (colour.clone(), shown.clone(), log.clone());
        // A `Wrap`, not a `Row`: three buttons are wider than a phone.
        let controls = Wrap::new()
            .gap(8.0)
            .run_gap(8.0)
            .child(
                // A new configuration for the same widget: `did_update_widget`.
                Button::new("Change its label")
                    .variant(Variant::Tonal)
                    .on_press(move || next.update(|i| *i = (*i + 1) % LABELS.len())),
            )
            .child(
                // Out of the tree and back: `dispose`, then a fresh `init_state`.
                Button::new(if shown.get() {
                    "Remove it"
                } else {
                    "Put it back"
                })
                .variant(Variant::Outlined)
                .on_press(move || flip.update(|on| *on = !*on)),
            )
            .child(
                Button::new("Clear log")
                    .variant(Variant::Text)
                    .on_press(move || clear.set(Vec::new())),
            );

        let child: Box<dyn Widget> = if shown.get() {
            Box::new(
                Tally {
                    label: LABELS[colour.get()],
                    log: log.clone(),
                }
                .into_widget(),
            )
        } else {
            Box::new(Text::new("(removed)").size(13.0))
        };

        let lines = log.get().into_iter().rev().take(8).fold(
            Column::new()
                .spacing(2.0)
                .cross_axis_alignment(Align::Start),
            |column, line| column.child(Text::new(line).size(13.0)),
        );

        sections(vec![
            Box::new(section("Controls", controls)),
            Box::new(section("The stateful widget", child)),
            Box::new(section(
                "Lifecycle log, newest first",
                Container::new()
                    .width(300.0)
                    .padding(12.0)
                    .radius(8.0)
                    .color(scheme.surface_container)
                    .child(lines),
            )),
        ])
    }))
}

const LABELS: [&str; 3] = ["Apples", "Pears", "Plums"];

/// The configuration: a label, and where to write the lifecycle down.
struct Tally {
    label: &'static str,
    log: UseState<Vec<String>>,
}

/// What survives rebuilds: the count. It also keeps the log, because `dispose` is given
/// nothing else.
struct TallyState {
    count: u32,
    log: UseState<Vec<String>>,
}

impl TallyState {
    fn write(&self, line: String) {
        self.log.update(|log| log.push(line));
    }
}

impl StatefulWidget for Tally {
    type State = TallyState;

    fn create_state(&self) -> TallyState {
        TallyState {
            count: 0,
            log: self.log.clone(),
        }
    }
}

impl State for TallyState {
    type Widget = Tally;

    fn init_state(&mut self, cx: &StateContext<Self>) {
        self.write(format!("init_state ({})", cx.widget().label));
    }

    fn did_update_widget(&mut self, old: &Tally, cx: &StateContext<Self>) {
        // Called on every rebuild of the parent; compare to see what actually changed.
        let new = cx.widget().label;
        if old.label != new {
            self.write(format!("did_update_widget: {} → {new}", old.label));
        }
    }

    fn dispose(&mut self) {
        self.write(format!("dispose (count was {})", self.count));
    }

    fn build(&self, cx: &StateContext<Self>) -> Box<dyn Widget> {
        let scheme = &cx.theme().scheme;
        Box::new(
            Row::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Center)
                .child(
                    Container::new()
                        .padding(12.0)
                        .radius(8.0)
                        .color(scheme.secondary_container)
                        .child(
                            Text::new(format!("{}: {}", cx.widget().label, self.count))
                                .color(scheme.on_secondary_container),
                        ),
                )
                .child(
                    Button::new("+1")
                        .variant(Variant::Tonal)
                        .on_press(cx.callback(|s| s.count += 1)),
                ),
        )
    }
}

//! Hooks — `use_state`, `use_ref` and `use_memo`: state kept by a plain function
//! component (`frus::component(|cx| ..)`), with no struct to declare.
//!
//! Hooks are matched to their values by the **order** they are called in, so call them
//! unconditionally and in the same order on every build: never inside an `if`, a loop or
//! a closure.

use frus::{component, Align, Button, Column, Component, Row, Slider, Text, Variant, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        Box::new(section(
            "use_state: a value that rebuilds when set",
            counter(),
        )),
        Box::new(section("use_ref: a value that does not", builds())),
        Box::new(section(
            "use_memo: work redone only when its input changes",
            primes(),
        )),
    ])
}

pub fn counter() -> Component {
    component(|cx| {
        // Made by the closure the first time, then kept for as long as the component is
        // on screen. `set` and `update` ask for a rebuild.
        let count = cx.use_state(|| 0);
        let (up, reset) = (count.clone(), count.clone());
        Box::new(
            Row::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Center)
                .child(Button::new("Add one").on_press(move || up.update(|n| *n += 1)))
                .child(
                    Button::new("Reset")
                        .variant(Variant::Text)
                        .on_press(move || reset.set(0)),
                )
                .child(Text::new(format!("count = {}", count.get()))),
        )
    })
}

pub fn builds() -> Component {
    component(|cx| {
        // A `use_ref` changes without rebuilding: right for bookkeeping the screen does not
        // show directly — a timer handle, a previous value, a counter of builds.
        let built = cx.use_ref(|| 0_u32);
        built.update(|n| *n += 1);
        let pending = cx.use_ref(|| 0_u32);
        let rebuilds = cx.use_state(|| ());

        let (add, show) = (pending.clone(), rebuilds.clone());
        Box::new(
            Column::new()
                .spacing(8.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    Row::new()
                        .spacing(8.0)
                        .child(
                            Button::new("Add to the ref")
                                .variant(Variant::Tonal)
                                .on_press(move || add.update(|n| *n += 1)),
                        )
                        .child(
                            // Setting a state — even to the same value — rebuilds, and
                            // the ref's current value shows.
                            Button::new("Rebuild")
                                .variant(Variant::Outlined)
                                .on_press(move || show.set(())),
                        ),
                )
                .child(Text::new(format!(
                    "ref = {} (shown as of the last build) · {} builds of this component",
                    pending.get(),
                    built.get()
                ))),
        )
    })
}

pub fn primes() -> Component {
    component(|cx| {
        let limit = cx.use_state(|| 10_000.0_f32);
        let unrelated = cx.use_state(|| 0_u32);
        let n = limit.get() as usize;

        // Recomputed only when `n` changes: pressing "Unrelated" rebuilds, but the count
        // comes from the memo.
        let runs = cx.use_ref(|| 0_u32);
        let counted = {
            let runs = runs.clone();
            cx.use_memo(n, move || {
                runs.update(|r| *r += 1);
                count_primes(n)
            })
        };

        let (set, bump) = (limit.clone(), unrelated.clone());
        Box::new(
            Column::new()
                .spacing(8.0)
                .cross_axis_alignment(Align::Start)
                .child(
                    Slider::new(limit.get())
                        .range(1_000.0, 50_000.0)
                        .width(260.0)
                        .on_change(move |value| set.set(value.round())),
                )
                .child(Text::new(format!("{counted} primes below {n}")))
                .child(
                    Row::new()
                        .spacing(12.0)
                        .cross_axis_alignment(Align::Center)
                        .child(
                            Button::new("Unrelated rebuild")
                                .variant(Variant::Outlined)
                                .on_press(move || bump.update(|n| *n += 1)),
                        )
                        .child(
                            Text::new(format!(
                                "{} rebuilds, {} computations",
                                unrelated.get(),
                                runs.get()
                            ))
                            .size(13.0),
                        ),
                ),
        )
    })
}

/// How many primes are below `n` — a sieve, cheap but not free.
pub fn count_primes(n: usize) -> usize {
    if n < 3 {
        return 0;
    }
    let mut composite = vec![false; n];
    let mut count = 0;
    for i in 2..n {
        if !composite[i] {
            count += 1;
            let mut multiple = i * i;
            while multiple < n {
                composite[multiple] = true;
                multiple += i;
            }
        }
    }
    count
}

//! `use_effect` — work to do **after** a build: subscribe, start something, write a log.
//! It runs again only when its dependencies change, and the closure it returns (the
//! cleanup) runs before the next run and when the component leaves the screen.

use frus::{
    component, Align, Button, Column, Component, Container, Row, Text, UseState, Variant, Widget,
};

use crate::common::shared::{section, sections};

/// How many lines of the log are shown.
const LINES: usize = 8;

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let log = cx.use_state(Vec::<String>::new);
        let mounted = cx.use_state(|| true);
        let count = cx.use_state(|| 0_u32);
        let scheme = &cx.theme().scheme;

        let (flip, add, clear) = (mounted.clone(), count.clone(), log.clone());
        let controls = Row::new()
            .spacing(8.0)
            .child(
                Button::new(if mounted.get() {
                    "Remove child"
                } else {
                    "Add child"
                })
                .variant(Variant::Tonal)
                .on_press(move || flip.update(|on| *on = !*on)),
            )
            .child(
                Button::new("Count + 1")
                    .variant(Variant::Outlined)
                    .on_press(move || add.update(|n| *n += 1)),
            )
            .child(
                Button::new("Clear log")
                    .variant(Variant::Text)
                    .on_press(move || clear.set(Vec::new())),
            );

        let mut child = Column::new();
        if mounted.get() {
            child = child.child(watcher(count.get(), log.clone()));
        } else {
            child = child.child(Text::new("(no child)").size(13.0));
        }

        let lines = log.get().into_iter().rev().take(LINES).fold(
            Column::new()
                .spacing(2.0)
                .cross_axis_alignment(Align::Start),
            |column, line| column.child(Text::new(line).size(13.0)),
        );

        sections(vec![
            Box::new(section("Controls", controls)),
            Box::new(section("The child component", child)),
            Box::new(section(
                "Log, newest first",
                Container::new()
                    .width(300.0)
                    .padding(12.0)
                    .radius(8.0)
                    .color(scheme.surface_container)
                    .child(lines),
            )),
        ])
    }))
}

/// A child with two effects, writing to its parent's log.
fn watcher(count: u32, log: UseState<Vec<String>>) -> Component {
    component(move |cx| {
        // `()` as the dependencies: once when the component appears; the returned closure
        // runs when it goes.
        let on_mount = log.clone();
        cx.use_effect((), move || {
            on_mount.update(|log| log.push("effect: mounted".to_string()));
            move || on_mount.update(|log| log.push("cleanup: unmounted".to_string()))
        });

        // Keyed on `count`: runs after each build where the count changed, cleaning up
        // the previous run first.
        let on_count = log.clone();
        cx.use_effect(count, move || {
            on_count.update(|log| log.push(format!("effect: count is {count}")));
            move || on_count.update(|log| log.push(format!("cleanup: count was {count}")))
        });

        Box::new(Text::new(format!("I am mounted; count = {count}")))
    })
}

//! `use_interval` — a timer owned by a component: it ticks for as long as builds keep
//! asking for it, and stops by itself when a build does not (or the component goes).
//!
//! Unlike the other hooks it **may** be called conditionally: `if running { .. }` is
//! exactly how a timer is switched on and off.

use std::time::Duration;

use frus::{component, Align, Button, Column, FontWeight, Row, Text, Variant, Widget};

use crate::common::shared::{section, sections};

/// The tick, in tenths of a second.
const TICK: Duration = Duration::from_millis(100);

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let tenths = cx.use_state(|| 0_u64);
        let running = cx.use_state(|| false);

        // Only while running: the next build without this call stops the timer.
        if running.get() {
            let tick = tenths.clone();
            cx.use_interval(TICK, move || tick.update(|t| *t += 1));
        }

        let t = tenths.get();
        let (toggle, reset) = (running.clone(), tenths.clone());
        let stop = running.clone();
        let display = Text::new(format!("{}:{:02}.{}", t / 600, (t / 10) % 60, t % 10))
            .size(40.0)
            .weight(FontWeight::Bold)
            .color(cx.theme().primary);

        sections(vec![Box::new(section(
            "A stopwatch",
            Column::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Start)
                .child(display)
                .child(
                    Row::new()
                        .spacing(8.0)
                        .child(
                            Button::new(if running.get() { "Pause" } else { "Start" })
                                .on_press(move || toggle.update(|on| *on = !*on)),
                        )
                        .child(Button::new("Reset").variant(Variant::Outlined).on_press(
                            move || {
                                stop.set(false);
                                reset.set(0);
                            },
                        )),
                ),
        ))])
    }))
}

//! `ValueNotifier`, `ChangeNotifier` and the builders that follow them —
//! `ValueListenableBuilder` and `ListenableBuilder`.
//!
//! A notifier is state that lives **outside** the widgets — in a model, a service, a
//! controller — and tells whoever cares when it changed. Cloning one gives another
//! handle to the same value, so it can be handed to every widget that needs it.

use std::cell::RefCell;
use std::rc::Rc;

use frus::{
    component, Align, Button, ChangeNotifier, Column, Listenable, ListenableBuilder, Row, Text,
    ValueListenableBuilder, ValueNotifier, Variant, Widget,
};

use crate::common::shared::{section, sections};

/// A small model with a `ChangeNotifier` inside: its own methods change it and say so.
#[derive(Clone, Default)]
struct Basket {
    items: Rc<RefCell<Vec<&'static str>>>,
    changed: ChangeNotifier,
}

impl Basket {
    fn add(&self, item: &'static str) {
        self.items.borrow_mut().push(item);
        self.changed.notify_listeners();
    }

    fn clear(&self) {
        self.items.borrow_mut().clear();
        self.changed.notify_listeners();
    }

    fn summary(&self) -> String {
        let items = self.items.borrow();
        if items.is_empty() {
            "The basket is empty".to_string()
        } else {
            format!("{} items: {}", items.len(), items.join(", "))
        }
    }
}

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        // In an app these would live in a service or a page's state; `use_ref` keeps them
        // for the demo's lifetime.
        let volume = cx.use_ref(|| ValueNotifier::new(3_i32)).get();
        let basket = cx.use_ref(Basket::default).get();

        // Listening by hand: a subscription made in an effect, dropped by its cleanup.
        let notifications = cx.use_state(|| 0_u32);
        {
            let (basket, heard) = (basket.clone(), notifications.clone());
            cx.use_effect((), move || {
                let subscription = basket
                    .changed
                    .add_listener(move || heard.update(|n| *n += 1));
                move || drop(subscription)
            });
        }

        let (down, up) = (volume.clone(), volume.clone());
        let volume_controls = Row::new()
            .spacing(8.0)
            .cross_axis_alignment(Align::Center)
            .child(
                Button::new("−")
                    .variant(Variant::Outlined)
                    .on_press(move || down.update(|v| *v = (*v - 1).max(0))),
            )
            .child(
                Button::new("+")
                    .variant(Variant::Outlined)
                    .on_press(move || up.update(|v| *v = (*v + 1).min(10))),
            )
            // Rebuilt from the notifier's value whenever it changes.
            .child(ValueListenableBuilder::new(
                volume.clone(),
                |cx, level: &i32| {
                    Box::new(
                        Text::new(format!("Volume {level} {}", "▮".repeat(*level as usize)))
                            .color(cx.theme().primary),
                    )
                },
            ));

        let (apples, pears, emptied) = (basket.clone(), basket.clone(), basket.clone());
        let basket_controls = Row::new()
            .spacing(8.0)
            .child(
                Button::new("Add an apple")
                    .variant(Variant::Tonal)
                    .on_press(move || apples.add("apple")),
            )
            .child(
                Button::new("Add a pear")
                    .variant(Variant::Tonal)
                    .on_press(move || pears.add("pear")),
            )
            .child(
                Button::new("Empty")
                    .variant(Variant::Text)
                    .on_press(move || emptied.clear()),
            );

        sections(vec![
            Box::new(section(
                "ValueNotifier + ValueListenableBuilder",
                volume_controls,
            )),
            Box::new(section(
                "ChangeNotifier in a model + ListenableBuilder",
                Column::new()
                    .spacing(8.0)
                    .cross_axis_alignment(Align::Start)
                    .child(basket_controls)
                    // Follows the model's notifier, and reads the model when it fires.
                    .child({
                        let basket = basket.clone();
                        ListenableBuilder::new(basket.changed.clone(), move |_, _| {
                            Box::new(Text::new(basket.summary()))
                        })
                    }),
            )),
            Box::new(section(
                "add_listener",
                Text::new(format!(
                    "The basket has notified {} times",
                    notifications.get()
                ))
                .size(13.0),
            )),
        ])
    }))
}

//! `use_future` and `FutureBuilder` — work that finishes later: start it once, show
//! "waiting" meanwhile, then the result. A rebuild does not start it again; a change of
//! its key (the dependencies) does.
//!
//! The future runs on the framework's executor natively (so it must be `Send`), and on
//! the browser's on the web. Work that can fail returns a `Result`, shown like any value.

use frus::{
    component, Align, AsyncSnapshot, Button, CircularProgressIndicator, Column, ConnectionState,
    FutureBuilder, Row, Text, Variant, Widget, Wrap,
};

use crate::common::shared::{section, sections};

const LIMITS: [usize; 3] = [100_000, 1_000_000, 3_000_000];

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let limit = cx.use_state(|| LIMITS[0]);
        let n = limit.get();

        // Keyed on `n`: picking another limit starts a new computation, and whatever the
        // old one gives is ignored.
        let snapshot = cx.use_future(n, move || async move { count_primes(n) });

        let picker = LIMITS
            .iter()
            .fold(Wrap::new().gap(8.0).run_gap(8.0), |row, &value| {
                let pick = limit.clone();
                row.child(
                    Button::new(format!("below {value}"))
                        .variant(if value == n {
                            Variant::Filled
                        } else {
                            Variant::Outlined
                        })
                        .on_press(move || pick.set(value)),
                )
            });

        sections(vec![
            Box::new(section(
                "cx.use_future: count primes on the executor",
                Column::new()
                    .spacing(12.0)
                    .cross_axis_alignment(Align::Start)
                    .child(picker)
                    .child(show(&snapshot, n)),
            )),
            // The same as a widget: the key, how to make the future, and how to build from
            // the snapshot.
            Box::new(section(
                "FutureBuilder",
                FutureBuilder::new(
                    "greeting",
                    |_: &&str| async {
                        format!(
                            "Hello from a future, {} primes below 50 000",
                            count_primes(50_000)
                        )
                    },
                    |_, snapshot| {
                        Box::new(Text::new(
                            snapshot.data.unwrap_or_else(|| "Working…".to_string()),
                        ))
                    },
                ),
            )),
        ])
    }))
}

/// What a snapshot looks like on screen, state by state.
fn show(snapshot: &AsyncSnapshot<usize>, n: usize) -> Box<dyn Widget> {
    match (snapshot.state, snapshot.data) {
        (ConnectionState::Done, Some(count)) => {
            Box::new(Text::new(format!("{count} primes below {n}")))
        }
        _ => Box::new(
            Row::new()
                .spacing(12.0)
                .cross_axis_alignment(Align::Center)
                .child(CircularProgressIndicator::new().size(20.0))
                .child(Text::new("Counting…")),
        ),
    }
}

/// How many primes are below `n` — a sieve, slow enough for big `n` to see the wait.
fn count_primes(n: usize) -> usize {
    if n < 3 {
        return 0;
    }
    let mut composite = vec![false; n];
    let mut count = 0;
    for i in 2..n {
        if !composite[i] {
            count += 1;
            let mut multiple = i * i;
            while multiple < n {
                composite[multiple] = true;
                multiple += i;
            }
        }
    }
    count
}

//! `use_stream` and `StreamBuilder` — work that gives **several** values as it goes: a
//! progress, a feed, messages. The work is handed a `StreamSink` and `add`s each value;
//! the component shows the latest one, then knows when the work is done.

use frus::{
    component, Align, AsyncSnapshot, Button, Column, ConnectionState, LinearProgressIndicator,
    StreamBuilder, Text, Variant, Widget,
};

use crate::common::shared::{section, sections};

/// The work is split in this many steps, each reported.
pub const STEPS: u32 = 40;
/// How far each step searches.
pub const PER_STEP: u64 = 4_000;

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        // The run number is the dependency: bumping it starts the work again.
        let run = cx.use_state(|| 0_u32);
        let snapshot = cx.use_stream(run.get(), |sink| async move {
            let mut found = 0;
            for step in 0..STEPS {
                let start = u64::from(step) * PER_STEP;
                found += (start..start + PER_STEP).filter(|&n| is_prime(n)).count();
                sink.add(Progress {
                    done: step + 1,
                    found,
                });
            }
        });

        let again = run.clone();
        sections(vec![
            Box::new(section(
                "cx.use_stream: search primes, reporting each step",
                Column::new()
                    .spacing(12.0)
                    .cross_axis_alignment(Align::Start)
                    .child(show(&snapshot))
                    .child(
                        Button::new("Run again")
                            .variant(Variant::Tonal)
                            .on_press(move || again.update(|n| *n += 1)),
                    ),
            )),
            // The same as a widget. Here the stream is a countdown.
            Box::new(section(
                "StreamBuilder",
                StreamBuilder::new(
                    (),
                    |_: &(), sink| async move {
                        for left in (0..=5).rev() {
                            sink.add(left);
                        }
                    },
                    |_, snapshot: AsyncSnapshot<i32>| {
                        Box::new(Text::new(match (snapshot.state, snapshot.data) {
                            (ConnectionState::Done, _) => "Lift-off".to_string(),
                            (_, Some(left)) => format!("{left}…"),
                            (_, None) => "Waiting".to_string(),
                        }))
                    },
                ),
            )),
        ])
    }))
}

#[derive(Clone, Copy)]
pub struct Progress {
    done: u32,
    found: usize,
}

pub fn show(snapshot: &AsyncSnapshot<Progress>) -> Box<dyn Widget> {
    let progress = snapshot.data.map_or(0.0, |p| p.done as f32 / STEPS as f32);
    let label = match (snapshot.state, snapshot.data) {
        (ConnectionState::Waiting, _) | (_, None) => "Starting…".to_string(),
        (ConnectionState::Active, Some(p)) => {
            format!("Step {}/{STEPS}: {} primes so far", p.done, p.found)
        }
        (ConnectionState::Done, Some(p)) => {
            format!(
                "Done: {} primes below {}",
                p.found,
                u64::from(STEPS) * PER_STEP
            )
        }
    };
    Box::new(
        Column::new()
            .spacing(8.0)
            .cross_axis_alignment(Align::Start)
            .child(LinearProgressIndicator::new(progress).width(260.0))
            .child(Text::new(label)),
    )
}

/// Trial division: slow on purpose, so the steps can be seen.
pub fn is_prime(n: u64) -> bool {
    if n < 2 {
        return false;
    }
    let mut d = 2;
    while d * d <= n {
        if n.is_multiple_of(d) {
            return false;
        }
        d += 1;
    }
    true
}

//! `host::spawn` and `host::after` — run slow work on another thread and get its result
//! back on the interface's thread, or run something after a delay.
//!
//! Both can be called from any handler. The callback that receives the result runs on the
//! interface's thread, so it may change state like any other handler.

use std::time::Duration;

use frus::{component, host, Align, Button, Column, Row, Text, Variant, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let result = cx.use_state(|| "Not started".to_string());
        let busy = cx.use_state(|| false);
        let reminder = cx.use_state(|| None::<String>);

        let (out, working) = (result.clone(), busy.clone());
        let start = move || {
            working.set(true);
            out.set("Working on another thread…".to_string());
            let (out, working) = (out.clone(), working.clone());
            host::spawn(
                // Runs off the interface's thread: it must not touch widgets or state.
                || fibonacci(32),
                // Runs back on the interface's thread, with what the work made.
                move |value| {
                    out.set(format!("fibonacci(32) = {value}"));
                    working.set(false);
                },
            );
        };

        let note = reminder.clone();
        let remind = move || {
            note.set(Some("Waiting two seconds…".to_string()));
            let note = note.clone();
            host::after(Duration::from_secs(2), move || {
                note.set(Some(
                    "Two seconds later: here is your reminder.".to_string(),
                ));
            });
        };

        sections(vec![
            Box::new(section(
                "host::spawn",
                Column::new()
                    .spacing(8.0)
                    .cross_axis_alignment(Align::Start)
                    .child(
                        Button::new("Compute fibonacci(32)")
                            .enabled(!busy.get())
                            .on_press(start),
                    )
                    .child(Text::new(result.get())),
            )),
            Box::new(section(
                "host::after",
                Row::new()
                    .spacing(12.0)
                    .cross_axis_alignment(Align::Center)
                    .child(
                        Button::new("Remind me in 2 s")
                            .variant(Variant::Tonal)
                            .on_press(remind),
                    )
                    .child(Text::new(reminder.get().unwrap_or_default()).size(13.0)),
            )),
        ])
    }))
}

/// Deliberately slow: the naive recursion, to give the thread something to do.
pub fn fibonacci(n: u32) -> u64 {
    if n < 2 {
        u64::from(n)
    } else {
        fibonacci(n - 1) + fibonacci(n - 2)
    }
}

//! `keyed` / `Keyed` — give a widget a stable identity, so its state follows it when its
//! siblings move.
//!
//! Without a key, a state belongs to a **position** among siblings: rotate a list and each
//! row keeps the count of whatever row used to be there. With `keyed(id, row)` the state
//! belongs to the id. Key every row of a list that can reorder, insert or remove.

use frus::{
    component, keyed, Align, Button, Column, Component, Container, Row, Text, Variant, Widget, Wrap,
};

use crate::common::shared::{section, sections};

const NAMES: [&str; 3] = ["Ada", "Grace", "Alan"];

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let order = cx.use_state(|| NAMES.to_vec());

        let (rotate, reset) = (order.clone(), order.clone());
        let controls = Row::new()
            .spacing(8.0)
            .child(
                Button::new("Rotate the rows")
                    .variant(Variant::Tonal)
                    .on_press(move || rotate.update(|names| names.rotate_left(1))),
            )
            .child(
                Button::new("Reset")
                    .variant(Variant::Text)
                    .on_press(move || reset.set(NAMES.to_vec())),
            );

        let names = order.get();
        // Each row keeps its own count with `use_state`.
        let unkeyed = names.iter().fold(
            Column::new()
                .spacing(6.0)
                .cross_axis_alignment(Align::Start),
            |column, name| column.child(row(name)),
        );
        let with_keys = names.iter().fold(
            Column::new()
                .spacing(6.0)
                .cross_axis_alignment(Align::Start),
            |column, name| column.child(keyed(*name, row(name))),
        );

        sections(vec![
            Box::new(section("Tap +1 on a few rows, then rotate", controls)),
            Box::new(
                Wrap::new()
                    .gap(32.0)
                    .run_gap(24.0)
                    .child(section("No keys: counts stay put", unkeyed))
                    .child(section("keyed(name, ..): counts follow", with_keys)),
            ),
        ])
    }))
}

/// A row with a count of its own.
fn row(name: &'static str) -> Component {
    component(move |cx| {
        let count = cx.use_state(|| 0_u32);
        let scheme = &cx.theme().scheme;
        let add = count.clone();
        Box::new(
            Container::new()
                .width(200.0)
                .padding(8.0)
                .radius(8.0)
                .color(scheme.surface_container)
                .child(
                    Row::new()
                        .spacing(8.0)
                        .cross_axis_alignment(Align::Center)
                        .child(Text::new(format!("{name}: {}", count.get())))
                        .child(
                            Button::new("+1")
                                .variant(Variant::Text)
                                .on_press(move || add.update(|n| *n += 1)),
                        ),
                ),
        )
    })
}

//! `Theme` — reading the colours and type every widget is dressed in (`cx.theme()`), and
//! switching the whole application between light and dark (`host::app()`).
//!
//! Read colours from the theme rather than writing them down: then dark mode, a brand
//! colour or a high-contrast theme reaches your widgets too.

use frus::{
    component, host, Align, Callback, Color, Column, Container, Row, SegmentedButton, Text, Theme,
    ThemeMode, Widget, Wrap,
};

use crate::common::shared::{section, sections};

const MODES: [(ThemeMode, &str); 3] = [
    (ThemeMode::Light, "Light"),
    (ThemeMode::Dark, "Dark"),
    (ThemeMode::System, "System"),
];

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let theme = cx.theme();
        let scheme = &theme.scheme;

        // The application's settings live in `host::app()`: the theme, the dark theme and
        // which of the two is on show. Changing one rebuilds the whole window.
        let app = host::app();
        let current = MODES
            .iter()
            .position(|(mode, _)| *mode == app.theme_mode())
            .unwrap_or(2);
        let modes = MODES.iter().fold(
            SegmentedButton::new(current, |index| {
                Callback::new(move || {
                    let app = host::app();
                    // An application with a single theme has nothing to switch to: give
                    // it a dark one the first time it is asked for.
                    if app.dark_theme().is_none() {
                        app.set_dark_theme(Some(Theme::dark()));
                    }
                    app.set_theme_mode(MODES[index].0);
                })
            }),
            |picker, (_, name)| picker.segment(*name),
        );

        let swatch = |name: &str, background: Color, foreground: Color| {
            Container::new()
                .width(132.0)
                .padding(10.0)
                .radius(8.0)
                .color(background)
                .border(1.0, scheme.outline_variant)
                .child(Text::new(name).size(12.0).color(foreground))
        };
        let colours = Wrap::new()
            .gap(8.0)
            .run_gap(8.0)
            .child(swatch("primary", scheme.primary, scheme.on_primary))
            .child(swatch(
                "primary_container",
                scheme.primary_container,
                scheme.on_primary_container,
            ))
            .child(swatch("secondary", scheme.secondary, scheme.on_secondary))
            .child(swatch("tertiary", scheme.tertiary, scheme.on_tertiary))
            .child(swatch("surface", scheme.surface, scheme.on_surface))
            .child(swatch(
                "surface_container_high",
                scheme.surface_container_high,
                scheme.on_surface,
            ))
            .child(swatch("error", scheme.error, scheme.on_error))
            .child(swatch(
                "inverse_surface",
                scheme.inverse_surface,
                scheme.on_inverse_surface,
            ));

        // The type scale: a named style for each role, rather than sizes picked by hand.
        let text = &theme.text;
        let type_scale = Column::new()
            .spacing(6.0)
            .cross_axis_alignment(Align::Start)
            .child(Text::styled("headline_small", text.headline_small))
            .child(Text::styled("title_medium", text.title_medium))
            .child(Text::styled("body_medium", text.body_medium))
            .child(Text::styled("label_small", text.label_small));

        sections(vec![
            Box::new(section(
                "Theme mode (the whole gallery follows)",
                Column::new()
                    .spacing(8.0)
                    .cross_axis_alignment(Align::Start)
                    .child(modes)
                    .child(
                        Text::new(format!("Building under a {:?} theme", theme.brightness()))
                            .size(13.0),
                    ),
            )),
            Box::new(section("Colour roles: cx.theme().scheme", colours)),
            Box::new(section(
                "Type roles: cx.theme().text",
                Row::new().child(type_scale),
            )),
        ])
    }))
}

//! `Themed` and `ThemeBuilder` — a different theme for one part of the screen.
//!
//! `Themed::new` replaces the theme for a subtree (a dark promo card on a light page).
//! `Themed::tweak` changes **part** of the inherited one (this section's buttons are
//! teal), keeping everything else. `ThemeBuilder` builds a subtree from whatever theme
//! is in force where it sits.

use frus::{
    component, Align, Button, Card, Color, Colors, Column, Container, Text, Theme, ThemeBuilder,
    Themed, Variant, Widget, Wrap,
};

use crate::common::shared::{section, sections};

/// A few widgets that only read the theme: shown under each theme below.
fn sample() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let scheme = &cx.theme().scheme;
        Box::new(
            Container::new()
                .width(260.0)
                .padding(16.0)
                .radius(12.0)
                .color(scheme.surface_container)
                .child(
                    Column::new()
                        .spacing(10.0)
                        .cross_axis_alignment(Align::Start)
                        .child(Text::new("Weekly digest").color(scheme.on_surface))
                        .child(
                            Wrap::new()
                                .gap(8.0)
                                .run_gap(8.0)
                                .child(Button::new("Open").on_press(|| {}))
                                .child(
                                    Button::new("Later")
                                        .variant(Variant::Outlined)
                                        .on_press(|| {}),
                                ),
                        ),
                ),
        )
    }))
}

pub fn example() -> Box<dyn Widget> {
    sections(vec![
        Box::new(section("The theme around it", sample())),
        // A whole theme, made from one seed colour, dark whatever the app is.
        Box::new(section(
            "Themed::new(Theme::from_seed(purple, dark))",
            Themed::new(Theme::from_seed(Color::hex("#7C3AED"), true), sample()),
        )),
        // Only the buttons change; the surface and text stay the inherited ones.
        Box::new(section(
            "Themed::tweak: teal buttons only",
            Themed::tweak(
                |theme| {
                    theme.widgets.button.color = Some(Color::hex("#0F766E"));
                    theme.widgets.button.label_color = Some(Colors::WHITE);
                },
                sample(),
            ),
        )),
        // Built late, from the theme in force *here* — inside the dark `Themed`, the
        // builder sees the dark theme.
        Box::new(section(
            "ThemeBuilder: build from the ambient theme",
            Themed::new(
                Theme::from_seed(Color::hex("#0EA5E9"), true),
                ThemeBuilder::new(|theme| {
                    Card::new().padding(16.0).child(
                        Text::new(format!("Built under a {:?} theme", theme.brightness()))
                            .color(theme.scheme.on_surface),
                    )
                }),
            ),
        )),
    ])
}

//! `MediaQuery` — what the screen is like: its size, density, the system's insets (status
//! bar, notch, keyboard), the reader's text size, light or dark, orientation and size
//! class. `MediaScope` changes part of it for a subtree.
//!
//! Resize the window: the values below follow.

use frus::{component, Align, Column, Container, Insets, MediaQuery, MediaScope, Text, Widget};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        // The description in force where this is built. Read it in `build`, never cache
        // it: a resize or a rotation rebuilds, and it is read afresh.
        let media = MediaQuery::of();
        let scheme = &cx.theme().scheme;

        let insets = |i: Insets| {
            format!(
                "top {:.0}, right {:.0}, bottom {:.0}, left {:.0}",
                i.top, i.right, i.bottom, i.left
            )
        };
        let lines = [
            (
                "size",
                format!(
                    "{:.0} × {:.0} logical px",
                    media.size.width, media.size.height
                ),
            ),
            (
                "device_pixel_ratio",
                format!("{:.2}", media.device_pixel_ratio),
            ),
            ("orientation()", format!("{:?}", media.orientation())),
            ("size_class()", format!("{:?}", media.size_class())),
            ("padding (system bars)", insets(media.padding)),
            ("view_insets (keyboard)", insets(media.view_insets)),
            ("safe()", insets(media.safe())),
            ("text_scaler", format!("{:.2}", media.text_scaler)),
            (
                "platform_brightness",
                format!("{:?}", media.platform_brightness),
            ),
            (
                "accessibility.disable_animations",
                format!("{}", media.accessibility.disable_animations),
            ),
        ];
        let table = lines.into_iter().fold(
            Column::new()
                .spacing(6.0)
                .cross_axis_alignment(Align::Start),
            |column, (name, value)| {
                column.child(
                    Column::new()
                        .cross_axis_alignment(Align::Start)
                        .child(Text::new(name).size(12.0).color(scheme.on_surface_variant))
                        .child(Text::new(value)),
                )
            },
        );

        // A subtree that believes the reader asked for bigger text.
        let scaled = MediaScope::tweak(
            |media| media.text_scaler = 1.5,
            Container::new()
                .padding(12.0)
                .radius(8.0)
                .color(scheme.surface_container)
                .child(Text::new("Laid out at a text scale of 1.5")),
        );

        sections(vec![
            Box::new(section("MediaQuery::of()", table)),
            Box::new(section("MediaScope::tweak", scaled)),
        ])
    }))
}

//! `Responsive`, `LayoutBuilder` and `OrientationBuilder` — one interface, several
//! layouts.
//!
//! `responsive(width)` picks a subtree by size class (compact < 600 px, medium < 840 px,
//! expanded beyond), usually from the window's width. `LayoutBuilder` builds from the room
//! **this box** is given — a component that adapts wherever it is put, in a sidebar as
//! well as full screen. Resize the window to watch them switch.

use frus::{
    component, responsive, Align, Alignment, Column, Container, LayoutBuilder, MediaQuery,
    Orientation, OrientationBuilder, Row, Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let scheme = &cx.theme().scheme;
        let (fill, on_fill) = (scheme.secondary_container, scheme.on_secondary_container);
        let outline = scheme.outline_variant;
        let panel = move |label: &str| {
            Container::new()
                .padding(12.0)
                .radius(8.0)
                .color(fill)
                .child(Text::new(label).color(on_fill))
        };

        // Variants per breakpoint; a missing one falls back to the nearest smaller one.
        let width = MediaQuery::of().size.width;
        let by_window = responsive(width)
            .compact(panel("Compact: one column"))
            .medium(panel("Medium: list beside detail"))
            .expanded(panel("Expanded: three panes"));

        // Built from the box's own width: the same widget, in two boxes of its own size.
        let adaptive = move || {
            LayoutBuilder::new(move |size| -> Box<dyn Widget> {
                if size.width < 220.0 {
                    Box::new(
                        Column::new()
                            .spacing(4.0)
                            .cross_axis_alignment(Align::Start)
                            .child(Text::new("Narrow"))
                            .child(Text::new(format!("{:.0} px", size.width)).size(12.0)),
                    )
                } else {
                    Box::new(
                        Row::new()
                            .spacing(8.0)
                            .child(Text::new("Wide, so side by side"))
                            .child(Text::new(format!("{:.0} px", size.width)).size(12.0)),
                    )
                }
            })
        };
        let frame = |width: f32, child: LayoutBuilder| {
            Container::new()
                .width(width)
                .padding(8.0)
                .radius(8.0)
                .border(1.0, outline)
                // `flex(1.0)` in a row: the builder takes the whole width on offer, so the
                // size it is handed is the room, not the size of what it built.
                .child(Row::new().child(child.flex(1.0)))
        };

        // Portrait or landscape, of this box rather than of the window.
        let shape = |width: f32, height: f32| {
            Container::new()
                .width(width)
                .height(height)
                .child(OrientationBuilder::new(move |orientation| {
                    Container::new()
                        .radius(8.0)
                        .color(fill)
                        .alignment(Alignment::CENTER)
                        .child(
                            Text::new(match orientation {
                                Orientation::Portrait => "Portrait",
                                Orientation::Landscape => "Landscape",
                            })
                            .color(on_fill),
                        )
                }))
        };

        sections(vec![
            Box::new(section(
                format!("responsive({width:.0}) by window width").as_str(),
                by_window,
            )),
            Box::new(section(
                "LayoutBuilder in a 160 px box and a 300 px box",
                Column::new()
                    .spacing(8.0)
                    .cross_axis_alignment(Align::Start)
                    .child(frame(160.0, adaptive()))
                    .child(frame(300.0, adaptive())),
            )),
            Box::new(section(
                "OrientationBuilder",
                Row::new()
                    .spacing(12.0)
                    .child(shape(80.0, 120.0))
                    .child(shape(160.0, 80.0)),
            )),
        ])
    }))
}

//! `Locale` and `Localizations` — the language the interface is in, and the words the
//! framework itself says in it: button labels a screen reader announces, month names in a
//! date picker, "1–10 of 100" under a table, digit grouping.
//!
//! The application states which languages it has and, optionally, the one the reader
//! picked; `locale::of()` and `localizations::of()` answer from anywhere. Your own
//! strings come from your own translation files, chosen by `locale::of()`.

use std::rc::Rc;

use frus::{
    component, host, locale, localizations, Align, Callback, Column, English, French, Locale, Row,
    SegmentedButton, Text, Widget,
};

use crate::common::shared::{section, sections};

pub fn example() -> Box<dyn Widget> {
    Box::new(component(|cx| {
        let scheme = &cx.theme().scheme;
        let current = locale::of();
        let french = current.language_code() == "fr";

        // Switching changes the whole application, on the next frame.
        let picker = SegmentedButton::new(usize::from(french), |index| {
            Callback::new(move || {
                let app = host::app();
                app.set_supported_locales(vec![Locale::new("en"), Locale::new("fr")]);
                if index == 1 {
                    app.set_locale(Some(Locale::new("fr")));
                    app.set_localizations(Some(Rc::new(French)));
                } else {
                    app.set_locale(Some(Locale::new("en")));
                    app.set_localizations(Some(Rc::new(English)));
                }
            })
        })
        .segment("English")
        .segment("Français");

        // The table in force. It always answers: English when nothing is installed.
        let words = localizations::of();
        let months = words.months();
        let lines = [
            ("locale::of()", current.to_string()),
            (
                "ok / cancel",
                format!(
                    "{} / {}",
                    words.ok_button_label(),
                    words.cancel_button_label()
                ),
            ),
            ("back button", words.back_button_label().to_string()),
            ("first months", months[..3].join(", ")),
            ("narrow weekdays", words.narrow_weekdays().join(" ")),
            (
                "page_range_label(1, 10, 1234)",
                words.page_range_label(1, 10, 1234),
            ),
            ("group_digits(1234567)", words.group_digits(1_234_567)),
        ];
        let table = lines.into_iter().fold(
            Column::new()
                .spacing(6.0)
                .cross_axis_alignment(Align::Start),
            |column, (name, value)| {
                column.child(
                    Row::new()
                        .spacing(8.0)
                        .child(Text::new(name).size(12.0).color(scheme.on_surface_variant))
                        .child(Text::new(value)),
                )
            },
        );

        sections(vec![
            Box::new(section("The application's language", picker)),
            Box::new(section("What the framework says", table)),
        ])
    }))
}
